window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s9-734","number":734,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما دلالة حرف الجر ﴿على﴾ في قوله: ﴿بعدت عليهم الشقة﴾؟","answer":"يشعر حرف ﴿على﴾ بثقل السفر واستعلاء مشقته عليهم، فيصور الطريق عبئًا ينوءون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص296، تحت «نكتة التعبير بحرف الجر عليهم»","url":""}]},{"id":"s9-265","number":265,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"لماذا أخبر أنهم سيحلفون بالله قبل أن يقع حلفهم؟","answer":"الإخبار السابق يكشفهم ويحقق صدق الوحي، ويهيئ النبي ﷺ والمؤمنين لأعذارهم المصنوعة عند العودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص298، تحت «بلاغة التعبير بالمستقبل»","url":""}]},{"id":"s9-266","number":266,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما نكتة التعبير بالمحلوف عليه في قولهم: ﴿لو استطعنا لخرجنا معكم﴾؟","answer":"علقوا خروجهم على الاستطاعة ليؤكدوا اعتذارهم ويوهموا أن العجز منعهم لا إرادة التخلف؛ فجاء المحلوف عليه مصوغًا لإحكام عذر مصنوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص300، تحت «نكتة التعبير بالمحلوف عليه»","url":""}]},{"id":"s9-267","number":267,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما معنى ﴿يهلكون أنفسهم﴾ مع أنهم أرادوا بالحلف النجاة؟","answer":"حلفهم الكاذب يوقعهم في الإثم والنفاق والعقوبة، فوسيلة النجاة الظاهرة صارت سبب هلاك النفس الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص301–302، تحت «موقع قوله يهلكون أنفسهم ودلالته»","url":""}]},{"id":"s9-268","number":268,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما بلاغة ختم كلامهم بقوله: ﴿والله يعلم إنهم لكاذبون﴾؟","answer":"تكشف الجملة أن حلفهم لا يستر الحقيقة، وتجعل علم الله محيطًا بكلامهم حال صدوره؛ فيُسجل كذبهم بحكم من يعلم السرائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص302، تحت «بلاغة الختم بالجملة الحالية»","url":""}]},{"id":"s9-735","number":735,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"كيف يتضمن قوله: ﴿والله يعلم إنهم لكاذبون﴾ تعريضًا بالتهديد؟","answer":"إظهار علم الله بكذبهم لا يقتصر على فضحهم، بل يلوح بأنهم واقعون تحت علمه وحسابه وأن هذا الكذب لن يفلت من الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص304، تحت «بلاغة التعريض بالتهديد»","url":""}]},{"id":"s9-269","number":269,"surah":9,"verses":[43],"references":[{"surah":9,"verses":[43]}],"verseLabel":"التوبة: 43","question":"ما دلالة تقديم ﴿عفا الله عنك﴾ على قوله: ﴿لم أذنت لهم﴾؟","answer":"في تقديم العفو إكرام للنبي ﷺ وتلطف في توجيه العتاب، وإيناس قبل بيان الأولى في الإذن. وقد وُجه الافتتاح على الدعاء، ووُجه على الإخبار بالعفو وإن جاء بلفظ الماضي؛ فلا يلزم حصره في الدعاء وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص306، تحت «دلالة موقع الجملة مما قبلها»","url":""}]},{"id":"s9-270","number":270,"surah":9,"verses":[43],"references":[{"surah":9,"verses":[43]}],"verseLabel":"التوبة: 43","question":"ما سرّ التعبير بقوله تعالى: ﴿لم أذنت لهم﴾، ولم يصرح بالفعل الذي أذن لهم في تركه؟","answer":"حُذف متعلق الإذن للعلم به من السياق، أي الإذن في التخلف، فركز التعبير على أصل المبادرة بالإذن قبل التبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص306–307، تحت «بلاغة التعبير بالاستفهام الإنكاري»","url":""}]},{"id":"s9-271","number":271,"surah":9,"verses":[43],"references":[{"surah":9,"verses":[43]}],"verseLabel":"التوبة: 43","question":"لماذا قيل: ﴿يتبين لك الذين صدقوا﴾، وقيل: ﴿وتعلم الكاذبين﴾؟","answer":"الصادقون تظهر دلائل صدقهم في الوقائع والأعمال، فناسبهم التبيّن. أما الكاذبون فحقيقتهم مستترة وراء دعواهم، فلا يكفي ظاهر قولهم، بل يحتاج كشفها إلى علم بما وراءه؛ فناسبهم ﴿تعلم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص308–309، تحت «سر التعبير بالفعل يتبين عن الصادقين وتعلم عن الكاذبين»","url":""}]},{"id":"s9-272","number":272,"surah":9,"verses":[44],"references":[{"surah":9,"verses":[44]}],"verseLabel":"التوبة: 44","question":"لماذا نفى عن المؤمنين أن يستأذنوا في الجهاد بأنفسهم وأموالهم؟","answer":"الإيمان الصادق يدفع إلى الجهاد ولا يحمل صاحبه على طلب الإذن في ترك بذل المال والنفس بلا عذر؛ فالاستئذان علامة على خلل الدافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص312، تحت «بلاغة تنوع متعلق الإذن»","url":""}]},{"id":"s9-273","number":273,"surah":9,"verses":[44],"references":[{"surah":9,"verses":[44]}],"verseLabel":"التوبة: 44","question":"لماذا أعاد الإيمان بالله واليوم الآخر هنا؟","answer":"أعيد الإيمان بالبدء والمعاد لأنهما أصل البذل: الثقة بالله والرجاء في جزاء الآخرة يمنعان الاستئذان في التخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص313، تحت «دلالة تقييد الإيمان بالله واليوم الآخر»","url":""}]},{"id":"s9-274","number":274,"surah":9,"verses":[44],"references":[{"surah":9,"verses":[44]}],"verseLabel":"التوبة: 44","question":"لماذا ختم بـ﴿والله عليم بالمتقين﴾؟","answer":"الخاتمة تقرير لصدق حال المؤمنين وشهادة لهم بالتقوى؛ إذ يعلم الله أن مبادرتهم صادرة عنها. وفيها تنويه بفضلهم وإشعار بأنهم أهل لعظيم الثواب، وليست مجرد وصف لفعل ظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص314، تحت «سر ختم الآية بعلم الله بالمتقين»","url":""}]},{"id":"s9-275","number":275,"surah":9,"verses":[45],"references":[{"surah":9,"verses":[45]}],"verseLabel":"التوبة: 45","question":"لماذا حصر الاستئذان في الذين لا يؤمنون وارتابت قلوبهم؟","answer":"يقصر الاستئذان المذموم هنا على المنافقين الذين لا يؤمنون بالله واليوم الآخر وداخل قلوبهم الريب. فيثبت لهم ما نُفي عن المؤمنين، ويكشف أن طلبهم التخلف نابع من فساد باطنهم وكراهتهم الجهاد، لا من عذر صادق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص317، تحت «بلاغة أسلوب القصر»","url":""}]},{"id":"s9-276","number":276,"surah":9,"verses":[45],"references":[{"surah":9,"verses":[45]}],"verseLabel":"التوبة: 45","question":"لماذا أسند الارتياب إلى القلوب؟","answer":"أُسند الارتياب إلى القلوب لأنها محل الاعتقاد واليقين، فدل على أن التردد نابع من أصل باطن لا عارض سلوكي فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص320، تحت «نكتة إسناد الارتياب إلى القلوب»","url":""}]},{"id":"s9-277","number":277,"surah":9,"verses":[45],"references":[{"surah":9,"verses":[45]}],"verseLabel":"التوبة: 45","question":"ما الصورة في قوله: ﴿فهم في ريبهم يترددون﴾؟","answer":"صُور الريب كحيز يدورون داخله ذهابًا وإيابًا بلا مخرج؛ فالتردد حركة مضطربة لا تنتهي إلى قرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص321، تحت «بلاغة الاستعارة في حرف الجر في»","url":""}]},{"id":"s9-278","number":278,"surah":9,"verses":[45],"references":[{"surah":9,"verses":[45]}],"verseLabel":"التوبة: 45","question":"كيف كنى قوله: ﴿فهم في ريبهم يترددون﴾ عن رسوخ الحيرة؟","answer":"جعلهم في صورة من يتحرك ذهابًا وإيابًا داخل حيز مغلق؛ فالتردد الحسي كناية تمثيلية عن اضطراب لا يهتدي صاحبه إلى قرار أو مخرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص321، تحت «سر التعبير بالكناية في ثوب الاستعارة التمثيلية»","url":""}]},{"id":"s9-279","number":279,"surah":9,"verses":[46],"references":[{"surah":9,"verses":[46]}],"verseLabel":"التوبة: 46","question":"كيف دل جواب الشرط في قوله: ﴿ولو أرادوا الخروج لأعدوا له عدة﴾ على كذب إرادتهم؟","answer":"جعل إعداد العدة لازمًا لصدق الإرادة؛ فلما لم يقع الإعداد مع القدرة انكشف أن دعوى الرغبة في الخروج لا توافق واقعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص324، تحت «سر التعبير بالجواب»","url":""}]},{"id":"s9-280","number":280,"surah":9,"verses":[46],"references":[{"surah":9,"verses":[46]}],"verseLabel":"التوبة: 46","question":"ما دلالة تنكير ﴿عدة﴾ في قوله: ﴿لأعدوا له عدة﴾؟","answer":"يفيد أن المطلوب أصل الاستعداد بحسب القدرة، لا عدة كاملة لا ينقصها شيء. فلو صدقت إرادتهم لظهر منها قدر من الإعداد، ولو قليلًا؛ فالتنكير يكشف انتفاء هذا الدليل على عزمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص325، تحت «سر تنكير المفعول به»","url":""}]},{"id":"s9-281","number":281,"surah":9,"verses":[46],"references":[{"surah":9,"verses":[46]}],"verseLabel":"التوبة: 46","question":"ما بلاغة التعبير بالفعل الماضي في قوله: ﴿ولكن كره الله انبعاثهم فثبطهم﴾؟","answer":"يعرض الماضي كراهة انبعاثهم وتثبيطهم أمرين متحققين؛ فقد حُرموا التوفيق جزاء نفاقهم، ووافق تخلفهم حماية المؤمنين من إفسادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص326، تحت «بلاغة التعبير بالفعل الماضي»","url":""}]},{"id":"s9-282","number":282,"surah":9,"verses":[46],"references":[{"surah":9,"verses":[46]}],"verseLabel":"التوبة: 46","question":"لماذا عبّر عن خروجهم بـ﴿انبعاثهم﴾؟","answer":"الانبعاث أصل الحركة ومبدؤها، فالتعبير به يبين أن الكراهة تناولت ابتداء حركتهم نحو الخروج، قبل أن يبلغوا تمامه. وفيه تصوير لما آلوا إليه من السكون والتثاقل بدل النهوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص326، تحت «سر التعبير بالانبعاث دون الخروج»","url":""}]},{"id":"s9-283","number":283,"surah":9,"verses":[46],"references":[{"surah":9,"verses":[46]}],"verseLabel":"التوبة: 46","question":"لماذا بُني ﴿وقيل اقعدوا مع القاعدين﴾ للمجهول؟","answer":"حذف القائل يفتح الدلالة لوجوه متعددة: وسوسة الشيطان، أو تثبيط بعضهم بعضًا، أو الإذن الذي طلبوه، أو التوبيخ الإلهي. والمقصود إبراز نفاذ القعود فيهم وانقيادهم إليه، مع إيجاز يَسَع هذه الوجوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص327، تحت «نكتة التعبير بالفعل المبني للمفعول»","url":""}]},{"id":"s9-284","number":284,"surah":9,"verses":[47],"references":[{"surah":9,"verses":[47]}],"verseLabel":"التوبة: 47","question":"لماذا فُصل قوله: ﴿لو خرجوا فيكم ما زادوكم إلا خبالًا﴾ عما قبله؟","answer":"جاءت الجملة بيانًا مستقلًا لعلة كراهة انبعاثهم وتثبيطهم: لو خرجوا لنشروا الاضطراب وسعوا بالوشاية والفتنة بين الصفوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص331، تحت «علة فصل قوله لو خرجوا عما قبله»","url":""}]},{"id":"s9-285","number":285,"surah":9,"verses":[47],"references":[{"surah":9,"verses":[47]}],"verseLabel":"التوبة: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿ما زادوكم إلا خبالًا﴾ بصيغة القصر؟","answer":"القصر ينفي كل زيادة خير منهم؛ فلم يكن أثرهم المتوقع إلا الخبال والفساد، دون نفع يوازن ضررهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص332، تحت «بلاغة التعبير بجواب الشرط في ثوب أسلوب القصر»","url":""}]},{"id":"s9-286","number":286,"surah":9,"verses":[47],"references":[{"surah":9,"verses":[47]}],"verseLabel":"التوبة: 47","question":"ما الصورة في قوله: ﴿ولأوضعوا خلالكم﴾؟","answer":"الإيضاع إسراع شديد، و﴿خلالكم﴾ بين صفوفكم؛ فالصورة تعرضهم يسرعون داخل الجيش بالنميمة والتحريض لتفكيكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص333، تحت «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s9-287","number":287,"surah":9,"verses":[47],"references":[{"surah":9,"verses":[47]}],"verseLabel":"التوبة: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿يبغونكم الفتنة﴾، وعدّى البغي إلى المؤمنين؟","answer":"الأصل: يبغون لكم الفتنة؛ فحذف الجار ووصل الفعل بالمفعول مباشرة. وهذا التوجيه يبرز أنهم يقصدون المؤمنين أنفسهم بالسوء ويريدون إيقاع الفتنة فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص334، تحت «فائدة حذف حرف الجر من الفعل»","url":""}]},{"id":"s9-288","number":288,"surah":9,"verses":[47],"references":[{"surah":9,"verses":[47]}],"verseLabel":"التوبة: 47","question":"ما بلاغة تقديم الخبر في قوله: ﴿وفيكم سماعون لهم﴾؟","answer":"يبرز التقديم أن موضع الخطر داخل جماعة المؤمنين نفسها؛ ففيهم من ينقل للمنافقين أو يستجيب لهم، ولذلك كان خروجهم منفذًا للفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص335، تحت «بلاغة تقديم الخبر على المبتدأ»","url":""}]},{"id":"s9-289","number":289,"surah":9,"verses":[47],"references":[{"surah":9,"verses":[47]}],"verseLabel":"التوبة: 47","question":"لماذا ختم بـ﴿والله عليم بالظالمين﴾؟","answer":"العلم بالظالمين يحيط بنفاقهم ومن يستجيب لهم، ويهدد بأن تدبيرهم لا يخفى ولا يفلت من الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص335، تحت «بلاغة التذييل»","url":""}]},{"id":"s9-290","number":290,"surah":9,"verses":[48],"references":[{"surah":9,"verses":[48]}],"verseLabel":"التوبة: 48","question":"ما سر افتتاح خبر سعيهم بالفتنة بحرف التحقيق في قوله: ﴿لقد ابتغوا الفتنة من قبل﴾؟","answer":"يفيد ﴿قد﴾ مع الماضي تحقيق وقوع طلبهم للفتنة، فيقرر أن مكرهم قديم مجرب وأن أعذارهم الجديدة امتداد لسلوك سابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص339، تحت «سر الافتتاح بحرف التحقيق قد»","url":""}]},{"id":"s9-291","number":291,"surah":9,"verses":[48],"references":[{"surah":9,"verses":[48]}],"verseLabel":"التوبة: 48","question":"ما الصورة في قوله: ﴿وقلبوا لك الأمور﴾؟","answer":"صُور تدبيرهم كمن يقلب وجوه الأمر بحثًا عن حيلة تفسده، فيغير الحقائق ويقدم ويؤخر حتى يحقق غرضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص341، تحت «بلاغة الاستعارة أو المجاز»","url":""}]},{"id":"s9-292","number":292,"surah":9,"verses":[48],"references":[{"surah":9,"verses":[48]}],"verseLabel":"التوبة: 48","question":"لماذا قيل: ﴿حتى جاء الحق﴾ بحرف الغاية، لا «إلى أن جاء الحق»؟","answer":"تصور ﴿حتى﴾ امتداد تقليبهم للأمور إلى غاية حاسمة قطعت مكرهم؛ فجاءت الغاية متصلة بالفعل ومبرزة لانتهائه بظهور الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص343، تحت «وجه التعبير بحتى دون إلى»","url":""}]},{"id":"s9-736","number":736,"surah":9,"verses":[48],"references":[{"surah":9,"verses":[48]}],"verseLabel":"التوبة: 48","question":"ما علة التعبير عن ظهور الحق بقوله: ﴿جاء الحق﴾؟","answer":"صُور الحق كأنه آتٍ بنفسه بعد انتظار، فلما جاء انكشف الباطل وظهر أمر الله رغم كراهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص343، تحت «علة التعبير عن مجيء الحق وظهور أمر الله بجاء»","url":""}]},{"id":"s9-293","number":293,"surah":9,"verses":[48],"references":[{"surah":9,"verses":[48]}],"verseLabel":"التوبة: 48","question":"ما دلالة التعبير بفعل المجيء في قوله: ﴿حتى جاء الحق﴾؟","answer":"في المجيء تصوير لوصول الحق وتحققه رغم شدة محاولات المنافقين إبطال الرسالة؛ فكأن سعيهم إلى منعه انتهى بخيبة، وقد ظهر واستقر. ويؤكد التعبير بالماضي تحقق هذا المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص343–344، تحت «نكتة التعبير بفعل المجيء جاء دون أتى»","url":""}]},{"id":"s9-294","number":294,"surah":9,"verses":[49],"references":[{"surah":9,"verses":[49]}],"verseLabel":"التوبة: 49","question":"ما دلالة تعريف ﴿الفتنة﴾ في قول المنافق: ﴿ولا تفتني﴾؟","answer":"عرّف الفتنة التي زعم أنه يخشاها كأنها أمر معلوم متعين، ليجعل الخروج سببًا مباشرًا لها ويقيم من هذا الزعم ذريعة للتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص352، تحت «دلالة تعريف لفظ الفتنة»","url":""}]},{"id":"s9-295","number":295,"surah":9,"verses":[49],"references":[{"surah":9,"verses":[49]}],"verseLabel":"التوبة: 49","question":"لماذا جاء الرد: ﴿ألا في الفتنة سقطوا﴾؟","answer":"الرد يقلب حجته عليه: الفتنة التي فر منها بزعمِه هي عين النفاق والمعصية التي وقع فيها بطلب التخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص353، تحت «دلالة استعمال الدليل المستدل به للنقض من باب قلب النكتة»","url":""}]},{"id":"s9-296","number":296,"surah":9,"verses":[49],"references":[{"surah":9,"verses":[49]}],"verseLabel":"التوبة: 49","question":"لماذا عبّر بـ﴿سقطوا﴾ في الفتنة؟","answer":"السقوط يصور الفتنة حفرة هوى فيها من غير قدرة على الخلاص، وهو أبلغ من مجرد الدخول فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص352، تحت «إيثار التعبير بلفظ سقطوا»","url":""}]},{"id":"s9-297","number":297,"surah":9,"verses":[49],"references":[{"surah":9,"verses":[49]}],"verseLabel":"التوبة: 49","question":"لماذا افتتحت الجملة بـ﴿ألا﴾؟","answer":"﴿ألا﴾ أداة تنبيه واستفتاح تلفت السمع إلى الحقيقة المخالفة لدعواه وتحقق وقوعه في الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص350، تحت «فائدة التصدير بألا»","url":""}]},{"id":"s9-298","number":298,"surah":9,"verses":[49],"references":[{"surah":9,"verses":[49]}],"verseLabel":"التوبة: 49","question":"كيف تُفهم إحاطة جهنم بالكافرين بين الحقيقة والمجاز؟","answer":"إحاطتها بهم يوم القيامة حقيقة محققة لا مهرب منها، ونُزل المستقبل منزلة الحال لشدة اليقين؛ وذُكر وجه مجازي بأن أسبابها وأعمالها المفضية إليها قد أحاطت بهم الآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص353، تحت «نكتة لفظ المحيطة بين المجاز والحقيقة»","url":""}]},{"id":"s9-737","number":737,"surah":9,"verses":[49],"references":[{"surah":9,"verses":[49]}],"verseLabel":"التوبة: 49","question":"ما دلالة صيغة اسم الفاعل في قوله: ﴿وإن جهنم لمحيطة بالكافرين﴾؟","answer":"تصور صيغة اسم الفاعل الإحاطة وصفًا ثابتًا محققًا، فتجعل الوعيد حاضرًا مستمرًا وتقطع رجاء الإفلات منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص356، تحت «دلالة صيغة اسم الفاعل»","url":""}]},{"id":"s9-299","number":299,"surah":9,"verses":[50],"references":[{"surah":9,"verses":[50]}],"verseLabel":"التوبة: 50","question":"كيف يُوجَّه بلاغيًا المقابلة بين جملتي الشرط في قوله تعالى: ﴿إن تصبك حسنة تسؤهم وإن تصبك مصيبة يقولوا قد أخذنا أمرنا﴾؟","answer":"تكشف الجملة أن المنافقين يتأذون بما يصيب النبي ﷺ والمؤمنين من خير، ويفرحون بالمصيبة زاعمين أنهم احتاطوا لأنفسهم؛ فهي تصور انقلاب موازينهم وفساد سرائرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص360، تحت «توجيه المقابلة بين جملتي الشرط»","url":""}]},{"id":"s9-300","number":300,"surah":9,"verses":[50],"references":[{"surah":9,"verses":[50]}],"verseLabel":"التوبة: 50","question":"لماذا اختير ﴿تصبك﴾ للحسنة والمصيبة معًا؟","answer":"تستعمل الإصابة في الخير والشر، وتوحي ببلوغ الأثر وتمكنه ممن وقع عليه. فناسبت الحسنة والمصيبة جميعًا، وأبرزت قوة تأثر المنافقين بما ينال المؤمنين من ظفر أو شدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص359، تحت «إيثار التعبير بلفظ الإصابة دون المس»","url":""}]},{"id":"s9-301","number":301,"surah":9,"verses":[50],"references":[{"surah":9,"verses":[50]}],"verseLabel":"التوبة: 50","question":"لماذا نكرت ﴿حسنة﴾ و﴿مصيبة﴾؟","answer":"يوجه المصدر التنكير إلى التقليل: حتى أدنى حسنة للمؤمنين تسوء المنافقين، وأدنى مصيبة تصيبهم تفرحهم. فهو يكشف شدة حسدهم وشماتتهم وتأثرهم بأقل ما يقع من ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص359–360، تحت «وجه التعبير بلفظي الحسنة والمصيبة وتنكيرهما»","url":""}]},{"id":"s9-302","number":302,"surah":9,"verses":[50],"references":[{"surah":9,"verses":[50]}],"verseLabel":"التوبة: 50","question":"ما وجه البلاغة في الاستعارة في قوله تعالى: ﴿قد أخذنا أمرنا من قبل﴾؟","answer":"معناه أنهم يزعمون أنهم أخذوا حذرهم ودبروا أمرهم قبل وقوع المصيبة، فلم يخرجوا مع المؤمنين؛ وفيه إظهار عجبهم برأيهم وشماتتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص361، تحت «بلاغة الاستعارة»","url":""}]},{"id":"s9-303","number":303,"surah":9,"verses":[50],"references":[{"surah":9,"verses":[50]}],"verseLabel":"التوبة: 50","question":"ما النكتة البلاغية في إيثار لفظ ويتولوا في قوله تعالى: ﴿ويتولوا وهم فرحون﴾؟","answer":"يجمع التعبير بين انصرافهم الظاهر وفرحهم الباطن بمصيبة المؤمنين؛ فعُطف التولي على مقالتهم، ثم جاءت الواو للحال والجملة الاسمية لتصور الفرح وصفًا ملازمًا لهم حين ينصرفون.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص361، تحت «نكتة إيثار لفظ ويتولوا»","url":""}]},{"id":"s9-304","number":304,"surah":9,"verses":[51],"references":[{"surah":9,"verses":[51]}],"verseLabel":"التوبة: 51","question":"لماذا جاء الرد بالأمر: ﴿قل لن يصيبنا إلا ما كتب الله لنا﴾؟","answer":"جاء الأمر بـ﴿قل﴾ لتلقين المؤمنين الرد الذي يبطل شماتة المنافقين: لا يقع شيء خارج تقدير الله، وما قدره لعباده المؤمنين فمآله إلى الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص366، تحت «وجه الافتتاح بفعل الأمر قل»","url":""}]},{"id":"s9-738","number":738,"surah":9,"verses":[51],"references":[{"surah":9,"verses":[51]}],"verseLabel":"التوبة: 51","question":"لماذا قيل: ﴿ما كتب الله لنا﴾ باللام، لا «علينا»؟","answer":"اللام تشعر بأن ما يقدره الله للمؤمنين مآله إلى نفعهم: نصرًا في الدنيا أو أجرًا وشهادة، فلا يرون قضاءه عبئًا محضًا عليهم، بل خيرًا مكتوبًا لهم في العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص369، تحت «سر التعبير بقوله لنا ودلالة اللام»","url":""}]},{"id":"s9-305","number":305,"surah":9,"verses":[51],"references":[{"surah":9,"verses":[51]}],"verseLabel":"التوبة: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿كتب الله لنا﴾ لا «علينا» مع احتمال المصيبة؟","answer":"قال ﴿لنا﴾ لأن ما يقدره الله للمؤمنين خير لهم في العاقبة، نصرًا أو شهادة وأجرًا؛ فالمصيبة في ظاهرها تنتهي إلى منفعة إيمانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص369، تحت «سر التعبير بقوله لنا ودلالة اللام»","url":""}]},{"id":"s9-306","number":306,"surah":9,"verses":[51],"references":[{"surah":9,"verses":[51]}],"verseLabel":"التوبة: 51","question":"لماذا وصف الله بأنه ﴿مولانا﴾ في هذا المقام؟","answer":"﴿مولانا﴾ تفيد الولاية والنصرة والتدبير؛ فمن تولاه الله لم يجزع من تقديره ولم يركن إلى احتياط المنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص369، تحت «بلاغة الفصل في جملة هو مولانا»","url":""}]},{"id":"s9-308","number":308,"surah":9,"verses":[52],"references":[{"surah":9,"verses":[52]}],"verseLabel":"التوبة: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿هل تربصون بنا إلا إحدى الحسنيين﴾، فسمّى النصر والشهادة حسنيين؟","answer":"النصر حسن لما فيه من الظفر، والشهادة حسنى لما فيها من الثواب؛ فالمؤمن بين عاقبتين محبوبتين لا موضع فيهما لشماتة المنافق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص379، تحت «بيان وجه الأحسنية بين المصيرين»","url":""}]},{"id":"s9-309","number":309,"surah":9,"verses":[52],"references":[{"surah":9,"verses":[52]}],"verseLabel":"التوبة: 52","question":"لماذا قيل: ﴿إلا إحدى الحسنيين﴾؟","answer":"حصر انتظار المؤمنين في واحدة من عاقبتين كلتاهما حسنى: النصر أو الشهادة. فأفردت ﴿إحدى﴾ لأنها النتيجة الواقعة، وثُنّيت ﴿الحسنيين﴾ لأن الاختيار واقع بين مصيرين كلاهما خير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص378، تحت «بلاغة الاستثناء»","url":""}]},{"id":"s9-310","number":310,"surah":9,"verses":[52],"references":[{"surah":9,"verses":[52]}],"verseLabel":"التوبة: 52","question":"لماذا قابل انتظار المؤمنين إحدى الحسنيين بانتظار عذاب المنافقين؟","answer":"المؤمن ينتظر خيرًا في كلتا الحالين، أما المنافق فينتظره عذاب من الله أو عقوبة بأيدي المؤمنين؛ فالمقابلة تقلب التربص على صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص378، تحت «علة الإتيان بأداة الحصر مع الحسنيين دون الإصابة»","url":""}]},{"id":"s9-311","number":311,"surah":9,"verses":[52],"references":[{"surah":9,"verses":[52]}],"verseLabel":"التوبة: 52","question":"كيف يُوجَّه بلاغيًا إضافة العذاب إليه تعالى في قوله تعالى: ﴿بعذاب من عنده أو بأيدينا﴾؟","answer":"﴿من عنده﴾ عذاب ينزله الله من غير مباشرة المؤمنين، و﴿بأيدينا﴾ عقوبة يجريها على أيديهم. والعطف بـ﴿أو﴾ يستوعب وجهي العقوبة المحتملين، فيكتمل به التهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص382، تحت «توجيه إضافة العذاب إليه تعالى»","url":""}]},{"id":"s9-312","number":312,"surah":9,"verses":[52],"references":[{"surah":9,"verses":[52]}],"verseLabel":"التوبة: 52","question":"لماذا ختم بقوله: ﴿فتربصوا إنا معكم متربصون﴾؟","answer":"الأمر للتهديد لا للإباحة؛ أي استمروا في انتظاركم، فنحن ننتظر لكم إحدى العقوبتين، وستظهر عاقبة كل فريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص383، تحت «دلالة الفاء في فتربصوا»","url":""}]},{"id":"s9-313","number":313,"surah":9,"verses":[53],"references":[{"surah":9,"verses":[53]}],"verseLabel":"التوبة: 53","question":"لماذا أمرهم بالإنفاق طوعًا أو كرهًا ثم حكم بأنه لن يتقبل منهم؟","answer":"الأمر للتسوية والتهديد: أنفقوا مختارين أو مكرهين، فلن ينفعكم الإنفاق؛ لأن فقد الإيمان أفسد أساس القبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص388، تحت «توجيه التعبير بالأمر أنفقوا»","url":""}]},{"id":"s9-314","number":314,"surah":9,"verses":[53],"references":[{"surah":9,"verses":[53]}],"verseLabel":"التوبة: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿أنفقوا طوعًا أو كرهًا﴾ بصيغة الأمر؟","answer":"صيغة الأمر ليست طلبًا مقصودًا للإنفاق، بل تفيد التسوية بين حالتي الطوع والكره في عدم القبول، وفيها إهانة وقطع لأطماعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص388، تحت «توجيه التعبير بالأمر أنفقوا»","url":""}]},{"id":"s9-315","number":315,"surah":9,"verses":[53],"references":[{"surah":9,"verses":[53]}],"verseLabel":"التوبة: 53","question":"لماذا بُني ﴿لن يتقبل منكم﴾ للمجهول؟","answer":"حذف الفاعل لأن المقصود إبراز النتيجة، وهي انتفاء القبول قطعًا، لا بيان مَن يتقبل؛ والفاعل معلوم من المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص392، تحت «غرض نفي التقبل والتعبير عنه بالمبني للمجهول»","url":""}]},{"id":"s9-316","number":316,"surah":9,"verses":[53],"references":[{"surah":9,"verses":[53]}],"verseLabel":"التوبة: 53","question":"لماذا علل عدم القبول بقوله: ﴿إنكم كنتم قومًا فاسقين﴾؟","answer":"تفصل الجملة عما قبلها لتقرر علة مستقلة: فالفسق خروج راسخ عن طاعة الله، ولفظ ﴿كنتم﴾ يدل على تمكن هذا الوصف منهم. واختيار ﴿فاسقين﴾ يجمع كفرهم وآثاره العملية من كسل وكراهة للإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص392، تحت «وجه الفصل في جملة الفاصلة»","url":""}]},{"id":"s9-317","number":317,"surah":9,"verses":[54],"references":[{"surah":9,"verses":[54]}],"verseLabel":"التوبة: 54","question":"ما مناسبة الآية لما قبلها في قوله تعالى: ﴿وما منعهم أن تقبل منهم نفقاتهم إلا أنهم كفروا﴾؟","answer":"يحصر الأسلوب أسباب رد نفقاتهم فيما بينته الآية: الكفر بالله ورسوله، وإتيان الصلاة بكسل، والإنفاق بكراهة. والكفر أصل هذه الحال، ثم يكشف عطف العملين أثره في عبادتهم وافتقاد الإخلاص فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص396، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-318","number":318,"surah":9,"verses":[54],"references":[{"surah":9,"verses":[54]}],"verseLabel":"التوبة: 54","question":"لماذا أعيد نفي القبول بعد الآية السابقة؟","answer":"جاء النفي الأول حكمًا مجملًا بعدم قبول النفقة، ثم أعيد هنا ليُفصَّل سببه: الكفر، والكسل في الصلاة، والإنفاق مع الكراهة. فالإعادة تعليل بعد إجمال وليست تكرارًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص396، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-319","number":319,"surah":9,"verses":[54],"references":[{"surah":9,"verses":[54]}],"verseLabel":"التوبة: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يأتون الصلاة إلا وهم كسالى﴾، دون أن يقال: «لا يصلون إلا بكسل»؟","answer":"اختيار ﴿يأتون الصلاة﴾ يصور مجيئهم إليها بأجسادهم من غير رغبة قلبية، ويستحضر المضارع تجدد المشهد، ثم تجعل الحال الاسمية ﴿وهم كسالى﴾ الكسل هيئة ظاهرة ملازمة لهم كلما أتوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص401، تحت «إيثار لفظ ولا يأتون»","url":""}]},{"id":"s9-320","number":320,"surah":9,"verses":[54],"references":[{"surah":9,"verses":[54]}],"verseLabel":"التوبة: 54","question":"لماذا جمع بين الكسل في الصلاة وكراهة الإنفاق؟","answer":"جمعهما لأن الصلاة والإنفاق أبرز العبادات البدنية والمالية؛ وكسلهم في الأولى وكراهتهم للثانية يكشفان خلو العمل من الإيمان والإخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص400، تحت «دلالة عطف أعمالهم بالواو»","url":""}]},{"id":"s9-321","number":321,"surah":9,"verses":[54],"references":[{"surah":9,"verses":[54]}],"verseLabel":"التوبة: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا ينفقون إلا وهم كارهون﴾ بجملة اسمية حالية؟","answer":"الجملة الاسمية الحالية تصور الكراهة وصفًا ثابتًا مصاحبًا لكل إنفاق منهم، لا خاطرًا عابرًا يقع مرة دون أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص402، تحت «وجه التعبير عن الإنفاق بالمضارع»","url":""}]},{"id":"s9-322","number":322,"surah":9,"verses":[55],"references":[{"surah":9,"verses":[55]}],"verseLabel":"التوبة: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تعجبك أموالهم ولا أولادهم﴾ مع أن المال والولد نعم؟","answer":"النهي عن الإعجاب ليس لأنهما ليسا نعمة في ذاتهما، بل لأنهما صارا في حق المنافقين وسيلة تعب وعقوبة في الدنيا ثم يموتون على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص406، تحت «دلالة الفاء وأثرها في فلا تعجبك»","url":""}]},{"id":"s9-324","number":324,"surah":9,"verses":[55],"references":[{"surah":9,"verses":[55]}],"verseLabel":"التوبة: 55","question":"ما وجه كون أموال المنافقين وأولادهم عذابًا لهم في الحياة الدنيا؟","answer":"عذابهم بهما يكون بما يلاقونه في تحصيلهما وحفظهما والخوف عليهما، وبما يكلفون من الإنفاق مع الكراهة، وبما يصيبهم فيهما من الآفات والأحزان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص410، تحت «معنى الباء في بها»","url":""}]},{"id":"s9-739","number":739,"surah":9,"verses":[55],"references":[{"surah":9,"verses":[55]}],"verseLabel":"التوبة: 55","question":"ما أثر تقديم قيد ﴿في الحياة الدنيا﴾ في سياق الآية؟","answer":"يحدد القيد أن تعذيبهم بالأموال والأولاد يقع في الدنيا، ثم ينتقل الكلام إلى مآل آخر هو خروج أرواحهم على الكفر؛ فيتميز عذاب الحياة من سوء الخاتمة مع اتصال أحدهما بالآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص411، تحت «نكتة التقديم والتأخير في الحياة الدنيا»","url":""}]},{"id":"s9-325","number":325,"surah":9,"verses":[55],"references":[{"surah":9,"verses":[55]}],"verseLabel":"التوبة: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿وتزهق أنفسهم﴾، دون أن يقال: «ويموتوا»؟","answer":"الزهوق يصور مفارقة النفس للجسد بشدة وضيق، فيناسب ذكر عذابهم وتعلقهم بأموالهم وأولادهم، وهو أخص في هذا السياق من مجرد الإخبار بالموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص412، تحت «بلاغة الكناية في وتزهق أنفسهم»","url":""}]},{"id":"s9-326","number":326,"surah":9,"verses":[55],"references":[{"surah":9,"verses":[55]}],"verseLabel":"التوبة: 55","question":"لماذا ختم بـ﴿وهم كافرون﴾؟","answer":"الحال ﴿وهم كافرون﴾ تبين أخطر مآل للعذاب الدنيوي: أن تنتهي حياتهم من غير توبة، فيتصل عذاب الدنيا بعذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص413، تحت «معنى الواو في قوله وهم كافرون»","url":""}]},{"id":"s9-327","number":327,"surah":9,"verses":[56],"references":[{"surah":9,"verses":[56]}],"verseLabel":"التوبة: 56","question":"لماذا يحلف المنافقون: ﴿إنهم لمنكم﴾ ثم ينفي الله ذلك؟","answer":"يحلفون طلبًا للسلامة واتقاءً لانكشافهم، فنفى الله انتسابهم الحقيقي إلى المؤمنين؛ إذ جمعتهم الظواهر وفرقتهم العقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص419، تحت «غرض تتابع المؤكدات في إنهم لمنكم»","url":""}]},{"id":"s9-328","number":328,"surah":9,"verses":[56],"references":[{"surah":9,"verses":[56]}],"verseLabel":"التوبة: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكنهم قوم يفرقون﴾، دون أن يقال: «يخافون»؟","answer":"﴿يفرقون﴾ أبلغ من مطلق الخوف؛ فهو خوف شديد مستمر يحملهم على الحلف والتستر والهرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص420، تحت «نكتة مادة الفرق والمضارعة»","url":""}]},{"id":"s9-329","number":329,"surah":9,"verses":[56],"references":[{"surah":9,"verses":[56]}],"verseLabel":"التوبة: 56","question":"ما دلالة حذف متعلق الخوف في قوله: ﴿ولكنهم قوم يفرقون﴾؟","answer":"يعمم الحذف حال خوفهم ويجعلها وصفًا يلازمهم، بدل حصرها في مخوف واحد. ومن دواعيها خوف انكشاف نفاقهم وما يترتب عليه، فدفعتهم هذه الحال إلى التستر بالأيمان وإظهار الموافقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص421، تحت «فائدة حذف متعلق يفرقون»","url":""}]},{"id":"s9-330","number":330,"surah":9,"verses":[57],"references":[{"surah":9,"verses":[57]}],"verseLabel":"التوبة: 57","question":"لماذا عدّد الملجأ والمغارات والمدخل؟","answer":"عُددت لتصوير شدة نفورهم واستقصاء كل مكان يمكن أن يحجبهم: ملجأ يحمي، أو مغارات تستر، أو مدخل ينفذون فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص424، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-331","number":331,"surah":9,"verses":[57],"references":[{"surah":9,"verses":[57]}],"verseLabel":"التوبة: 57","question":"ما الفرق التصويري بين ﴿ملجأ﴾ و﴿مغارات﴾ و﴿مدخلًا﴾؟","answer":"الملجأ مكان يتحصنون به، والمغارات تجاويف الجبال، والمدخل موضع ضيق ينفذون فيه أو سرداب؛ فتتنوع الصورة من الاحتماء إلى الاختباء والانحشار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص427، تحت «فائدة الترتيب بين الملاذات الثلاثة»","url":""}]},{"id":"s9-740","number":740,"surah":9,"verses":[57],"references":[{"surah":9,"verses":[57]}],"verseLabel":"التوبة: 57","question":"لماذا أُفرد ﴿ملجأ﴾ و﴿مدخلًا﴾ وجُمعت ﴿مغارات﴾؟","answer":"جاء ﴿ملجأ﴾ و﴿مدخلًا﴾ بصيغة الجنس، فيصدق كل منهما على الواحد والكثير، أما جمع ﴿مغارات﴾ فيستحضر تعدد تجاويف الجبال التي قد يختبئون فيها؛ فتتنوع صورة فرارهم وتتسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص428، تحت «نكتة إفراد ملجأ ومدخلًا وجمع مغارات»","url":""}]},{"id":"s9-332","number":332,"surah":9,"verses":[57],"references":[{"surah":9,"verses":[57]}],"verseLabel":"التوبة: 57","question":"ما معنى اللام في لولوا إليه في قوله تعالى: ﴿لولوا إليه وهم يجمحون﴾؟","answer":"﴿لولوا إليه﴾ تفيد سرعة الانصراف نحوه، و﴿يجمحون﴾ تصور اندفاعًا لا يملكون رده كجموح الدابة؛ مبالغة في فرارهم من المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص428، تحت «معنى اللام في لولوا إليه»","url":""}]},{"id":"s9-333","number":333,"surah":9,"verses":[58],"references":[{"surah":9,"verses":[58]}],"verseLabel":"التوبة: 58","question":"لماذا عبّر عن الطعن في قسمة الصدقات بقوله: ﴿يلمزك﴾؟","answer":"اللمز طعن خفي يعيب صاحبه غيره قولًا أو إشارة، واختيار المضارع ﴿يلمزك﴾ يصور تجدد طعنهم في النبي ﷺ كلما قسمت الصدقات، فيكشف أن اعتراضهم عادة نفعية لا طلبًا للعدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص434، تحت «فائدة التعبير بالمضارع في من يلمزك»","url":""}]},{"id":"s9-334","number":334,"surah":9,"verses":[58],"references":[{"surah":9,"verses":[58]}],"verseLabel":"التوبة: 58","question":"لماذا كرر الشرطين: ﴿فإن أعطوا منها رضوا وإن لم يعطوا منها إذا هم يسخطون﴾؟","answer":"فصل الشرطان ميزانهم النفعي: الرضا تابع للأخذ، والسخط تابع للحرمان؛ فلا يحكمهم حق ولا عدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص435، تحت «فائدة التعبير بالجملة الشرطية»","url":""}]},{"id":"s9-335","number":335,"surah":9,"verses":[58],"references":[{"surah":9,"verses":[58]}],"verseLabel":"التوبة: 58","question":"لماذا جاءت المفاجأة بـ﴿إذا هم يسخطون﴾؟","answer":"﴿إذا﴾ الفجائية تصور سرعة انقلابهم إلى السخط بمجرد عدم العطاء، من غير تروٍّ أو نظر في حكمة القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص438، تحت «معنى إذا الفجائية في إذا هم يسخطون»","url":""}]},{"id":"s9-336","number":336,"surah":9,"verses":[58],"references":[{"surah":9,"verses":[58]}],"verseLabel":"التوبة: 58","question":"ما سرّ التعبير في قوله تعالى: ﴿هم يسخطون﴾ بالجملة الاسمية؟","answer":"الجملة الاسمية تفيد ثبات السخط واستقراره فيهم عند الحرمان. و﴿هم﴾ مبتدأ، وجملة ﴿يسخطون﴾ خبره؛ فتكرار إسناد السخط إليهم، بالضمير المنفصل ثم ضمير الفعل، يزيد توكيد هذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص438، تحت «موقع جملة هم يسخطون في سياق الآية الكريمة»","url":""}]},{"id":"s9-337","number":337,"surah":9,"verses":[59],"references":[{"surah":9,"verses":[59]}],"verseLabel":"التوبة: 59","question":"ما دلالة عرض الحال المفترضة بقوله: ﴿ولو أنهم رضوا ما آتاهم الله ورسوله﴾؟","answer":"عرضت الآية الحال التي كان ينبغي أن يكونوا عليها: الرضا بالقسمة والتوكل على الله والرغبة إليه، وفي ذلك تقريع على نقيض فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص440، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-338","number":338,"surah":9,"verses":[59],"references":[{"surah":9,"verses":[59]}],"verseLabel":"التوبة: 59","question":"لماذا نسب الإيتاء إلى الله ورسوله، ثم قال: ﴿وقالوا حسبنا الله﴾؟","answer":"نسب الإيتاء إلى الله ورسوله لأن الله هو المقدِّر والرسول ﷺ هو المباشر للقسمة بأمره، أما الكفاية والفضل فمن الله وحده فقالوا: ﴿حسبنا الله﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص443، تحت «فائدة عطف لفظ ورسوله على لفظ الجلالة»","url":""}]},{"id":"s9-339","number":339,"surah":9,"verses":[59],"references":[{"surah":9,"verses":[59]}],"verseLabel":"التوبة: 59","question":"لماذا تكرر ذكر الله في الآية ولم يكتف بالضمائر؟","answer":"يُظهر تكرار الاسم الجليل تعلق الكفاية والفضل والرغبة بالله، ويجدد تعظيمه في كل مقام؛ فذُكر صراحة عند الثقة بكفايته، وإضافة الفضل إليه، وقصر الرغبة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص444، تحت «معنى قوله تعالى وقالوا حسبنا الله»","url":""}]},{"id":"s9-741","number":741,"surah":9,"verses":[59],"references":[{"surah":9,"verses":[59]}],"verseLabel":"التوبة: 59","question":"ما دلالة تقديم ﴿إلى الله﴾ في قوله: ﴿إنا إلى الله راغبون﴾؟","answer":"تقديم الجار والمجرور يفيد العناية والقصر؛ أي إن رغبتهم متجهة إلى الله وحده، لا إلى العطاء نفسه ولا إلى أحد من الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص447، تحت «غرض تقديم شبه الجملة»","url":""}]},{"id":"s9-340","number":340,"surah":9,"verses":[59],"references":[{"surah":9,"verses":[59]}],"verseLabel":"التوبة: 59","question":"ما دلالة الجمع بين ﴿حسبنا الله﴾ و﴿إنا إلى الله راغبون﴾؟","answer":"﴿حسبنا الله﴾ إقرار بالكفاية وتفويض وتوكل عليه، و﴿إنا إلى الله راغبون﴾ بيان لتوجه الرغبة إليه وحده. فتجتمع الثقة بفضله مع صدق الطلب منه والرضا بما يقسمه، وهي الحال التي كان ينبغي أن يقولوا بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص444، تحت «معنى قوله تعالى وقالوا حسبنا الله»","url":""}]},{"id":"s9-341","number":341,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"لماذا افتتحت آية المصارف بـ﴿إنما الصدقات﴾؟","answer":"﴿إنما﴾ تقصر الصدقات على الأصناف المذكورة، فترد اعتراض من يطلبها لغير استحقاق وتبين أن قسمتها حكم شرعي لا هوى شخصيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص448، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-342","number":342,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"لماذا سُمّيت الزكاة هنا ﴿الصدقات﴾؟","answer":"يذكر المصدر أن تسميتها صدقة تربط بذلها بصدق وعد الله للإنسان حين جعله خليفة في المال؛ فهي مما يؤديه شكرًا لما رزقه الله. والمؤمن يلتزم بها طاعةً، فتسند حاجات غير القادرين إلى ما أعطيه القادرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص451، تحت «نكتة التعبير عن الزكاة بلفظ الصدقات»","url":""}]},{"id":"s9-343","number":343,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"لماذا بدأ بالفقراء ثم المساكين؟","answer":"من توجيهات الترتيب تقديم الأهم في حاجة المعونة؛ فالفقراء والمساكين أحق من غيرهم بهذه الصدقات وهم المقصودون أولًا بذاتها. ويعلل المصدر تقديم الفقراء على هذا الوجه بكونهم أشد حاجة، دون جعل ذلك حسمًا لجميع الخلاف في حد الفقير والمسكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص456، تحت «بلاغة الترتيب بين الأصناف الثمانية»","url":""}]},{"id":"s9-344","number":344,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"ما سرّ التعبير في قوله تعالى في الأصناف الأربعة الأولى باللام، ثم قال: ﴿وفي الرقاب والغارمين وفي سبيل الله﴾ بـ﴿في﴾؟","answer":"من وجوهه أن اللام تناسب تمليك الأصناف الأولى ما يعطَون، وأن ﴿في﴾ تناسب صرف المال في الجهات المذكورة بعدها. وفي العدول أيضًا تصوير لشدة استحقاق هذه الجهات حتى كأنها أوعية توضع فيها الصدقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص452، تحت «معنى اللام في للفقراء»","url":""}]},{"id":"s9-345","number":345,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿المؤلفة قلوبهم﴾ بالبناء للمجهول؟","answer":"حذف فاعل التأليف للعلم به في هذا التوجيه؛ فالله هو الذي يؤلف القلوب. ووجه البناء العناية إلى صفة تأليفها واجتماعها، مع الإيجاز وعدم الحاجة إلى إعادة تسمية الفاعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص453، تحت «نكتة بناء والمؤلفة قلوبهم»","url":""}]},{"id":"s9-346","number":346,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"لماذا أفرد ﴿ابن السبيل﴾ مع جمع بقية الأصناف؟","answer":"﴿ابن السبيل﴾ اسم جنس يصدق على كل مسافر انقطع به الطريق، وإفراده يرسم شدة ملازمته للسبيل كأنه ابنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص455، تحت «نكتة إفراد ابن السبيل»","url":""}]},{"id":"s9-347","number":347,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"لماذا ختم تعداد المصارف بقوله: ﴿فريضة من الله﴾؟","answer":"﴿فريضة من الله﴾ تؤكد أن تحديد المصارف حكم واجب صادر من الله، فلا مدخل فيه لأهواء المعترضين أو اجتهاد في نقلها إلى غير أهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص457، تحت «معنى من في من الله»","url":""}]},{"id":"s9-348","number":348,"surah":9,"verses":[60],"references":[{"surah":9,"verses":[60]}],"verseLabel":"التوبة: 60","question":"ما نكتة التذييل بـ﴿والله عليم حكيم﴾ بعد بيان مصارف الصدقات؟","answer":"﴿عليم﴾ بأحوال المستحقين وحاجاتهم، و﴿حكيم﴾ في توزيع المال بينهم؛ فالخاتمة تعلل دقة القسمة وعدلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص457، تحت «نكتة التذييل بعليم حكيم»","url":""}]},{"id":"s9-349","number":349,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"لماذا عبّر عن إيذاء النبي ﷺ بقوله: ﴿ومنهم الذين يؤذون النبي﴾ دون ذكر نوع الأذى؟","answer":"أُطلق الأذى ليشمل أقوالهم وأفعالهم كلها، وليدل على تجدد أذاهم، ثم خُص من أقوالهم طعنهم فيه بقولهم: ﴿هو أذن﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص461، تحت «نكتة التعبير بالمضارعة في جملة صلة الموصول يؤذون»","url":""}]},{"id":"s9-350","number":350,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"لماذا وصفه المنافقون بقولهم: ﴿هو أذن﴾؟","answer":"قصدوا أنه يسمع كل ما يقال ويصدقه، فحولوا خلقه في الحلم وحسن الاستماع إلى مطعن يتهمونه به.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص462، تحت «بلاغة الكناية والمجاز المرسل في قوله هو أذن»","url":""}]},{"id":"s9-351","number":351,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"لماذا جاء الرد: ﴿قل أذن خير لكم﴾، فأبقى اللفظ نفسه؟","answer":"أبقى لفظهم وقيده بالخير، فقلب الذم مدحًا: هو أذن فيما ينفعكم، يسمع الوحي والحق ويقبل منكم ظاهر الاعتذار رحمة وحلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص464، تحت «نكتة الفصل في قل أذن خير لكم»","url":""}]},{"id":"s9-352","number":352,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"لماذا أضيفت ﴿أذن﴾ إلى ﴿خير﴾؟","answer":"إضافة ﴿أذن﴾ إلى ﴿خير﴾ تخصص سماعه بما هو خير لهم، وتنفي زعمهم أنه يقبل كل باطل بلا تمييز.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص465، تحت «بلاغة الأسلوب الحكيم في قوله قل أذن خير لكم»","url":""}]},{"id":"s9-353","number":353,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"لماذا فرّق بين ﴿يؤمن بالله﴾ و﴿يؤمن للمؤمنين﴾؟","answer":"عُدّي الإيمان بالله بالباء لأنه تصديق جازم به، وعُدّي الإيمان للمؤمنين باللام لأن المراد تصديق أخبارهم والثقة بهم وقبول قولهم؛ فاختلاف الحرفين يميز حقيقة الإيمان بالله من حسن الاستماع للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص465، تحت «نكتة مجيء يؤمن بالله»","url":""}]},{"id":"s9-354","number":354,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿ورحمة للذين آمنوا منكم﴾، فقيد الرحمة بالمؤمنين؟","answer":"إن حُمل ﴿الذين آمنوا﴾ على صادقي الإيمان، فالتخصيص لأنهم المنتفعون بهدايته ورحمته. وإن أريد من أظهر الإيمان، فمن رحمته بهم قبول ظاهرهم وعدم كشف أسرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص466، تحت «بلاغة العطف في ورحمة للذين آمنوا منكم»","url":""}]},{"id":"s9-355","number":355,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"لماذا أعاد الاسم الموصول: ﴿والذين يؤذون رسول الله﴾ بعد قوله ﴿الذين يؤذون النبي﴾؟","answer":"أعيد الموصول لاستئناف حكم عام في كل من يؤذي الرسول ﷺ، وليترتب عليه الوعيد مستقلًا بعد الرد على مقالتهم الخاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص468، تحت «بلاغة العطف في والذين يؤذون رسول الله»","url":""}]},{"id":"s9-742","number":742,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"لماذا عُدل من وصف ﴿النبي﴾ إلى وصف ﴿رسول الله﴾؟","answer":"وصف الرسالة يبرز أن أذاهم لا يتعلق بشخصه ﷺ وحده، بل بمنصبه في تبليغ أمر الله؛ ولذلك كان الوعيد على إيذائه أشد وأعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص469، تحت «نكتة العدول عن وصف النبوة إلى وصف الرسالة»","url":""}]},{"id":"s9-356","number":356,"surah":9,"verses":[61],"references":[{"surah":9,"verses":[61]}],"verseLabel":"التوبة: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿لهم عذاب أليم﴾ بدل «سيعذبهم الله»؟","answer":"الجملة الاسمية مع تقديم ﴿لهم﴾ تثبت اختصاصهم بالعذاب واستقراره لهم، ووصفه بالأليم يجانس الأذى الذي ألحقوه بالرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص470، تحت «نكتة التعبير بالجملة الاسمية في فاصلة الآية»","url":""}]},{"id":"s9-357","number":357,"surah":9,"verses":[62],"references":[{"surah":9,"verses":[62]}],"verseLabel":"التوبة: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿يحلفون بالله لكم ليرضوكم﴾، فجعل غاية الحلف رضا المؤمنين؟","answer":"قيد الحلف بقوله ﴿لكم﴾ ثم كشف غايته بقوله ﴿ليرضوكم﴾، فظهر أنهم لا يقصدون الحق، وإنما يسترون نفاقهم بطلب رضا الناس، مع أن رضا الله ورسوله أحق أن يطلبوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص479، تحت «سر تقييد الحلف بالجار والمجرور لكم»","url":""}]},{"id":"s9-358","number":358,"surah":9,"verses":[62],"references":[{"surah":9,"verses":[62]}],"verseLabel":"التوبة: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿والله ورسوله أحق أن يرضوه﴾، فأفرد الضمير مع ذكر اثنين؟","answer":"من توجيهاته أن رضا الرسول ﷺ لا ينفك عن رضا الله، فإرضاؤه من إرضائه سبحانه، فناسب ذلك توحيد الضمير. وذكر المصدر أوجهًا أخرى في عود الضمير وتقدير المحذوف، وكلها تراعي تعظيم المقام واتصال طاعة الرسول بطاعة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص482–484، تحت «نكتة حذف المسند الثاني وتوحيد الخبر في السياق الكريم»","url":""}]},{"id":"s9-359","number":359,"surah":9,"verses":[62],"references":[{"surah":9,"verses":[62]}],"verseLabel":"التوبة: 62","question":"ما دلالة ذكر الرسول ﷺ مع اسم الله في قوله: ﴿والله ورسوله أحق أن يرضوه﴾؟","answer":"ينبه إلى أن طلب رضا الرسول وطاعته من طلب رضا الله، ويعظم منزلته في مقام تبليغ الرسالة. وفي وقوع ذكره قبل الخبر ﴿أحق﴾ توكيد لوجوب مراعاة حقه وترك ما يؤذيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص481–482، تحت «بلاغة عطف اسم الرسول الأكرم على اسم الجلالة الأعظم»","url":""}]},{"id":"s9-360","number":360,"surah":9,"verses":[62],"references":[{"surah":9,"verses":[62]}],"verseLabel":"التوبة: 62","question":"لماذا استعمل ﴿أحق﴾ مع أن إرضاء الله ورسوله واجب لا مجرد أولى؟","answer":"يوجه المصدر ﴿أحق﴾ هنا بمعنى حقيق وواجب، مع اختصاص الله ورسوله بهذا الحق في المقام؛ فلا يراد مجرد ترجيح يجوز معه تقديم رضا الناس عليهما. فهي تبطل جعل إرضاء المؤمنين بالحلف الكاذب غايةً بدل امتثال ما يرضي الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص484–485، تحت «سر التعبير بمادة التفضيل أحق صيغة ومادة لغوية»","url":""}]},{"id":"s9-361","number":361,"surah":9,"verses":[62],"references":[{"surah":9,"verses":[62]}],"verseLabel":"التوبة: 62","question":"لماذا خُتم بـ﴿إن كانوا مؤمنين﴾؟","answer":"الشرط يفضح دعوى الإيمان: إن كانوا مؤمنين حقًا لقدموا رضا الله ورسوله، أما صنيعهم فدليل على خلاف ما يظهرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص485، تحت «بلاغة القيد بالشرط في جملة إن كانوا مؤمنين»","url":""}]},{"id":"s9-362","number":362,"surah":9,"verses":[63],"references":[{"surah":9,"verses":[63]}],"verseLabel":"التوبة: 63","question":"لماذا افتتحت الآية بـ﴿ألم يعلموا﴾ مع أن المنافقين يخفون كفرهم؟","answer":"الاستفهام للتوبيخ والتقرير؛ وعلمهم بما توعد الله به من المحادة حجة عليهم، وإن أظهروا الإيمان وأبطنوا الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص491، تحت «بلاغة الفصل ألم يعلموا»","url":""}]},{"id":"s9-363","number":363,"surah":9,"verses":[63],"references":[{"surah":9,"verses":[63]}],"verseLabel":"التوبة: 63","question":"ما سرّ التعبير بالمحادة في الفعل يحادد في قوله تعالى: ﴿من يحادد الله ورسوله﴾؟","answer":"المحادة اتخاذ حد وجانب في مقابلة حد الله ورسوله؛ فصورت مخالفتهم عداوة ومشاقة صريحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص493، تحت «سر التعبير بالمحادة في الفعل يحادد»","url":""}]},{"id":"s9-364","number":364,"surah":9,"verses":[63],"references":[{"surah":9,"verses":[63]}],"verseLabel":"التوبة: 63","question":"إلى من يعود الضمير في ﴿فأن له نار جهنم﴾، وما دلالة إفراده؟","answer":"يعود إلى ﴿مَن﴾ المحادِّ لله ورسوله، وقد روعي لفظها المفرد. وهذا الفرد يراد به كل من تحققت فيه الصفة؛ فلا تتعلق وحدة الضمير بذكر الله ورسوله، بل بمرجعه الذي استحق الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص498–500، تحت «بلاغة تقديم الجار والمجرور له؛ نكتة إفراد له وخالدًا»","url":""}]},{"id":"s9-365","number":365,"surah":9,"verses":[63],"references":[{"surah":9,"verses":[63]}],"verseLabel":"التوبة: 63","question":"لماذا جمع بين ﴿خالدًا فيها﴾ و﴿ذلك الخزي العظيم﴾؟","answer":"﴿خالدًا فيها﴾ يبين دوام العذاب، و﴿ذلك الخزي العظيم﴾ يجمع إلى الألم الهوان والفضيحة؛ فاستوفى نوعي العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص499، تحت «سر القيد بالحال خالدًا فيها»","url":""}]},{"id":"s9-366","number":366,"surah":9,"verses":[63],"references":[{"surah":9,"verses":[63]}],"verseLabel":"التوبة: 63","question":"لماذا أشار إلى العذاب بالبعيد: ﴿ذلك الخزي العظيم﴾؟","answer":"اسم الإشارة للبعيد يفخم شأن الخزي ويهول منزلته، ثم أكده بوصفه ﴿العظيم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص501، تحت «دلالة الإشارة في ذلك الخزي»","url":""}]},{"id":"s9-367","number":367,"surah":9,"verses":[64],"references":[{"surah":9,"verses":[64]}],"verseLabel":"التوبة: 64","question":"كيف يحذر المنافقون أن تنزل سورة تكشفهم مع أنهم لا يصدقون الوحي؟","answer":"يذكر المصدر أن الحذر قد ينشأ من الشك في أمر الوحي والخشية من أن يكون الرسول ﷺ صادقًا فيكشف الله ما يخفونه. فتظاهرهم بإنكار الوحي لا يمنع اضطرابهم من احتمال الفضيحة، ولا يلزم حمل خوفهم على إيمان ثابت به.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص508، تحت «بلاغة الكناية في لفظة يحذر»","url":""}]},{"id":"s9-368","number":368,"surah":9,"verses":[64],"references":[{"surah":9,"verses":[64]}],"verseLabel":"التوبة: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿يحذر المنافقون أن تنزل عليهم سورة﴾، مع أن السورة تنزل على النبي؟","answer":"﴿عليهم﴾ لأنها وإن نزلت على النبي ﷺ كانت في شأنهم وكاشفة لأحوالهم، فكان وقعها وضررها عائدًا عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص512، تحت «بلاغة التعبير بالمجاز المرسل في تنزيل السورة عليهم»","url":""}]},{"id":"s9-369","number":369,"surah":9,"verses":[64],"references":[{"surah":9,"verses":[64]}],"verseLabel":"التوبة: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿تنبئهم بما في قلوبهم﴾، فجعل السورة مخبرة للمنافقين أنفسهم؟","answer":"اختير ﴿تنبئهم﴾ لأنها تفيد الإخبار بأمر خفي ذي شأن؛ فتكشف السورة ما في قلوبهم حتى تصير خباياهم معلومة. ونُسب الإنباء إلى السورة لأنها سبب إعلان تلك الأسرار وافتضاح أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص514، تحت «الدقة في اصطفاء كلمة تنبئهم»","url":""}]},{"id":"s9-370","number":370,"surah":9,"verses":[64],"references":[{"surah":9,"verses":[64]}],"verseLabel":"التوبة: 64","question":"لماذا أُمر النبي أن يقول لهم: ﴿استهزئوا﴾؟","answer":"الأمر للتهديد والتعجيز، لا للإذن؛ أي استمروا في استهزائكم فالله سيظهر ما تخافون ظهوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص517، تحت «بلاغة الأمر بالفعل قل»","url":""}]},{"id":"s9-371","number":371,"surah":9,"verses":[64],"references":[{"surah":9,"verses":[64]}],"verseLabel":"التوبة: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الله مخرج ما تحذرون﴾، وصوّر السر كشيء يُخرج؟","answer":"صور ما أخفوه في القلوب شيئًا محبوسًا يخرجه الله إلى العلن، وفيه تأكيد أن كتمانهم لا يمنع افتضاحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص519، تحت «بلاغة التصوير البياني في الخبر»","url":""}]},{"id":"s9-372","number":372,"surah":9,"verses":[64],"references":[{"surah":9,"verses":[64]}],"verseLabel":"التوبة: 64","question":"لماذا اختير اسم الفاعل ﴿مخرج﴾ لا الفعل «سيخرج»؟","answer":"اسم الفاعل يدل على ثبوت الوعد وتحققه واستمرار القدرة عليه، فكأن إخراج أسرارهم وصف قائم لا أمر محتمل في المستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص520، تحت «سر التعبير باسم الفاعل مخرج»","url":""}]},{"id":"s9-373","number":373,"surah":9,"verses":[65],"references":[{"surah":9,"verses":[65]}],"verseLabel":"التوبة: 65","question":"ما وجه البلاغة في التعبير بالقسم وجوابه في قوله تعالى: ﴿ولئن سألتهم ليقولن إنما كنا نخوض ونلعب﴾؟","answer":"أكد بالقسم ولام الجواب ونونه أنهم سيجيبون بهذا الاعتذار، ثم حصروا فعلهم بإنما في الخوض واللعب ليوهموا أنهم لم يقصدوا الاستهزاء؛ ففضح النظم عذرهم الجاهز.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص525، تحت «بلاغة التعبير بالقسم وجوابه»","url":""}]},{"id":"s9-374","number":374,"surah":9,"verses":[65],"references":[{"surah":9,"verses":[65]}],"verseLabel":"التوبة: 65","question":"لماذا عبّروا عن استهزائهم بـ﴿نخوض ونلعب﴾؟","answer":"استعاروا الخوض للاندفاع في حديث الباطل كما يخوض المرء في الماء، ثم عطفوا ﴿ونلعب﴾ ليؤكدوا زعمهم أن الكلام عابر غير مقصود. لكن هذا التهوين لا يرفع قبح الاستهزاء ولا تبعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص528، تحت «بلاغة الاستعارة التبعية في لفظة نخوض»","url":""}]},{"id":"s9-375","number":375,"surah":9,"verses":[65],"references":[{"surah":9,"verses":[65]}],"verseLabel":"التوبة: 65","question":"ما دلالة الاستفهام في قوله: ﴿أبالله وآياته ورسوله كنتم تستهزئون﴾؟","answer":"الاستفهام إنكاري توبيخي، وقد قُدّم الجار والمجرور لإبراز فظاعة المتعلَّق: فالله وآياته ورسوله لا يصح أن يكونوا محل استهزاء، ولا يصلح ادعاء اللعب عذرًا في هذا المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص529، تحت «من بلاغة الاستفهام أبالله في السياق»","url":""}]},{"id":"s9-376","number":376,"surah":9,"verses":[65],"references":[{"surah":9,"verses":[65]}],"verseLabel":"التوبة: 65","question":"ما دلالة تقديم ﴿بالله وآياته ورسوله﴾ على ﴿كنتم تستهزئون﴾؟","answer":"قدم متعلق الاستهزاء لأنه الأهم في مقام التوبيخ، ودخلت عليه همزة الإنكار؛ فوجه التقريع إلى اتخاذ الله وآياته ورسوله محلًا لاستهزائهم، بعدما أقروا بالخوض واللعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص530، تحت «بلاغة تقديم الجار والمجرور في السياق»","url":""}]},{"id":"s9-377","number":377,"surah":9,"verses":[66],"references":[{"surah":9,"verses":[66]}],"verseLabel":"التوبة: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تعتذروا﴾ مع أنهم قدموا عذر اللعب؟","answer":"نُهوا عن الاعتذار لأن قولهم ﴿إنما كنا نخوض ونلعب﴾ لا يصلح عذرًا، بل هو إقرار بالفعل ومحاولة لتهوين جريمة لا يهونها اللعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص532، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-378","number":378,"surah":9,"verses":[66],"references":[{"surah":9,"verses":[66]}],"verseLabel":"التوبة: 66","question":"لماذا قيل للمنافقين: ﴿قد كفرتم بعد إيمانكم﴾؟","answer":"سُمّي استهزاؤهم كفرًا لأنه طعن في الله وآياته ورسوله، و﴿بعد﴾ تبين انقلابهم عما أظهروه من الإيمان. وإضافة الإيمان إليهم تراعي دعواهم وحكم ظاهرهم، فلا تشهد بصدق ما أخفوه في القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص535، تحت «دلالة وصف الاستهزاء بالكفر»","url":""}]},{"id":"s9-379","number":379,"surah":9,"verses":[66],"references":[{"surah":9,"verses":[66]}],"verseLabel":"التوبة: 66","question":"ما النكتة البلاغية في التقييد بإن في قوله تعالى: ﴿إن نعف عن طائفة منكم نعذب طائفة﴾؟","answer":"يفتح الشرط باب الرجاء لمن يتوب، مع إبقاء الوعيد لمن يصر على الإجرام؛ فمن أقلع وتاب ليس كمن استمر في النفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص536، تحت «نكتة التقييد بإن»","url":""}]},{"id":"s9-380","number":380,"surah":9,"verses":[66],"references":[{"surah":9,"verses":[66]}],"verseLabel":"التوبة: 66","question":"ما دلالة إسناد العفو والعذاب إلى الله في ﴿نعف﴾ و﴿نعذب﴾؟","answer":"في هذا الإسناد تعظيم للعفو وترغيب فيه، وتهويل للعذاب وترهيب منه؛ فأمر الفريقين إلى الله، وهو القادر على إنفاذ العفو والعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص538، تحت «نكتة إسناد العفو والعذاب إليه تعالى»","url":""}]},{"id":"s9-381","number":381,"surah":9,"verses":[66],"references":[{"surah":9,"verses":[66]}],"verseLabel":"التوبة: 66","question":"لماذا علل التعذيب بقوله: ﴿بأنهم كانوا مجرمين﴾ لا «مستهزئين»؟","answer":"الإجرام أعم ويكشف رسوخ الذنب وتعديه؛ فاستهزاؤهم ثم اعتذارهم الكاذب مظهر من حال إجرامية مستمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص539، تحت «لطيفة في وصف لفظ طائفة الثانية بالإجرام»","url":""}]},{"id":"s9-382","number":382,"surah":9,"verses":[67],"references":[{"surah":9,"verses":[67]}],"verseLabel":"التوبة: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿المنافقون والمنافقات بعضهم من بعض﴾، وقال في المؤمنين: ﴿بعضهم أولياء بعض﴾؟","answer":"﴿بعضهم من بعض﴾ تفيد تشابه المنافقين في الكفر وصفات الشر، أما ﴿بعضهم أولياء بعض﴾ فتثبت للمؤمنين رابطة المحبة والنصرة والتعاون؛ فتختلف رابطة الإيمان عن مجرد الاشتراك في النفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص548، تحت «دلالة الإطناب في صيغة الخبر»","url":""}]},{"id":"s9-383","number":383,"surah":9,"verses":[67],"references":[{"surah":9,"verses":[67]}],"verseLabel":"التوبة: 67","question":"لماذا صرح بذكر المنافقات مع المنافقين؟","answer":"لإحاطة الحكم بالجنسين وبيان اشتراكهما في صفات النفاق ووعيده؛ فلا يختص الذم بالرجال دون النساء اللاتي يشاركنهم أو يعاونّهم في تلك الأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص547، تحت «علة التصريح بذكر والمنافقات»","url":""}]},{"id":"s9-384","number":384,"surah":9,"verses":[67],"references":[{"surah":9,"verses":[67]}],"verseLabel":"التوبة: 67","question":"ما سرّ تقديم الأمر بالمنكر على النهي عن المعروف؟","answer":"قدم الأمر بالمنكر لأنه يبين مبادرتهم إلى نشر الشر، ثم ذكر نهيهم عن المعروف؛ فجمعوا الدعوة إلى الفساد والصد عن الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص554، تحت «سر البدء بالأمر بالمنكر على النهي عن المعروف»","url":""}]},{"id":"s9-385","number":385,"surah":9,"verses":[67],"references":[{"surah":9,"verses":[67]}],"verseLabel":"التوبة: 67","question":"ما الصورة في قوله: ﴿ويقبضون أيديهم﴾؟","answer":"كناية عن البخل ومنع الإنفاق والمعونة؛ فصوّر أيديهم مقبوضة لا تمتد إلى خير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص553–554، تحت «بلاغة الكناية في قبض اليد عن الشح»","url":""}]},{"id":"s9-386","number":386,"surah":9,"verses":[67],"references":[{"surah":9,"verses":[67]}],"verseLabel":"التوبة: 67","question":"ما دلالة قوله تعالى: ﴿نسوا الله فنسيهم﴾، وهل يوصف الله بالنسيان؟","answer":"بل تركوا ذكر الله وطاعته، فعاملهم معاملة المنسي بتركهم من رحمته وتوفيقه، جزاءً وفاقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص554، تحت «بلاغة التعبير بالمجاز في نسوا»","url":""}]},{"id":"s9-387","number":387,"surah":9,"verses":[67],"references":[{"surah":9,"verses":[67]}],"verseLabel":"التوبة: 67","question":"لماذا رتب نسيان الله لهم بالفاء على نسيانهم؟","answer":"الفاء تفيد ترتيب الجزاء على العمل وتعقيبه: لما تركوا طاعة الله جازاهم بتركهم من فضله وتوفيقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص555، تحت «من بلاغة المجاز والمشاكلة في سياق الآية الكريمة»","url":""}]},{"id":"s9-388","number":388,"surah":9,"verses":[67],"references":[{"surah":9,"verses":[67]}],"verseLabel":"التوبة: 67","question":"لماذا ختم بـ﴿إن المنافقين هم الفاسقون﴾؟","answer":"أكد الحكم بـ﴿إن﴾ وضمير الفصل ﴿هم﴾ وقصر الفسق عليهم للمبالغة؛ لأن النفاق جمع وجوه الخروج عن الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص556، تحت «دلالة موقع الجملة المؤكدة بإن مما قبلها»","url":""}]},{"id":"s9-389","number":389,"surah":9,"verses":[68],"references":[{"surah":9,"verses":[68]}],"verseLabel":"التوبة: 68","question":"لماذا جمع في الوعيد المنافقين والمنافقات والكفار؟","answer":"جمعهم لاشتراكهم في الكفر والمصير، مع التصريح بالذكور والإناث من المنافقين حتى يعم الوعيد جميع أصنافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص561، تحت «بلاغة الإظهار في مقام الإضمار»","url":""}]},{"id":"s9-390","number":390,"surah":9,"verses":[68],"references":[{"surah":9,"verses":[68]}],"verseLabel":"التوبة: 68","question":"ما دلالة التعبير بالحال خالدين فيها في قوله تعالى: ﴿نار جهنم خالدين فيها هي حسبهم ولعنهم الله﴾؟","answer":"﴿خالدين فيها﴾ يقرر دوام العذاب، و﴿هي حسبهم﴾ تبين أن جهنم كافية في جزائهم لشدة نكالها، ثم يزيد ذكر اللعنة معنى الإبعاد من رحمة الله؛ فتتراكم وجوه الوعيد ولا يتعارض بعضها مع بعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص563، تحت «دلالة التعبير بالحال خالدين فيها»","url":""}]},{"id":"s9-391","number":391,"surah":9,"verses":[68],"references":[{"surah":9,"verses":[68]}],"verseLabel":"التوبة: 68","question":"لماذا جمع بين النار ولعنة الله والعذاب المقيم؟","answer":"زاد ذكر اللعنة معنى الإبعاد من رحمة الله على وعيد النار، ووصف العذاب بالمقيم يصور ملازمته ودوامه، فيجمع السياق بين ألم العقوبة والحرمان من الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص565، تحت «سر عطف جملة ولعنهم الله»","url":""}]},{"id":"s9-392","number":392,"surah":9,"verses":[68],"references":[{"surah":9,"verses":[68]}],"verseLabel":"التوبة: 68","question":"لماذا وصف العذاب بأنه ﴿مقيم﴾ لا «دائم»؟","answer":"﴿مقيم﴾ يصور العذاب ثابتًا ملازمًا لا يبرح صاحبه، فكأنه مقيم معه؛ وهو أبلغ تصويرًا من الإخبار المجرد بالدوام.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص567، تحت «سر وصف العذاب بمقيم»","url":""}]},{"id":"s9-393","number":393,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"لماذا شُبّه المنافقون بمن قبلهم قبل تفصيل أوجه الشبه؟","answer":"قدم التشبيه الإجمالي لاستحضار سنة الأمم قبلهم وتحذيرهم من المصير نفسه، ثم فصل وجوه المشابهة في القوة والمتاع والخوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص569، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-394","number":394,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"لماذا عدد القوة وكثرة الأموال والأولاد؟","answer":"عددها لأنها أبرز أسباب اغترار الأمم: قوة الأبدان والسلطان، وسعة المال، وكثرة الأعوان والذرية؛ ولم تمنع عنهم العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص575، تحت «دلالة اعتراضية جملة اعتبارهم أشد منهم قوة»","url":""}]},{"id":"s9-395","number":395,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"ما دلالة الطلب بالفعل استمتع في السياق في قوله تعالى: ﴿فاستمتعوا بخلاقهم فاستمتعتم بخلاقكم﴾؟","answer":"تكرار العبارة يطابق بين فعل السابقين واللاحقين: تمتع كل فريق بنصيبه العاجل حتى شغله عن الآخرة، فاستحقوا مآلًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص579، تحت «دلالة الطلب بالفعل استمتع في السياق»","url":""}]},{"id":"s9-396","number":396,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"ما معنى ﴿خلاقهم﴾، ولماذا اختير بدل «نصيبهم»؟","answer":"الخلاق نصيب الخير المكتسب أو المستحق، أما النصيب فأعم. وقد استعمل هنا في حظهم من لذات الدنيا التي ألهتهم عن الآخرة، وفيه تهكم بمن استبدل الحظ العاجل بالجزاء الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص582، تحت «سر التعبير بالخلاق»","url":""}]},{"id":"s9-397","number":397,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"لماذا كرر ﴿كما استمتع الذين من قبلكم بخلاقهم﴾ بعد وضوح التشبيه؟","answer":"كرر الاستمتاع لتأكيد مماثلة اللاحقين للسابقين في الاغترار بنصيب الدنيا، مع بيان أن من قبلهم كانوا أشد قوة وأكثر مالًا وولدًا فلم تغن عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص580، تحت «نكتة الإطناب في تكرار لفظ الاستمتاع»","url":""}]},{"id":"s9-398","number":398,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿وخضتم كالذي خاضوا﴾، فأفرد ﴿الذي﴾؟","answer":"من توجيهات ﴿الذي﴾ أنها مصدرية، أو صفة لمصدر محذوف، أي كالخوض الذي خاضوه؛ فالإفراد على هذين الوجهين باعتبار الفعل لا جماعة الخائضين. وذكر المصدر أوجهًا أخرى لتوجيه الموصول.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص583–584، تحت «بلاغة الإيجاز في التشبيه؛ نكتة التعبير بالاسم الموصول المفرد كالذي»","url":""}]},{"id":"s9-399","number":399,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"لماذا جمع بين حبوط الأعمال والخسران؟","answer":"حبوط الأعمال يبين بطلان ما عملوه وذهاب ثمرته، والخسران يبين ما عاد على ذواتهم من فقد الخير واستحقاق العقاب؛ فجمع خسارة العمل والعامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص585، تحت «نكتة فصل قوله أولئك حبطت أعمالهم»","url":""}]},{"id":"s9-400","number":400,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"لماذا تكرر اسم الإشارة في قوله: ﴿أولئك حبطت أعمالهم... وأولئك هم الخاسرون﴾؟","answer":"أعيد ﴿أولئك﴾ ليستأنف لكل نتيجة حكم مستقل: حبوط الأعمال أولًا، ثم ثبوت الخسران لأصحابها؛ فيرسخ الوعيدان ولا تبدو الثانية مجرد تابع للأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص588، تحت «فائدة إعادة ذكر اسم الإشارة للبعيد»","url":""}]},{"id":"s9-743","number":743,"surah":9,"verses":[69],"references":[{"surah":9,"verses":[69]}],"verseLabel":"التوبة: 69","question":"ما وجه البلاغة في القصر بضمير الفصل هم وتعريف طرفي الإسناد؟","answer":"ضمير الفصل ﴿هم﴾ مع تعريف طرفي الإسناد يقوي اختصاصهم بالخسران على سبيل المبالغة؛ فكأنهم استجمعوا حقيقته وبلغوا غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص589، تحت «بلاغة القصر بضمير الفصل هم وتعريف طرفي الإسناد»","url":""}]},{"id":"s9-401","number":401,"surah":9,"verses":[70],"references":[{"surah":9,"verses":[70]}],"verseLabel":"التوبة: 70","question":"لماذا سأل: ﴿ألم يأتهم نبأ الذين من قبلهم﴾ مع معرفتهم بأخبار بعضهم؟","answer":"الاستفهام للتقرير والتوبيخ؛ فالعبرة ليست بمجرد سماع الأخبار، بل بفهم دلالتها، وكأنها لم تأتهم لما لم ينتفعوا بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص595، تحت «بلاغة الاستفهام في صدر الآية الكريمة»","url":""}]},{"id":"s9-744","number":744,"surah":9,"verses":[70],"references":[{"surah":9,"verses":[70]}],"verseLabel":"التوبة: 70","question":"ما سرّ التعبير بإتيان النبأ في قوله: ﴿ألم يأتهم نبأ الذين من قبلهم﴾؟","answer":"صُوّر الخبر كأنه آتٍ يبلغهم بنفسه؛ لكثرة طرق وصوله ووضوح شواهده، فلا يبقى لهم عذر في الغفلة عنه أو عدم الاعتبار به.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص596، تحت «نكتة التعبير بالإتيان دون غيره من الألفاظ»","url":""}]},{"id":"s9-745","number":745,"surah":9,"verses":[70],"references":[{"surah":9,"verses":[70]}],"verseLabel":"التوبة: 70","question":"ما فائدة التعبير بالموصول في قوله: ﴿نبأ الذين من قبلهم﴾؟","answer":"يجمع الموصول الأمم السابقة تحت وصف واحد هو تقدمها وسبق مصيرها، ثم يأتي تفصيلها بعد ذلك؛ فيهيئ السامع للعبرة العامة قبل تعداد أمثلتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص597، تحت «نكتة التعبير بالاسم الموصول الذين»","url":""}]},{"id":"s9-403","number":403,"surah":9,"verses":[70],"references":[{"surah":9,"verses":[70]}],"verseLabel":"التوبة: 70","question":"لماذا جمع أممًا متباعدة: قوم نوح وعاد وثمود وقوم إبراهيم وأصحاب مدين والمؤتفكات؟","answer":"خصت هذه الأمم لأن أخبارها معروفة للعرب وآثار بعض ديارها قريبة منهم، ولتنوع ما حل بها من العقوبات مع اشتراكها في تكذيب الرسل؛ فاجتمعت شواهد التحذير والاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص599، تحت «نكتة ذكر والمؤتفكات»","url":""}]},{"id":"s9-404","number":404,"surah":9,"verses":[70],"references":[{"surah":9,"verses":[70]}],"verseLabel":"التوبة: 70","question":"لماذا سميت قرى لوط ﴿المؤتفكات﴾؟","answer":"سميت ﴿المؤتفكات﴾ لأنها ائتفكت، أي انقلبت بأهلها؛ فالاسم يستحضر هيئة العقوبة التي صارت علمًا على قراهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص599، تحت «معنى أل للتعريف والعهد في لفظ والمؤتفكات»","url":""}]},{"id":"s9-405","number":405,"surah":9,"verses":[70],"references":[{"surah":9,"verses":[70]}],"verseLabel":"التوبة: 70","question":"ما دلالة قوله: ﴿أتتهم رسلهم بالبينات﴾ بعد ذكر الأمم السابقة؟","answer":"ذكر مجيء الرسل بالبينات يقرر تمام الحجة قبل الهلاك، وينفي أن تكون العقوبة بلا إنذار أو بيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص600، تحت «نكتة فصل قوله أتتهم رسلهم»","url":""}]},{"id":"s9-406","number":406,"surah":9,"verses":[70],"references":[{"surah":9,"verses":[70]}],"verseLabel":"التوبة: 70","question":"ما دلالة الفاء في سياق نفي الظلم في قوله تعالى: ﴿فما كان الله ليظلمهم ولكن كانوا أنفسهم يظلمون﴾؟","answer":"نفت الصيغة المؤكدة إمكان الظلم عن الله، ثم أسندت ظلمهم إلى أنفسهم؛ لأنهم باختيار التكذيب جلبوا إليها العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص601، تحت «دلالة الفاء في سياق نفي الظلم»","url":""}]},{"id":"s9-407","number":407,"surah":9,"verses":[71],"references":[{"surah":9,"verses":[71]}],"verseLabel":"التوبة: 71","question":"ما سرّ التعبير في قوله تعالى في المؤمنين: ﴿بعضهم أولياء بعض﴾ بدل ﴿بعضهم من بعض﴾ الواردة في المنافقين؟","answer":"الولاية تتضمن المحبة والنصرة والتعاون على الخير، وهي رابطة المؤمنين؛ أما ﴿بعضهم من بعض﴾ في المنافقين فمجرد تشابه في الطبع والشر لا ولاء صادق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص610–611، تحت «نكتة تغاير وصف المؤمنين عن وصف المنافقين»","url":""}]},{"id":"s9-408","number":408,"surah":9,"verses":[71],"references":[{"surah":9,"verses":[71]}],"verseLabel":"التوبة: 71","question":"ما دلالة الجمع بين المؤمنين والمؤمنات في وصف الولاية؟","answer":"يبين اشتراك الرجال والنساء في رابطة الإيمان وما تقتضيه من الولاية والتعاون والتكاليف المذكورة؛ فتشمل هذه الصفات والجزاء الجنسين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص611، تحت «دلالة الجمع بين المؤمنين والمؤمنات»","url":""}]},{"id":"s9-409","number":409,"surah":9,"verses":[71],"references":[{"surah":9,"verses":[71]}],"verseLabel":"التوبة: 71","question":"ما دلالة تقديم الأمر بالمعروف على النهي عن المنكر، وكيف يقابل ذلك وصف المنافقين؟","answer":"قُدّم الأمر بالمعروف لأنه إيجاد للخير، ثم أتبعه النهي عن المنكر لإزالة الشر. ويقابل ذلك المنافقون فيأمرون بالمنكر وينهون عن المعروف؛ فثبت ترتيب الأمر ثم النهي، وانقلب متعلق كل منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص612، تحت «فائدة تقديم الأمر على النهي»","url":""}]},{"id":"s9-410","number":410,"surah":9,"verses":[71],"references":[{"surah":9,"verses":[71]}],"verseLabel":"التوبة: 71","question":"لماذا جمع الصلاة والزكاة بعد الأمر بالمعروف والنهي عن المنكر؟","answer":"الأمر والنهي إصلاح للمجتمع، ثم خص الصلاة والزكاة لأنهما عمادا صلاح الفرد في العبادة البدنية والمالية، ودليل صدق الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص614، تحت «فائدة التنصيص على إقامة الصلاة والزكاة»","url":""}]},{"id":"s9-411","number":411,"surah":9,"verses":[71],"references":[{"surah":9,"verses":[71]}],"verseLabel":"التوبة: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿ويطيعون الله ورسوله﴾ بعد تفصيل الأعمال؟","answer":"بعد ذكر أعمال ظاهرة مخصوصة جاء الوصف الجامع ﴿يطيعون الله ورسوله﴾ ليدخل فيه سائر الأوامر والنواهي، وليبين أن تلك الأعمال صادرة عن طاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص615، تحت «علة استحضار الطاعة بعد ذكر الفرائض السابقة»","url":""}]},{"id":"s9-412","number":412,"surah":9,"verses":[71],"references":[{"surah":9,"verses":[71]}],"verseLabel":"التوبة: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿أولئك سيرحمهم الله﴾ بالسين؟","answer":"السين تفيد الوعد بالرحمة المستقبلة المتحققة، ولا سيما رحمة الآخرة؛ وفيها بشارة مرتبة على صفاتهم وأعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص616، تحت «نكتة دخول السين على الفعل سيرحمهم»","url":""}]},{"id":"s9-413","number":413,"surah":9,"verses":[71],"references":[{"surah":9,"verses":[71]}],"verseLabel":"التوبة: 71","question":"لماذا ختم بـ﴿إن الله عزيز حكيم﴾ لا «غفور رحيم»؟","answer":"﴿عزيز﴾ قادر على نصر أوليائه وإنفاذ وعده، و﴿حكيم﴾ يضع الرحمة في أهلها؛ فالخاتمة تناسب الوعد بالتمكين والجزاء وفق الحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص617، تحت «بلاغة فصل قوله إن الله عزيز حكيم»","url":""}]},{"id":"s9-414","number":414,"surah":9,"verses":[72],"references":[{"surah":9,"verses":[72]}],"verseLabel":"التوبة: 72","question":"لماذا فصل جزاء المؤمنين بعد إجماله في ﴿سيرحمهم الله﴾؟","answer":"﴿سيرحمهم الله﴾ وعد مجمل، ثم فصلت الآية صور الرحمة من جنات ومساكن ورضوان، لزيادة التشويق وبيان عظم الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص619، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-415","number":415,"surah":9,"verses":[72],"references":[{"surah":9,"verses":[72]}],"verseLabel":"التوبة: 72","question":"لماذا جمع بين الجنات والمساكن الطيبة ورضوان الله؟","answer":"الجنات تجمع نعيم المكان، والمساكن الطيبة راحته واستقراره، والرضوان نعيم القرب والقبول؛ فجمع نعيم الحس والروح.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص625، تحت «فائدة عطف جملة ومساكن طيبة على الجنات»","url":""}]},{"id":"s9-416","number":416,"surah":9,"verses":[72],"references":[{"surah":9,"verses":[72]}],"verseLabel":"التوبة: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿ورضوان من الله أكبر﴾ مع عظمة الجنة؟","answer":"عطف الرضوان على نعيم الجنات ليرتقي من نعمة المكان إلى رضا المنعم، و﴿من الله﴾ تشرفه بمصدره. وحُذف متعلق ﴿أكبر﴾ ليعم: فرضوان الله أكبر من كل ما سبق ومن كل نعيم يتصوره الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص627، تحت «فائدة العطف في قوله تعالى ورضوان»","url":""}]},{"id":"s9-418","number":418,"surah":9,"verses":[72],"references":[{"surah":9,"verses":[72]}],"verseLabel":"التوبة: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك هو الفوز العظيم﴾ بضمير الفصل؟","answer":"ضمير الفصل ﴿هو﴾ يقوي الحكم ويفيد القصر: هذا الجزاء الجامع للنعيم والرضوان هو الفوز العظيم حقًا، لا متاع الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص629، تحت «بلاغة القصر في فاصلة الآية»","url":""}]},{"id":"s9-419","number":419,"surah":9,"verses":[72],"references":[{"surah":9,"verses":[72]}],"verseLabel":"التوبة: 72","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران: ﴿ورضوان من الله﴾، وقوله تعالى في التوبة: ﴿ورضوان من الله أكبر﴾؟","answer":"في التوبة سبق تفصيل الجنان والمساكن، فناسب التصريح بـ﴿أكبر﴾ ليقرر أن رضوان الله أعظم من ذلك كله. أما الموضع الآخر فاكتفى بذكر الرضوان ضمن الجزاء من غير هذه المقارنة السياقية الصريحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص627، تحت «فائدة العطف في قوله تعالى ورضوان»","url":""}]},{"id":"s9-420","number":420,"surah":9,"verses":[72,89,100,111],"references":[{"surah":9,"verses":[72,89,100,111]}],"verseLabel":"التوبة: 72؛ التوبة: 89، 100، 111","question":"ما سرّ اختلاف التعبير في سورة التوبة بين: ﴿ذلك هو الفوز العظيم﴾، و﴿ذلك الفوز العظيم﴾، و﴿وذلك هو الفوز العظيم﴾؟","answer":"في الآية 72 أكد الجزاء الجامع للنعيم والرضوان بضمير الفصل والقصر. وفي 89 جاءت ﴿ذلك الفوز العظيم﴾ بلا واو لشدة اتصالها بما قبلها وتوكيده، وبلا ضمير فصل في خطاب هذه الطائفة المعينة. وفي 100 جاءت الجملة استئنافًا بعد تفصيل حال السابقين وأتباعهم، لتوجيه الانتباه إلى عظم فوزهم. وفي 111 استؤنفت بالواو بعد الأمر بالاستبشار بالبيع، وأكد الفوز بضمير الفصل؛ فلكل موضع صلته بسياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص366، تحت «بلاغة التذييل التعليلي في الإشارة إلى الفوز العظيم»","url":""}]},{"id":"s9-421","number":421,"surah":9,"verses":[73],"references":[{"surah":9,"verses":[73]}],"verseLabel":"التوبة: 73","question":"لماذا جمع النبي ﷺ في أمر واحد بين جهاد الكفار والمنافقين؟","answer":"جمعهما لأن الفريقين يعادون الدعوة، لكن جهاد الكفار يكون بالسلاح والحجة، وجهاد المنافقين بإقامة الحجة وكشف النفاق وإجراء الأحكام والغلظة المناسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص637، تحت «دلالة الحقيقة والمجاز في قوله جاهد»","url":""}]},{"id":"s9-422","number":422,"surah":9,"verses":[73],"references":[{"surah":9,"verses":[73]}],"verseLabel":"التوبة: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿واغلظ عليهم﴾ بعد الأمر بالجهاد؟","answer":"الأمر بالغلظة يبين الهيئة التي يقتضيها الجهاد حين لا يصلح اللين: حزم يمنع الكفار والمنافقين من التمادي في الأذى. واستعيرت الغلظة، وهي صفة للأجسام، للشدة في المعاملة والموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص640، تحت «دلالة الأمر بالغلظة بعد الأمر بالجهاد»","url":""}]},{"id":"s9-423","number":423,"surah":9,"verses":[73],"references":[{"surah":9,"verses":[73]}],"verseLabel":"التوبة: 73","question":"لماذا كانت خاتمة الآية: ﴿ومأواهم جهنم وبئس المصير﴾؟","answer":"يبين السياق بعد الأمر بجهادهم والغلظة عليهم مآلهم في الآخرة: جهنم مستقرهم، وبئس المرجع الذي ينتهون إليه. وفي ذكر المأوى على سبيل التهكم زيادة في التهديد، ثم جاء الذم تقريرًا لسوء المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص641، تحت «دلالة الوصل بالواو في ومأواهم جهنم»","url":""}]},{"id":"s9-424","number":424,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"ما سرّ التأكيد في ولقد قالوا كلمة الكفر في قوله تعالى: ﴿يحلفون بالله ما قالوا ولقد قالوا كلمة الكفر﴾؟","answer":"قابل حلفهم المؤكد بالنفي بتوكيدين: اللام و﴿قد﴾ في ﴿ولقد قالوا﴾؛ ففضح كذب اليمين وأثبت قولهم ثبوتًا قاطعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص652، تحت «سر التأكيد في ولقد قالوا كلمة الكفر»","url":""}]},{"id":"s9-425","number":425,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"لماذا أبهم القول فقال: ﴿كلمة الكفر﴾ ولم ينقل عبارتهم؟","answer":"ثم سماه ﴿كلمة الكفر﴾ ليصف حقيقته ويثبت بطلان إنكارهم؛ والمراد بالكلمة هنا الكلام الذي قالوه، لا مجرد لفظ مفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص652، تحت «سر حذف متعلق الفعل قالوا»","url":""}]},{"id":"s9-426","number":426,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿وكفروا بعد إسلامهم﴾ لا «بعد إيمانهم»؟","answer":"﴿إسلامهم﴾ يدل على الانقياد الظاهر الذي أعلنوه، ولا يشهد لهم بإيمان قلبي؛ ثم أظهرت كلمة الكفر حقيقة باطنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص655، تحت «بلاغة الاستعارة في وكفروا بعد إسلامهم»","url":""}]},{"id":"s9-427","number":427,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿وهموا بما لم ينالوا﴾ ولم يصرح بما هموا به؟","answer":"أبهم الأمر باسم الموصول لشناعة ما هموا به، مع بيان أنهم لم يبلغوه. ويفسره الموضع المعاين بمحاولة قتل الرسول ﷺ، وفي ﴿لم ينالوا﴾ إظهار فشل كيدهم وعصمة الله له من أعدائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص657، تحت «دلالة التعبير بالفعل الماضي وهموا»","url":""}]},{"id":"s9-428","number":428,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"ما المفارقة في قوله: ﴿وما نقموا إلا أن أغناهم الله ورسوله من فضله﴾؟","answer":"ذكر الإغناء في موضع ما ينقمونه، مع أنه إحسان يقتضي الشكر؛ فليس لهم سبب صحيح للنقمة. وهذا من تأكيد المدح بما يشبه الذم، وفيه كشف جحودهم إذ قابلوا النعمة بالعداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص659–660، تحت «بلاغة تأكيد المدح بما يشبه الذم»","url":""}]},{"id":"s9-429","number":429,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"لماذا نُسب الإغناء إلى الله ورسوله ثم أُفرد الفضل في ﴿من فضله﴾؟","answer":"الإغناء وقع بتقدير الله وعلى يد رسوله ﷺ في القسمة، أما الفضل فمن الله وحده؛ لذلك عاد الضمير مفردًا إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص660، تحت «دلالة عطف الرسول على الاسم الأعظم في قوله إلا أن أغناهم الله ورسوله»","url":""}]},{"id":"s9-430","number":430,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"لماذا فُتح باب التوبة بعد كل هذه الجرائم: ﴿فإن يتوبوا يك خيرًا لهم﴾؟","answer":"فتح باب التوبة بيان لسعة الرحمة وإقامة للحجة؛ فمع عظم جرائمهم يكون رجوعهم خيرًا لهم من الإصرار الذي يجر عذاب الدارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص662، تحت «دلالة الفاء في فإن»","url":""}]},{"id":"s9-431","number":431,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"ما النكتة البلاغية في تقديم التوبة على التولي في قوله تعالى: ﴿وإن يتولوا يعذبهم الله عذابًا أليمًا في الدنيا والآخرة﴾؟","answer":"قابل الشرطان طريقين واضحين: التوبة خير لهم، والتولي يفضي إلى عذاب مؤلم في الدنيا والآخرة؛ فاستوعب المآل العاجل والآجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص663، تحت «نكتة تقديم التوبة على التولي»","url":""}]},{"id":"s9-432","number":432,"surah":9,"verses":[74],"references":[{"surah":9,"verses":[74]}],"verseLabel":"التوبة: 74","question":"لماذا ختم بنفي الولي والنصير في الأرض؟","answer":"نفي الولي والنصير يقطع طمعهم في حماية تنفعهم من عذاب الله؛ فلا قريب يتولى أمرهم ولا معين يدفع عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص667، تحت «نكتة التعبير بلفظ الأرض»","url":""}]},{"id":"s9-433","number":433,"surah":9,"verses":[75],"references":[{"surah":9,"verses":[75]}],"verseLabel":"التوبة: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿ومنهم من عاهد الله﴾، فنسب العهد إلى الله مباشرة؟","answer":"العهد مع الله يغلظ مسؤولية الوعد؛ فهم لم يعدوا الناس فقط، بل التزموا لله إن رزقهم أن يتصدقوا ويصلحوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص673–674، تحت «نكتة التعبير بالاسم الأعظم الله»","url":""}]},{"id":"s9-434","number":434,"surah":9,"verses":[75],"references":[{"surah":9,"verses":[75]}],"verseLabel":"التوبة: 75","question":"لماذا أكدوا وعدهم باللام والنون: ﴿لنصدقن ولنكونن من الصالحين﴾؟","answer":"اللام ونون التوكيد الثقيلة في الفعلين تشددان الوعد وتكشفان عظم إخلافه حين جاءهم الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص674، تحت «دلالة اللام في لئن»","url":""}]},{"id":"s9-435","number":435,"surah":9,"verses":[75],"references":[{"surah":9,"verses":[75]}],"verseLabel":"التوبة: 75","question":"لماذا جمعوا بين الصدقة والصلاح؟","answer":"الصدقة عمل مالي مخصوص، وكونهم من الصالحين وصف أعم يشمل الوفاء والطاعة؛ فوعدوا ببذل المال وإصلاح الحال كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص670، تحت «مناسبة الآيات لما قبلها»","url":""}]},{"id":"s9-436","number":436,"surah":9,"verses":[76],"references":[{"surah":9,"verses":[76]}],"verseLabel":"التوبة: 76","question":"ما دلالة الفاء في فلما في قوله تعالى: ﴿فلما آتاهم من فضله بخلوا به﴾؟","answer":"الفاء تفيد التعقيب: ما إن تحقق الإيتاء حتى قابلوه بالبخل، و﴿من فضله﴾ تذكر بأن المال تفضل من الله لا ملك مستقل لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص677، تحت «دلالة الفاء في فلما»","url":""}]},{"id":"s9-437","number":437,"surah":9,"verses":[76],"references":[{"surah":9,"verses":[76]}],"verseLabel":"التوبة: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿وتولوا وهم معرضون﴾، فجمع بين التولي والإعراض؟","answer":"﴿تولوا﴾ يصور انصرافهم بالفعل بعد أن تحقق لهم الفضل، ثم تكشف الحال ﴿وهم معرضون﴾ أن ذلك الانصراف صادر عن صدود قلبي راسخ؛ فجمع التعبير بين حركة الظاهر وموقف الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص677، تحت «دلالة الفعل المضعف وتولوا»","url":""}]},{"id":"s9-438","number":438,"surah":9,"verses":[76],"references":[{"surah":9,"verses":[76]}],"verseLabel":"التوبة: 76","question":"لماذا جاءت ﴿وهم معرضون﴾ جملة اسمية؟","answer":"الجملة الاسمية تثبت الإعراض صفة مستقرة فيهم حال توليهم، لا فعلًا طارئًا وقع مرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص678، تحت «دلالة التعبير بالجملة الاسمية وهم معرضون»","url":""}]},{"id":"s9-439","number":439,"surah":9,"verses":[77],"references":[{"surah":9,"verses":[77]}],"verseLabel":"التوبة: 77","question":"ما وجه قوله تعالى: ﴿فأعقبهم نفاقًا في قلوبهم﴾ مع وصفهم قبل ذلك بالنفاق؟","answer":"المعنى أن إخلاف العهد والكذب أورثاهم نفاقًا ثابتًا متزايدًا لازم قلوبهم إلى الموت أو لقاء الله؛ فالجزاء زيادة النفاق ورسوخه، لا ابتداء كل نفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص680، تحت «نكتة تنكير لفظ نفاقًا»","url":""}]},{"id":"s9-440","number":440,"surah":9,"verses":[77],"references":[{"surah":9,"verses":[77]}],"verseLabel":"التوبة: 77","question":"لماذا أسند إعقاب النفاق إلى الله أو إلى البخل بحسب توجيه الضمير؟","answer":"على عود الضمير إلى الله فالإعقاب جزاء إلهي عادل على البخل والإخلاف، وعلى عوده إلى البخل فالمعنى أن فعلهم صار سببًا ملازمًا للنفاق؛ والنتيجة واحدة في ترتيب الجزاء على الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص679، تحت «دلالة الفاء في فأعقبهم»","url":""}]},{"id":"s9-441","number":441,"surah":9,"verses":[77],"references":[{"surah":9,"verses":[77]}],"verseLabel":"التوبة: 77","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى يوم يلقونه﴾ بدل «إلى موتهم»؟","answer":"﴿إلى يوم يلقونه﴾ يستحضر الوقوف بين يدي الله وما بعد الموت من حساب، فهو أبلغ في الوعيد من ذكر الموت وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص681، تحت «بلاغة الكناية إلى يوم يلقونه»","url":""}]},{"id":"s9-442","number":442,"surah":9,"verses":[77],"references":[{"surah":9,"verses":[77]}],"verseLabel":"التوبة: 77","question":"لماذا علل النفاق بإخلاف الوعد والكذب معًا؟","answer":"جمع بين إخلاف الوعد والكذب لبيان تعدد أسباب رسوخ النفاق؛ فذكر الإخلاف ونص على الكذب مع دخوله فيه لتغليظ جرمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص681، تحت «دلالة الباء في بما»","url":""}]},{"id":"s9-443","number":443,"surah":9,"verses":[78],"references":[{"surah":9,"verses":[78]}],"verseLabel":"التوبة: 78","question":"لماذا سأل: ﴿ألم يعلموا أن الله يعلم سرهم ونجواهم﴾؟","answer":"الاستفهام للتقرير والتوبيخ: أي إنهم يعلمون أن الله يحيط بما يسرونه وما يتناجون به، فكيف يخفون إخلافهم وكذبهم؟ وفصل الجملة يستأنف الحجة ويواجههم بها مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص686، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-444","number":444,"surah":9,"verses":[78],"references":[{"surah":9,"verses":[78]}],"verseLabel":"التوبة: 78","question":"ما الفرق بين ﴿سرهم﴾ و﴿نجواهم﴾؟","answer":"السر ما يضمره الإنسان أو يخفيه في نفسه، والنجوى حديث خفي بين اثنين فأكثر؛ فجمع علمه بالباطن الفردي والخفي المتبادل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص692، تحت «السر والنجوى»","url":""}]},{"id":"s9-445","number":445,"surah":9,"verses":[78],"references":[{"surah":9,"verses":[78]}],"verseLabel":"التوبة: 78","question":"لماذا ختم بـ﴿وأن الله علام الغيوب﴾ بصيغة المبالغة؟","answer":"﴿علّام﴾ صيغة مبالغة تدل على سعة العلم وإحاطته بكل غائب وخفي، فلا يخرج عنه سر ولا نجوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص690، تحت «نكتة التأكيد في وأن الله علام الغيوب»","url":""}]},{"id":"s9-446","number":446,"surah":9,"verses":[79],"references":[{"surah":9,"verses":[79]}],"verseLabel":"التوبة: 79","question":"لماذا وصف المنافقين بأنهم ﴿يلمزون المطوعين﴾؟","answer":"اللمز طعن بقصد الانتقاص، والمضارع ﴿يلمزون﴾ يصور تجدد فعلهم واعتيادهم له؛ فهم يعيبون المتصدقين كلما وجدوا سبيلًا، لا لأنهم ينقدون فعلًا معينًا بإنصاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص696، تحت «نكتة التعبير بالفعل المضارع يلمزون»","url":""}]},{"id":"s9-447","number":447,"surah":9,"verses":[79],"references":[{"surah":9,"verses":[79]}],"verseLabel":"التوبة: 79","question":"لماذا جمع بين السخرية من كثير الصدقة وقليلها؟","answer":"جمع الفريقين ليكشف أن غرض المنافقين ليس تقويم الصدقة؛ فكثيرها عندهم رياء وقليلها سخرية، فلا يسلم عندهم صاحب خير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص697، تحت «دلالة أل في لفظ المطوعين»","url":""}]},{"id":"s9-448","number":448,"surah":9,"verses":[79],"references":[{"surah":9,"verses":[79]}],"verseLabel":"التوبة: 79","question":"ما وجه البلاغة في الإطناب في قوله تعالى: ﴿والذين لا يجدون إلا جهدهم﴾؟","answer":"القصر بـ﴿لا يجدون إلا جهدهم﴾ يبرز أنهم بذلوا غاية ما يملكون مع قلته، فيعظم إخلاصهم وتشتد بشاعة السخرية منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص698، تحت «بلاغة الإطناب»","url":""}]},{"id":"s9-449","number":449,"surah":9,"verses":[79],"references":[{"surah":9,"verses":[79]}],"verseLabel":"التوبة: 79","question":"لماذا جاء الجزاء بلفظ فعلهم: ﴿سخر الله منهم﴾؟","answer":"قوبلت سخريتهم بالمؤمنين بسخرية الله منهم جزاءً من جنس عملهم؛ فيعاملهم بما يهينهم ويكشف خبيئة كفرهم، مع إبقاء أحكام الإسلام الظاهرة عليهم إلى أن يلقوا وعيدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص699، تحت «براعة المقابلة»","url":""}]},{"id":"s9-450","number":450,"surah":9,"verses":[79],"references":[{"surah":9,"verses":[79]}],"verseLabel":"التوبة: 79","question":"لماذا ختم بـ﴿ولهم عذاب أليم﴾؟","answer":"العذاب الأليم جزاء يناسب أذاهم للمؤمنين وسخريتهم من الطاعة، والجملة الاسمية تثبت استحقاقه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص700، تحت «نكتة تقديم ما حقه التأخير»","url":""}]},{"id":"s9-451","number":451,"surah":9,"verses":[80],"references":[{"surah":9,"verses":[80]}],"verseLabel":"التوبة: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿استغفر لهم أو لا تستغفر لهم﴾ بصيغة التسوية؟","answer":"الأمر للتسوية في انتفاء النتيجة: استغفارك لهم وعدمه سواء ما داموا مصرين على الكفر؛ وليس المقصود طلب أحد الفعلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص704، تحت «دلالة الأمر في استغفر»","url":""}]},{"id":"s9-452","number":452,"surah":9,"verses":[80],"references":[{"surah":9,"verses":[80]}],"verseLabel":"التوبة: 80","question":"لماذا ذُكر العدد ﴿سبعين مرة﴾؟","answer":"السبعون تجري في أساليب العرب مجرى التكثير والمبالغة، والمعنى أن كثرة الاستغفار لا تنفعهم مع بقاء سبب المنع، لا أن الزيادة تضمن المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص711، تحت «دلالة لفظ سبعين ودلالته»","url":""}]},{"id":"s9-453","number":453,"surah":9,"verses":[80],"references":[{"surah":9,"verses":[80]}],"verseLabel":"التوبة: 80","question":"لماذا علل عدم المغفرة بكفرهم بالله ورسوله؟","answer":"بينت العلة أن المانع ليس قلة الاستغفار، بل كفرهم بالله ورسوله؛ والمغفرة لا تنال مع الإصرار على أصل الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص713، تحت «دلالة اسم الإشارة ذلك»","url":""}]},{"id":"s9-454","number":454,"surah":9,"verses":[80],"references":[{"surah":9,"verses":[80]}],"verseLabel":"التوبة: 80","question":"ما دلالة إيراد جملة ﴿والله لا يهدي القوم الفاسقين﴾ اسمية من دون مؤكدات؟","answer":"تفيد الاسمية ثبات انتفاء الهداية واستمراره ما دام الفسق وصفهم، وجاءت من دون مؤكدات لأن سياق أفعالهم شاهد ظاهر يغني عن التوكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص714، تحت «دلالة إيراد الجملة الاسمية من دون مؤكدات»","url":""}]},{"id":"s9-746","number":746,"surah":9,"verses":[80],"references":[{"surah":9,"verses":[80]}],"verseLabel":"التوبة: 80","question":"ما علاقة تذييل الآية بـ﴿والله لا يهدي القوم الفاسقين﴾ بمعناها؟","answer":"الخاتمة تعلل عدم المغفرة بأنهم خرجوا عن الطاعة ورسخ الفسق فيهم، فلا يوفقهم الله للهداية ما داموا مختارين لهذا الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص715، تحت «علاقة تذييل الآية بمعناها»","url":""}]},{"id":"s9-747","number":747,"surah":9,"verses":[80],"references":[{"surah":9,"verses":[80]}],"verseLabel":"التوبة: 80","question":"لماذا أوثر لفظ ﴿الفاسقين﴾ بدلًا من المنافقين؟","answer":"لأن الفسق هو الوصف الذي يبين علة حرمانهم من الهداية، وهو أعم من اسم المنافقين وأشد اتصالًا بالحكم المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص716، تحت «إيثار لفظ الفاسقين بدلًا من المنافقين»","url":""}]},{"id":"s9-455","number":455,"surah":9,"verses":[80],"references":[{"surah":9,"verses":[80]}],"verseLabel":"التوبة: 80","question":"ما سرّ اختلاف التعبير بين قوله تعالى في التوبة: ﴿استغفر لهم أو لا تستغفر لهم إن تستغفر لهم سبعين مرة فلن يغفر الله لهم﴾، وقوله تعالى في المنافقون: ﴿سواء عليهم أستغفرت لهم أم لم تستغفر لهم لن يغفر الله لهم﴾؟","answer":"جاءت آية التوبة في صورة الأمر والتخيير مع ذكر السبعين، والمراد عند حملها على التسوية انتفاء المغفرة ولو كثر الاستغفار. أما آية المنافقون فصرحت بالتسوية بلفظ ﴿سواء عليهم﴾. ويذكر المصدر وجوهًا للجمع بينهما، منها أن الثانية تبين الأولى وتكشف أن الزيادة على السبعين لا تنفع مع الإصرار على النفاق، ومنها اختلاف الطائفة المخاطب بشأنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص716–717، تحت «المتشابه اللفظي»","url":""}]},{"id":"s9-456","number":456,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"لماذا سُمّي المتخلفون ﴿المخلفون﴾ بالبناء للمجهول؟","answer":"﴿المخلّفون﴾ يشعر بأنهم تُركوا وراء الخارجين وحرموا شرف صحبتهم، مع أنهم اختاروا التخلف؛ ففي الصيغة ذم وإبعاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص723، تحت «دلالة أل في المخلفون»","url":""}]},{"id":"s9-457","number":457,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"ما دلالة التعبير بقوله: ﴿بمقعدهم﴾؟","answer":"جعل قعودهم نفسه متعلق فرحهم، فكأن موضع التخلف صار غاية يسرون بها. وإفراد ﴿مقعد﴾ باعتباره مصدرًا أو اسم جنس يجمع قعودهم المتعدد في هيئة واحدة مذمومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص724، تحت «دلالة الجار والمجرور بمقعدهم»","url":""}]},{"id":"s9-748","number":748,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"ما سرّ اختيار ﴿خلاف رسول الله﴾؟","answer":"تحتمل ﴿خلاف﴾ معنى التخلف وراء الرسول ﷺ ومعنى مخالفته؛ فتجمع الكلمة قعودهم المكاني عن الخروج وصدودهم المعنوي عن أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص725، تحت «فوائد إيثار لفظ خلاف»","url":""}]},{"id":"s9-458","number":458,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"ما دلالة عطف جملة وكرهوا على ما قبلها في قوله تعالى: ﴿كرهوا أن يجاهدوا بأموالهم وأنفسهم﴾؟","answer":"المصدر المؤول يبين متعلق كراهيتهم: نفس الجهاد بالمال والنفس؛ وهو يكشف أن التخلف لم يكن عذرًا بل نفورًا من التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص726، تحت «عطف جملة وكرهوا على ما قبلها»","url":""}]},{"id":"s9-459","number":459,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"ما سرّ تقديم الأموال على الأنفس حتى في وصف كراهتهم؟","answer":"قدم الأموال لأن بذلها مقدمة لإعداد القتال، ولأن الحاجة إلى الجهاد بالمال أوسع؛ فالمجاهد بنفسه يحتاج إلى ما يجهزه ويعينه. وناسب ذكرها هنا كشف كراهتهم لما يتطلبه الجهاد من بذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص728، تحت «سر تقديم الأموال على الأنفس»","url":""}]},{"id":"s9-460","number":460,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"ما وجه العطف في وقالوا في قوله تعالى: ﴿لا تنفروا في الحر﴾؟","answer":"قالوها تثبيطًا لغيرهم واعتذارًا بحر تبوك؛ فجمعوا تخلفهم الشخصي ومحاولة صرف المؤمنين عن النفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص731، تحت «وجه العطف في وقالوا»","url":""}]},{"id":"s9-461","number":461,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"لماذا جاء الرد: ﴿قل نار جهنم أشد حرًا﴾؟","answer":"رد عليهم من جنس عذرهم: إن فروا من حر يسير مؤقت فقد عرضوا أنفسهم لحر جهنم الأشد، فالموازنة تبطل حجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص732، تحت «وجه الرد عليهم»","url":""}]},{"id":"s9-462","number":462,"surah":9,"verses":[81],"references":[{"surah":9,"verses":[81]}],"verseLabel":"التوبة: 81","question":"لماذا ختم بـ﴿لو كانوا يفقهون﴾ لا «يعلمون»؟","answer":"الفقه فهم ينفذ إلى العواقب، لا مجرد معرفة أن النار أشد حرًا؛ فلو فقهوا لآثروا مشقة الساعة على عذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص735، تحت «فائدة قوله تعالى لو كانوا يفقهون ودلالته»","url":""}]},{"id":"s9-463","number":463,"surah":9,"verses":[82],"references":[{"surah":9,"verses":[82]}],"verseLabel":"التوبة: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿فليضحكوا قليلًا وليبكوا كثيرًا﴾ بصيغة الأمر؟","answer":"الأمران للتهديد والإخبار بالمآل، لا لطلب الضحك والبكاء؛ أي ضحكهم في الدنيا قليل وسيتبعه بكاء كثير في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص741، تحت «دلالة اللام في الفعل فليضحكوا»","url":""}]},{"id":"s9-464","number":464,"surah":9,"verses":[82],"references":[{"surah":9,"verses":[82]}],"verseLabel":"التوبة: 82","question":"لماذا قابل القليل بالكثير والضحك بالبكاء؟","answer":"قابل الضحك بالبكاء والقليل بالكثير لإظهار التفاوت بين متاعهم العاجل القصير وحسرتهم وعذابهم الطويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص743، تحت «بلاغة المقابلة»","url":""}]},{"id":"s9-465","number":465,"surah":9,"verses":[82],"references":[{"surah":9,"verses":[82]}],"verseLabel":"التوبة: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿جزاء بما كانوا يكسبون﴾، فاختار الكسب؟","answer":"اختير ﴿يكسبون﴾ لأن الكسب ما يتعمد الإنسان تحصيله لنفسه، فدل على مسؤوليتهم عن النفاق والتثبيط. وصيغة المضارع مع ﴿كانوا﴾ تصور دوام هذا السلوك وتجدد آثاره حتى صار الجزاء من جنس ما اكتسبوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص746، تحت «إيثار لفظ يكسبون دون مرادفاته»","url":""}]},{"id":"s9-466","number":466,"surah":9,"verses":[83],"references":[{"surah":9,"verses":[83]}],"verseLabel":"التوبة: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن رجعك الله إلى طائفة منهم﴾، دون أن يقال: «إذا رجعت»؟","answer":"اختيرت ﴿إن﴾ لأن الرجوع من السفر، بحسب ما يترقبه المخاطبون، أمر معلق بما يقدره الله لا موعدًا يتصرفون فيه؛ وفي ذلك إبقاء للشرط مع ربط المآل كله بمشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص752، تحت «إيثار إن على إذا»","url":""}]},{"id":"s9-749","number":749,"surah":9,"verses":[83],"references":[{"surah":9,"verses":[83]}],"verseLabel":"التوبة: 83","question":"لماذا صُرّح باسم الله في قوله: ﴿فإن رجعك الله﴾؟","answer":"التصريح باسم الجلالة يقرر أن الرجوع بتقدير الله وحفظه، وأن الحكم اللاحق في المتخلفين صادر عن سلطانه، لا عن رغبة شخصية من الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص753، تحت «دلالة التصريح باسم الجلالة»","url":""}]},{"id":"s9-467","number":467,"surah":9,"verses":[83],"references":[{"surah":9,"verses":[83]}],"verseLabel":"التوبة: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى طائفة منهم﴾ لا «إليهم»؟","answer":"قال ﴿طائفة منهم﴾ لأن بعض المتخلفين قد يهلك أو يغيب، ولأن الحكم متعلق بمن بقي ممن استحق هذا التأديب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص754، تحت «دلالة لفظ طائفة»","url":""}]},{"id":"s9-468","number":468,"surah":9,"verses":[83],"references":[{"surah":9,"verses":[83]}],"verseLabel":"التوبة: 83","question":"ما دلالة توكيد المنع في قوله: ﴿لن تخرجوا معي أبدًا ولن تقاتلوا معي عدوًا﴾؟","answer":"أكدت ﴿لن﴾ نفي خروجهم وقتالهم في المستقبل، وزاد ﴿أبدًا﴾ المنع استغراقًا، فصار الخبر في قوة النهي والعقوبة: لما رضوا بالتخلف أول مرة حُرموا شرف المشاركة بعد ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص756، تحت «إيثار النفي بلن»","url":""}]},{"id":"s9-469","number":469,"surah":9,"verses":[83],"references":[{"surah":9,"verses":[83]}],"verseLabel":"التوبة: 83","question":"ما النكتة البلاغية في التعبير بالرضا عن القعود في قوله تعالى: ﴿رضيتم بالقعود أول مرة﴾؟","answer":"﴿رضيتم﴾ يثبت أن القعود كان اختيارًا استحسنوه لا اضطرارًا، و﴿أول مرة﴾ تجعل موقف تبوك أصلًا يترتب عليه حرمانهم اللاحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص760، تحت «نكتة التعبير بالرضا عن القعود»","url":""}]},{"id":"s9-470","number":470,"surah":9,"verses":[83],"references":[{"surah":9,"verses":[83]}],"verseLabel":"التوبة: 83","question":"ما دلالة الفاء في فاقعدوا في قوله تعالى: ﴿فاقعدوا مع الخالفين﴾؟","answer":"الأمر للإهانة والتثبيت على الجزاء: الزموا القعود مع من شأنهم التخلف، بعد أن رضيتم لأنفسكم به حين دعاكم الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص761، تحت «دلالة الفاء في فاقعدوا»","url":""}]},{"id":"s9-471","number":471,"surah":9,"verses":[84],"references":[{"surah":9,"verses":[84]}],"verseLabel":"التوبة: 84","question":"لماذا نُهي النبي ﷺ عن الصلاة على أحد منهم مات أبدًا؟","answer":"النهي الدائم يقطع ما في الصلاة عليه من تكريم ودعاء واستغفار؛ لأن موته على الكفر يمنع المغفرة ويكشف حقيقة نفاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص767، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-472","number":472,"surah":9,"verses":[84],"references":[{"surah":9,"verses":[84]}],"verseLabel":"التوبة: 84","question":"لماذا جمع بين ﴿ولا تصل على أحد﴾ و﴿ولا تقم على قبره﴾؟","answer":"الصلاة دعاء للميت، والقيام على القبر يشمل شهود دفنه والدعاء له؛ فجمع النهي عن وجهي التكريم بعد الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص770، تحت «فائدة عطف جملة ولا تقم على قبره»","url":""}]},{"id":"s9-473","number":473,"surah":9,"verses":[84],"references":[{"surah":9,"verses":[84]}],"verseLabel":"التوبة: 84","question":"لماذا علل النهي بأنهم كفروا وماتوا وهم فاسقون؟","answer":"الكفر يبين فساد الاعتقاد، والموت على الفسق يبين استمرار الخروج عن الطاعة إلى النهاية؛ فالعبرة بالخاتمة من غير توبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص771، تحت «سر فصل جملة إنهم كفروا»","url":""}]},{"id":"s9-474","number":474,"surah":9,"verses":[84],"references":[{"surah":9,"verses":[84]}],"verseLabel":"التوبة: 84","question":"ما سرّ التعبير في قوله تعالى: ﴿ماتوا وهم فاسقون﴾، دون أن يقال: «منافقون»؟","answer":"الفسق هو الخروج عن الطاعة، وهو أعم من الكفر والنفاق في الأصل، لكن السياق يجعله هنا وصفًا كاشفًا لاستمرار خروجهم عن الإيمان إلى الموت؛ فناسب مقام بيان سوء الخاتمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص773، تحت «إيثار لفظ فاسقون دون غيره»","url":""}]},{"id":"s9-475","number":475,"surah":9,"verses":[85],"references":[{"surah":9,"verses":[85]}],"verseLabel":"التوبة: 85","question":"لماذا تكرر النهي: ﴿ولا تعجبك أموالهم وأولادهم﴾ من الآية 55؟","answer":"أعيد النهي لتقرير التحذير وتأكيده مع تجدد السياق وما قد يثير الإعجاب بالأموال والأولاد. ويذكر المصدر وجهًا آخر، وهو اختلاف الطائفتين المقصودتين؛ فلا يحصر سبب التكرار في هذا الوجه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص780–781، تحت «فائدة التكرار في ولا تعجبك»","url":""}]},{"id":"s9-476","number":476,"surah":9,"verses":[85],"references":[{"surah":9,"verses":[85]}],"verseLabel":"التوبة: 85","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿أن يعذبهم بها في الدنيا﴾، وقال سابقًا: ﴿في الحياة الدنيا﴾؟","answer":"ذُكرت ﴿الحياة الدنيا﴾ أولًا بتمام الموصوف والصفة، ثم حذف الموصوف هنا اكتفاء بسبق ذكره؛ والدنيا هي الحياة القريبة المقابلة للآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص784، تحت «المتشابه اللفظي»","url":""}]},{"id":"s9-477","number":477,"surah":9,"verses":[85],"references":[{"surah":9,"verses":[85]}],"verseLabel":"التوبة: 85","question":"لماذا أعيدت خاتمة ﴿وتزهق أنفسهم وهم كافرون﴾؟","answer":"تقرر الخاتمة اقتران خروج أرواحهم بالكفر، فتصل ما يعانونه في الدنيا بعاقبتهم بعد الموت. وتكرار هذا الوصف في السورة يكشف حال المنافقين عند قبض أرواحهم ويحذر من الاغترار بظاهر النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص786، تحت «دلالة الواو في وتزهق»","url":""}]},{"id":"s9-478","number":478,"surah":9,"verses":[86],"references":[{"surah":9,"verses":[86]}],"verseLabel":"التوبة: 86","question":"ما دلالة ﴿أن﴾ في قوله: ﴿أن آمنوا بالله وجاهدوا مع رسوله﴾؟","answer":"تأتي ﴿أن﴾ تفسيرية فتشرح مضمون السورة المنزلة: الأمر بالإيمان والجهاد مع الرسول ﷺ؛ وبذلك ينتقل الكلام من ذكر نزول السورة إلى بيان التكليف الذي فضح موقف المنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص797، تحت «دلالة أن في أن آمنوا وأثرها في المعنى»","url":""}]},{"id":"s9-750","number":750,"surah":9,"verses":[86],"references":[{"surah":9,"verses":[86]}],"verseLabel":"التوبة: 86","question":"ما سرّ تقديم الأمر بالإيمان على الأمر بالجهاد؟","answer":"قدم الإيمان لأنه أصل الأعمال وشرط قبول الجهاد، ثم عطف الجهاد بوصفه الأثر العملي الذي يمتحن صدق ذلك الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص797، تحت «سر تقديم الأمر بالإيمان على الأمر بالجهاد»","url":""}]},{"id":"s9-479","number":479,"surah":9,"verses":[86],"references":[{"surah":9,"verses":[86]}],"verseLabel":"التوبة: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿استأذنك أولو الطول منهم﴾، وخص أهل القدرة؟","answer":"﴿أولو الطول﴾ أصحاب السعة والقدرة، وخصوا لأن استئذان العاجز قد يعذر، أما استئذان القادر فيكشف النفاق وشدة التعلق بالدعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص798، تحت «سر التعبير بأولو الطول»","url":""}]},{"id":"s9-480","number":480,"surah":9,"verses":[86],"references":[{"surah":9,"verses":[86]}],"verseLabel":"التوبة: 86","question":"ما دلالة الأمر في قوله ذرنا ودلالته؟","answer":"﴿ذرنا﴾ طلب ترك يحمل معنى التعلل والإصرار، و﴿مع القاعدين﴾ يكشف رضاهم بالانضمام إلى أهل الأعذار ومن لا ينهض للجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص799، تحت «دلالة الأمر في قوله ذرنا ودلالته»","url":""}]},{"id":"s9-481","number":481,"surah":9,"verses":[87],"references":[{"surah":9,"verses":[87]}],"verseLabel":"التوبة: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿رضوا بأن يكونوا مع الخوالف﴾، فجعل القعود موضع رضا؟","answer":"جعل القعود موضع رضا لبيان أنهم لم يقعوا فيه كارهين أو معذورين، بل اختاروا منزلة الخوالف واستحبوها على صحبة الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص12، تحت «سر العدول إلى الإخبار برضاهم أن يكونوا مع الخوالف»","url":""}]},{"id":"s9-482","number":482,"surah":9,"verses":[87],"references":[{"surah":9,"verses":[87]}],"verseLabel":"التوبة: 87","question":"لماذا اختيرت ﴿الخوالف﴾ لا «القاعدين»؟","answer":"﴿الخوالف﴾ يغلب في النساء أو من شأنه البقاء خلف الخارجين، فاختيارها أشد إزراء بالرجال القادرين الذين رضوا لأنفسهم هذا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص14، تحت «سر اصطفاء صيغة الجمع في الخوالف»","url":""}]},{"id":"s9-483","number":483,"surah":9,"verses":[87],"references":[{"surah":9,"verses":[87]}],"verseLabel":"التوبة: 87","question":"ما دلالة عطف ﴿وطبع على قلوبهم﴾ على رضاهم بالقعود مع الخوالف؟","answer":"يصل العطف بين اختيارهم القعود وحال قلوبهم؛ فرضاهم بالدعة والصدود عن الجهاد أفضى إلى انغلاقها عن الهدى. ثم جاءت الفاء في ﴿فهم لا يفقهون﴾ لترتب حرمان الفهم النافع على ذلك الطبع.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص18، تحت «دلالة الفاء في فهم»","url":""}]},{"id":"s9-484","number":484,"surah":9,"verses":[87],"references":[{"surah":9,"verses":[87]}],"verseLabel":"التوبة: 87","question":"ما الصورة في ﴿طبع على قلوبهم﴾؟","answer":"شُبهت قلوبهم بشيء ختم عليه فلا يدخله نور ولا يخرج ما فيه؛ فهي استعارة تصور انغلاقها عن فهم الحق وقبوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص16، تحت «الغرض من التعبير بالاستعارة في وطبع»","url":""}]},{"id":"s9-485","number":485,"surah":9,"verses":[87],"references":[{"surah":9,"verses":[87]}],"verseLabel":"التوبة: 87","question":"لماذا كانت النتيجة: ﴿فهم لا يفقهون﴾ لا «لا يعلمون»؟","answer":"الفقه فهم دقيق يثمر اعتبارًا وعملًا؛ وقد حجب الطبع قلوبهم عن هذا الفهم، وإن أدركوا ظواهر الأقوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص18، تحت «سر التعبير بلفظ لا يفقهون»","url":""}]},{"id":"s9-486","number":486,"surah":9,"verses":[88],"references":[{"surah":9,"verses":[88]}],"verseLabel":"التوبة: 88","question":"لماذا استدرك بقوله: ﴿لكن الرسول والذين آمنوا معه﴾ بعد وصف المتخلفين؟","answer":"يقابل الاستدراك تخلف المنافقين بجهاد الرسول ﷺ والمؤمنين معه؛ فإن قعد أولئك فقد نهض غيرهم بالنصرة. وفي ذلك بيان الاستغناء عن المتخلفين وإبراز فضل أهل الإيمان وبشارتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص24، تحت «دلالة حرف الاستدراك وعلاقته بما قبله»","url":""}]},{"id":"s9-487","number":487,"surah":9,"verses":[88],"references":[{"surah":9,"verses":[88]}],"verseLabel":"التوبة: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿الرسول﴾ بالوصف ولم يذكر اسمه؟","answer":"وصف ﴿الرسول﴾ يستحضر موجب اتباعه ونصره؛ فالجهاد معه مقتضى رسالته، والتخلف عنه مخالفة لوظيفته في الأمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص25، تحت «دلالة أل في لفظ الرسول وأثرها في السياق»","url":""}]},{"id":"s9-488","number":488,"surah":9,"verses":[88],"references":[{"surah":9,"verses":[88]}],"verseLabel":"التوبة: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿جاهدوا بأموالهم وأنفسهم﴾، وأعاد الوصف المألوف؟","answer":"إعادة الأموال والأنفس تقابل كراهة المنافقين لهما، وتبين أن المؤمنين بذلوا أعز ما يملكون في الجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص28، تحت «الغرض من تقديم الأموال على الأنفس في السياق»","url":""}]},{"id":"s9-489","number":489,"surah":9,"verses":[88],"references":[{"surah":9,"verses":[88]}],"verseLabel":"التوبة: 88","question":"ما دلالة التعبير بـ﴿الخيرات﴾ دون تقييدها بنوع واحد؟","answer":"يدل الجمع والتعريف على وفرة الخيرات وشمولها لمنافع الدنيا والآخرة، فيندرج فيها النصر والكرامة والثواب والجنة؛ وجاءت غير مقيدة بنوع لتتسع لهذه البشارات.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص29، تحت «دلالة الجمع في لفظ الخيرات»","url":""}]},{"id":"s9-490","number":490,"surah":9,"verses":[88],"references":[{"surah":9,"verses":[88]}],"verseLabel":"التوبة: 88","question":"لماذا كرر اسم الإشارة: ﴿وأولئك لهم الخيرات وأولئك هم المفلحون﴾؟","answer":"كرر الإشارة ليجعل لكل بشارة استقلالًا: لهم جميع الخيرات، وهم المفلحون؛ وضمير الفصل يؤكد اختصاصهم بالفلاح الكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص30، تحت «فائدة تكرار اسم الإشارة»","url":""}]},{"id":"s9-491","number":491,"surah":9,"verses":[89],"references":[{"surah":9,"verses":[89]}],"verseLabel":"التوبة: 89","question":"لماذا انتقل من ﴿الخيرات﴾ إلى تفصيل الجنات؟","answer":"فصلت الجنات بعد إجمال ﴿الخيرات﴾ لبيان أعظم خيرات الآخرة وتشويق النفس إليها بعد الوعد العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص34، تحت «الغرض من كمال الاتصال في الجملة أعد من السياق»","url":""}]},{"id":"s9-493","number":493,"surah":9,"verses":[89],"references":[{"surah":9,"verses":[89]}],"verseLabel":"التوبة: 89","question":"لماذا جمع بين ﴿خالدين فيها﴾ و﴿ذلك الفوز العظيم﴾؟","answer":"﴿خالدين فيها﴾ ينفي انقطاع النعيم، و﴿ذلك الفوز العظيم﴾ يحكم بأن نيل المحبوب الدائم والنجاة من المكروه هو الفوز الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص39، تحت «الغرض من كمال الاتصال ذلك الفوز العظيم»","url":""}]},{"id":"s9-494","number":494,"surah":9,"verses":[90],"references":[{"surah":9,"verses":[90]}],"verseLabel":"التوبة: 90","question":"لماذا فرّق بين ﴿المعذرون﴾ و﴿الذين كذبوا الله ورسوله﴾؟","answer":"﴿المعذرون﴾ جاؤوا يطلبون الإذن ويظهرون عذرًا، وقد يكون فيهم صادق أو مقصر؛ أما الآخرون فقعدوا بلا اعتذار وكذبوا الله ورسوله، فكان جرمهم أصرح.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص45، تحت «سر اختيار لفظ المعذرون»","url":""}]},{"id":"s9-495","number":495,"surah":9,"verses":[90],"references":[{"surah":9,"verses":[90]}],"verseLabel":"التوبة: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿وجاء المعذرون﴾، بينما قال عن الآخرين: ﴿وقعد الذين كذبوا﴾؟","answer":"المعذرون تحملوا المجيء لعرض أعذارهم، أما المكذبون فقعدوا من غير اكتراث ولا محاولة اعتذار؛ فاختلاف الفعلين يصور تفاوت الحال والجرأة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص48، تحت «سر التعبير بالجملة الخبرية وجاء المعذرون»","url":""}]},{"id":"s9-496","number":496,"surah":9,"verses":[90],"references":[{"surah":9,"verses":[90]}],"verseLabel":"التوبة: 90","question":"ما دلالة قوله: ﴿كذبوا الله ورسوله﴾، وتعدية كذبوا من غير حرف جر؟","answer":"على قراءة التخفيف، معناه أنهم أخبروا الله ورسوله بخلاف ما في قلوبهم، فكانت دعوى إيمانهم أو وعدهم بالنصرة كاذبًا. وذكر المصدر قراءة التشديد بمعنى التكذيب؛ فهذان توجيهان مرتبطان باختلاف القراءة، لا معنى واحد للفعلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص50، تحت «سر التصريح بمعمول الفعل الله ورسوله»","url":""}]},{"id":"s9-497","number":497,"surah":9,"verses":[90],"references":[{"surah":9,"verses":[90]}],"verseLabel":"التوبة: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿سيصيب الذين كفروا منهم عذاب أليم﴾، فأدخل ﴿منهم﴾؟","answer":"من أوجه ﴿منهم﴾ التبعيض؛ فالوعيد متعلق بمن ثبت كفره، ولا يعمم على كل الأعراب أو كل من عرض عذرًا. ويذكر المصدر اختلاف مرجع الضمير بين الأعراب والمذكورين من المنافقين والمعذرين، مع احتمال توبة بعضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص52–53، تحت «سر التعبير بالجار والمجرور منهم»","url":""}]},{"id":"s9-498","number":498,"surah":9,"verses":[91],"references":[{"surah":9,"verses":[91]}],"verseLabel":"التوبة: 91","question":"لماذا جمع الضعفاء والمرضى ومن لا يجدون ما ينفقون؟","answer":"جمعت الآية أصحاب الأعذار التي تمنع الجهاد: ضعف البدن، والمرض، وفقد النفقة؛ فاستوعبت العجز الخِلقي والعارض والمالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص61، تحت «سر اصطفاء صيغة الجمع الضعفاء»","url":""}]},{"id":"s9-499","number":499,"surah":9,"verses":[91],"references":[{"surah":9,"verses":[91]}],"verseLabel":"التوبة: 91","question":"لماذا اشترط لرفع الحرج: ﴿إذا نصحوا لله ورسوله﴾؟","answer":"رفع الحرج مشروط ببقاء صدقهم وإخلاصهم: ينصحون لله ورسوله ولا يثبطون ولا يخونون، ويؤدون ما قدروا عليه من وجوه الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص65، تحت «دلالة التعبير بالظرف المتضمن معنى الشرط في إذا»","url":""}]},{"id":"s9-500","number":500,"surah":9,"verses":[91],"references":[{"surah":9,"verses":[91]}],"verseLabel":"التوبة: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿ما على المحسنين من سبيل﴾، فنفى كل سبيل؟","answer":"﴿من﴾ الزائدة في سياق النفي تفيد الاستغراق: لا طريق إلى لوم المحسنين أو عقابهم من أي وجه ما دام العذر صحيحًا والنصح قائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص67، تحت «موقع جملة ما على المحسنين ودلالته»","url":""}]},{"id":"s9-501","number":501,"surah":9,"verses":[91],"references":[{"surah":9,"verses":[91]}],"verseLabel":"التوبة: 91","question":"لماذا وصف أصحاب الأعذار بـ﴿المحسنين﴾؟","answer":"وصفوا بالمحسنين لأنهم مع عجزهم صدقوا النية ونصحوا وبذلوا ما استطاعوا؛ فالإحسان بحسب القدرة لا بمجرد المشاركة البدنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص68، تحت «سر اصطفاء لفظ المحسنين في السياق»","url":""}]},{"id":"s9-502","number":502,"surah":9,"verses":[91],"references":[{"surah":9,"verses":[91]}],"verseLabel":"التوبة: 91","question":"لماذا ختمت آية أصحاب الأعذار (التوبة: 91) بـ﴿والله غفور رحيم﴾؟","answer":"تؤكد الخاتمة رفع الحرج عن أصحاب الأعذار؛ فمن رحمته ألا يكلفهم ما يشق عليهم، ومن مغفرته ألا يؤاخذهم بالتخلف المعذور.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص70، تحت «دلالة تذييل الآية بقوله والله غفور رحيم»","url":""}]},{"id":"s9-751","number":751,"surah":9,"verses":[91],"references":[{"surah":9,"verses":[91]}],"verseLabel":"التوبة: 91","question":"ما فائدة حذف متعلق صفتي المغفرة والرحمة؟","answer":"يفيد الحذف الإطلاق والعموم، فتتسع المغفرة للذنوب والرحمة لأحوال العباد من غير تقييد بمتعلق معين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص71، تحت «فائدة حذف متعلق صفتي المغفرة والرحمة»","url":""}]},{"id":"s9-503","number":503,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"لماذا أفرد بالذكر الذين جاؤوا ليُحملوا بعد إدخالهم فيمن لا يجدون ما ينفقون؟","answer":"أفردوا لأن حالهم أبلغ: لم يكتفوا بالرغبة، بل جاؤوا يطلبون ما يحملهم، ثم بكوا حين لم يجدوا؛ فاستحق إخلاصهم تنويهًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص76، تحت «دلالة عطف قوله ولا على الذين على ما قبله»","url":""}]},{"id":"s9-504","number":504,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"ما دلالة قوله: ﴿قلت لا أجد ما أحملكم عليه﴾ في تصوير حال الرسول ﷺ وطالبي الخروج؟","answer":"يبين أنه ﷺ لم يجد وقتئذ ما يهيئه لحملهم، مع صدق رغبتهم في الخروج. واكتفى أولئك بتصريحه بعدم الوجدان، فصدقوه وانصرفوا حزنى؛ فعبارة الآية تصور العجز عن التجهيز والثقة بقوله معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص79، تحت «موقع جملة قلت ودلالتها»","url":""}]},{"id":"s9-505","number":505,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"لماذا عبّر بقوله تعالى: ﴿تولوا﴾ عن رجوع طالبي الخروج؟","answer":"يصوّر التولي رجوعهم عن رسول الله ﷺ مكرهين بعد أن تعلقت نفوسهم بالخروج؛ فالكلمة ترسم انصراف الجسد مع بقاء الرغبة والحزن في القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص81، تحت «إيثار لفظ تولوا»","url":""}]},{"id":"s9-752","number":752,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"ما الصورة في قوله تعالى: ﴿وأعينهم تفيض من الدمع﴾؟","answer":"بالغ التصوير حتى جعل العين نفسها كأنها تفيض، لا الدمع وحده؛ وفي ذلك إشعار بكثرة بكائهم وصدق حزنهم على فوات الجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص82، تحت «الغرض من التعبير بالاستعارة في الفعل تفيض»","url":""}]},{"id":"s9-506","number":506,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿حزنًا ألا يجدوا ما ينفقون﴾، دون أن يقال: حزنًا على عدم الخروج؟","answer":"ذكر فقد النفقة لأنه العائق المباشر عن الخروج، وفيه أنهم كانوا يملكون الرغبة والقوة ولم يحبسهم إلا عدم وسيلة الجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص84، تحت «الغرض من التعبير بقوله ألا يجدوا ما ينفقون»","url":""}]},{"id":"s9-507","number":507,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"لماذا أوثر لفظ ﴿تولوا﴾ في وصف أصحاب الأعذار الصادقين؟","answer":"يصور اللفظ انصرافهم بعد أن توجهت رغبتهم إلى الخروج، فكان رجوعهم اضطرارًا لا إعراضًا عن الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص81، تحت «إيثار لفظ تولوا»","url":""}]},{"id":"s9-753","number":753,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"ما الغرض من التعبير بالاستعارة في الفعل ﴿تفيض﴾؟","answer":"صور كثرة الدمع حتى كأن العين إناء يفيض، مبالغة في صدق حزنهم على فوات المشاركة في الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص82، تحت «الغرض من التعبير بالاستعارة في الفعل تفيض»","url":""}]},{"id":"s9-754","number":754,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"ما دلالة كلمة ﴿حزنًا﴾ في سياق فيض أعينهم من الدمع؟","answer":"تكشف أن الدمع ناشئ من حزن صادق على العجز عن النفقة والخروج، لا من تظاهر أو ضعف عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص83، تحت «موقع كلمة حزنًا ودلالته»","url":""}]},{"id":"s9-755","number":755,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"ما سر العدول عن الإخبار إلى الإنشاء في ﴿فليضحكوا قليلًا وليبكوا كثيرًا﴾؟","answer":"جاء الخبر في صورة الأمر للتهكم والوعيد، حتى يبدو الجزاء واقعًا محققًا لا مجرد خبر ينتظر تحققه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص742، تحت «سر العدول عن الإخبار إلى الإنشاء»","url":""}]},{"id":"s9-756","number":756,"surah":9,"verses":[92],"references":[{"surah":9,"verses":[92]}],"verseLabel":"التوبة: 92","question":"ما بلاغة المقابلة بين ﴿فليضحكوا قليلًا﴾ و﴿وليبكوا كثيرًا﴾؟","answer":"قوبل الضحك بالبكاء والقلة بالكثرة، فبرز قصر فرحهم في الدنيا وطول حزنهم في الآخرة في صورة شديدة التأثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص743، تحت «بلاغة المقابلة»","url":""}]},{"id":"s9-508","number":508,"surah":9,"verses":[93],"references":[{"surah":9,"verses":[93]}],"verseLabel":"التوبة: 93","question":"لماذا حصر المؤاخذة بقوله: ﴿إنما السبيل على الذين يستأذنونك وهم أغنياء﴾؟","answer":"﴿إنما﴾ تقصر اللوم والعقوبة على القادرين الذين يستأذنون في القعود، بعد رفع الحرج عن أصحاب الأعذار الصادقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص90، تحت «سر اختيار إنما طريقًا لأسلوب القصر في السياق»","url":""}]},{"id":"s9-509","number":509,"surah":9,"verses":[93],"references":[{"surah":9,"verses":[93]}],"verseLabel":"التوبة: 93","question":"لماذا وصفهم بالغنى بدل القوة أو الصحة؟","answer":"الغنى يدل على امتلاك النفقة والوسيلة، وهو موضع العذر السابق؛ فإذا كانوا أغنياء انتفى عذر العجز المالي وظهر اختيارهم للقعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص92، تحت «سر التقييد بالجملة الحالية وهم أغنياء وأثرها في المعنى»","url":""}]},{"id":"s9-510","number":510,"surah":9,"verses":[93],"references":[{"surah":9,"verses":[93]}],"verseLabel":"التوبة: 93","question":"لماذا كرر: ﴿رضوا بأن يكونوا مع الخوالف﴾؟","answer":"كرر وصف رضاهم بمعية الخوالف لتأكيد قبح اختيارهم القعود واستسلامهم لهذه المنزلة مع قدرتهم على الخروج. فالتكرار يثبت ما انطوت عليه نفوسهم من الإعراض وما آل إليه حال قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص93، تحت «دلالة الاستئناف في رضوا»","url":""}]},{"id":"s9-511","number":511,"surah":9,"verses":[93],"references":[{"surah":9,"verses":[93]}],"verseLabel":"التوبة: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿وطبع الله على قلوبهم﴾ هنا بإظهار اسم الله، وقال في الآية 87: ﴿وطبع على قلوبهم﴾؟","answer":"في الآية 87 سبق البناء للمجهول في ﴿أنزلت﴾ فناسبه ﴿طبع﴾، وهنا تكرر اسم الله في السياق فصرح به: ﴿وطبع الله﴾؛ وفي الحالين الطبع جزاء إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص94، تحت «سر بناء الفعل للمفعول وطبع وللفاعل وطبع»","url":""}]},{"id":"s9-512","number":512,"surah":9,"verses":[93],"references":[{"surah":9,"verses":[93]}],"verseLabel":"التوبة: 93","question":"لماذا ختم بـ﴿فهم لا يعلمون﴾، بينما ختمت الآية 87 بـ﴿فهم لا يفقهون﴾؟","answer":"يربط المصدر بين الفقه والتفكر والتأمل، وهو من صفات المخلوقين، وبين العلم الذي يوصف به الله. فعلى هذا التوجيه ناسب ﴿لا يفقهون﴾ عدم التصريح بالفاعل في الموضع الأول، وناسب ﴿لا يعلمون﴾ التصريح باسم الله في الثاني؛ وفي حذف المفعول تعميم لنفي العلم النافع عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص96، تحت «دلالة حذف المفعول به من الفعل يعلمون»","url":""}]},{"id":"s9-513","number":513,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"لماذا أخبر أنهم سيعتذرون ﴿إذا رجعتم إليهم﴾ قبل وقوع الاعتذار؟","answer":"الإخبار قبل وقوعه دليل على صدق الوحي وكشف لما أضمروه، ويهيئ المؤمنين لئلا يخدعوا بأعذار مصنوعة عند الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص102، تحت «دلالة التعبير بالماضي رجعتم»","url":""}]},{"id":"s9-514","number":514,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"لماذا جاء الرد: ﴿قل لا تعتذروا لن نؤمن لكم﴾؟","answer":"نُهوا عن الاعتذار لأن الله كشف أخبارهم، و﴿لن نؤمن لكم﴾ أي لن نصدقكم؛ فانتفى أثر كلامهم بعد ظهور كذبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص104، تحت «دلالة الفصل لن نؤمن لكم»","url":""}]},{"id":"s9-515","number":515,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"ما سرّ التعبير بقوله تعالى: ﴿قد نبأنا الله﴾؟","answer":"النبأ خبر عظيم الشأن؛ فاختياره يدل على خطورة ما كشفه الله من أحوال المنافقين، وأنه خبر يقيني يبطل أعذارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص106، تحت «سر التعبير بنبأنا»","url":""}]},{"id":"s9-757","number":757,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿من أخباركم﴾؟","answer":"تحتمل التبعيض؛ أي أطلع الله رسوله ﷺ على قدر من أخبارهم يكفي لكشف كذبهم، وتحتمل بيان الجنس، وكلا الوجهين يقطع أثر اعتذارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص107، تحت «سر التعبير بمن»","url":""}]},{"id":"s9-516","number":516,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿وسيرى الله عملكم ورسوله﴾، فأعاد باب العمل بعد الأعذار؟","answer":"بعد إبطال الأقوال أحال الحكم إلى العمل المستقبل؛ فصدق التوبة لا تثبته الأعذار، بل ما سيراه الله ورسوله من أفعالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص108، تحت «بلاغة الكناية في جملة وسيرى الله»","url":""}]},{"id":"s9-517","number":517,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"لماذا وصف الله بـ﴿عالم الغيب والشهادة﴾ في خاتمة الآية؟","answer":"وصفه بـ﴿عالم الغيب والشهادة﴾ لأنه يعلم أعذارهم الباطنة وأعمالهم الظاهرة، فلا تخفى عليه حقيقة التوبة ولا النفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص112، تحت «سر التعبير بلفظي عالم الغيب والشهادة»","url":""}]},{"id":"s9-518","number":518,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿فينبئكم بما كنتم تعملون﴾ مع أنهم يعرفون أعمالهم؟","answer":"الإنباء هنا إظهار حقيقة الأعمال والحكم عليها والجزاء بها يوم القيامة، لا مجرد إخبارهم بوقائع يعرفونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص113، تحت «بلاغة الكناية في فينبئكم»","url":""}]},{"id":"s9-519","number":519,"surah":9,"verses":[94,105],"references":[{"surah":9,"verses":[94,105]}],"verseLabel":"التوبة: 94؛ التوبة: 105","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الآية 94: ﴿وسيرى الله عملكم ورسوله ثم تردون﴾، وقوله في الآية 105: ﴿فسيرى الله عملكم ورسوله والمؤمنون وستردون﴾؟","answer":"في الآية94 حديث عن المنافقين وما يخفونه؛ فاقتصر على الله ورسوله، وعطفت الرؤية بالواو على كشف أخبارهم، وجاءت ثم للتراخي والإمهال قبل الرد للجزاء. وفي الآية105 الحديث عن العمل الظاهر، فذكر المؤمنون، ورتبت رؤيته بالفاء على الأمر بالعمل. وتفيد الواو مع السين في وستردون تقريب الجزاء ثوابًا أو عقابًا؛ فلا تختص العبارة بالوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص116، تحت «سر استعمال الواو في لفظ وسيرى»","url":""}]},{"id":"s9-520","number":520,"surah":9,"verses":[95],"references":[{"surah":9,"verses":[95]}],"verseLabel":"التوبة: 95","question":"لماذا سيحلفون بالله عند الرجوع: ﴿لتعرضوا عنهم﴾؟","answer":"يحلفون لتكون غاية المؤمنين مجرد ترك اللوم والمؤاخذة، لا التصديق والمحبة؛ فهم يريدون السلامة من تبعات تخلفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص126، تحت «دلالة اللام في قوله لتعرضوا»","url":""}]},{"id":"s9-521","number":521,"surah":9,"verses":[95],"references":[{"surah":9,"verses":[95]}],"verseLabel":"التوبة: 95","question":"لماذا جاء الأمر: ﴿فأعرضوا عنهم﴾ موافقًا لما طلبوه؟","answer":"أُمروا بالإعراض لا عفوًا ولا رضا، بل إعراض هجر واحتقار؛ فوافق اللفظ مطلوبهم وخالف مرادهم، إذ أرادوا سلامة وقبولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص128، تحت «الغرض من الأمر في الفعل فأعرضوا»","url":""}]},{"id":"s9-522","number":522,"surah":9,"verses":[95],"references":[{"surah":9,"verses":[95]}],"verseLabel":"التوبة: 95","question":"لماذا علل الإعراض بقوله: ﴿إنهم رجس﴾؟","answer":"الرجس الخبث المعنوي الناشئ من النفاق والكذب؛ فالبعد عنهم صيانة للمؤمنين لا استجابة تكريم لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص128، تحت «دلالة فصل جملة إنهم رجس»","url":""}]},{"id":"s9-523","number":523,"surah":9,"verses":[95],"references":[{"surah":9,"verses":[95]}],"verseLabel":"التوبة: 95","question":"ما دلالة التعبير بالجملة الاسمية في قوله تعالى: ﴿ومأواهم جهنم﴾؟","answer":"تفيد الجملة الاسمية ثبات هذا المصير واستقراره؛ فجهنم هي المأوى الذي ينتهون إليه ويلزمونه جزاء نفاقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص130، تحت «فائدة التعبير بالاسمية في ومأواهم جهنم»","url":""}]},{"id":"s9-758","number":758,"surah":9,"verses":[95],"references":[{"surah":9,"verses":[95]}],"verseLabel":"التوبة: 95","question":"ما سرّ التعبير بقوله تعالى: ﴿بما كانوا يكسبون﴾؟","answer":"نسب الجزاء إلى ما تعمدوا اكتسابه من الكذب والنفاق، فدلّ على أن العذاب ثمرة طريق اختاروه وداوموا عليه، لا عقوبة بلا سبب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص131، تحت «سر التعبير بيكسبون»","url":""}]},{"id":"s9-524","number":524,"surah":9,"verses":[96],"references":[{"surah":9,"verses":[96]}],"verseLabel":"التوبة: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿يحلفون لكم لترضوا عنهم﴾ بعد قوله في الآية السابقة ﴿لتعرضوا عنهم﴾؟","answer":"في الأولى طلب ترك اللوم والمؤاخذة، وفي الثانية بيان طلب الرضا عنهم، وهو أزيد من مجرد الإعراض. ويعرض المصدر أوجهًا في تكرار الحلف تتعلق باختلاف غرضه أو المخاطبين به؛ فلا يلزم أن يكون حلفًا لاحقًا في الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص132، تحت «غرض تكرار الحلف في يحلفون بعد سيحلفون»","url":""}]},{"id":"s9-525","number":525,"surah":9,"verses":[96],"references":[{"surah":9,"verses":[96]}],"verseLabel":"التوبة: 96","question":"ما دلالة الفاء ومعناها في قوله تعالى: ﴿فإن ترضوا عنهم فإن الله لا يرضى عن القوم الفاسقين﴾؟","answer":"رضا الناس لا يغير حكم الله؛ فإن رضي المؤمنون ظاهرًا بسبب الحلف، فإن الله لا يرضى عن قوم رسخ فسقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص134، تحت «دلالة الفاء ومعناها»","url":""}]},{"id":"s9-526","number":526,"surah":9,"verses":[96],"references":[{"surah":9,"verses":[96]}],"verseLabel":"التوبة: 96","question":"لماذا لم ينه المؤمنين مباشرة عن الرضا، بل بيّن أن الله لا يرضى؟","answer":"المقصود تحذير المؤمنين من الرضا عنهم؛ إذ إن رضا الناس لا ينفع مع سخط الله. فذكر أن الله لا يرضى عن الفاسقين يحمل المؤمنين على الامتناع عن الرضا الذي يناقض حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص135، تحت «بلاغة التعبير بالجملة الشرطية فإن ترضوا عنهم»","url":""}]},{"id":"s9-527","number":527,"surah":9,"verses":[97],"references":[{"surah":9,"verses":[97]}],"verseLabel":"التوبة: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿الأعراب أشد كفرًا ونفاقًا﴾، دون أن يقال: «كل الأعراب كفار»؟","answer":"ليس في الآية تعميم الحكم على جميع الأعراب؛ بل بيان أن بيئة البداوة فيمن كفر أو نافق تجعل كفره ونفاقه أشد لبعده عن العلم، وقد استثنت الآيات التالية مؤمنيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص146–147، 170، تحت «دلالة أل على الجنس في لفظ الأعراب»","url":""}]},{"id":"s9-528","number":528,"surah":9,"verses":[97],"references":[{"surah":9,"verses":[97]}],"verseLabel":"التوبة: 97","question":"لماذا جمع بين الكفر والنفاق في وصف الأعراب؟","answer":"جمعهما لاستيعاب الفريقين: من أظهر الكفر ومن ستره بالنفاق، أو لأن بعضهم جمع شدة الكفر الباطن وإظهار الإسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص149، تحت «دلالة الجمع بين الكفر والنفاق في قوله كفرًا ونفاقًا»","url":""}]},{"id":"s9-529","number":529,"surah":9,"verses":[97],"references":[{"surah":9,"verses":[97]}],"verseLabel":"التوبة: 97","question":"ما صلة قوله: ﴿وأجدر ألا يعلموا حدود ما أنزل الله﴾ بوصف الأعراب بالشدة في الكفر والنفاق؟","answer":"عطف صفة الجهل بحدود الشرع على شدة الكفر والنفاق، فجمع وصفين يرتبطان ببعدهم عن مجالس العلم وسماع الوحي. وأجدر بمعنى أحق وأخلق بهذا الجهل بحسب حالهم المذكورة، وليس حكمًا لازمًا لكل فرد من الأعراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص150، تحت «دلالة العطف في جملة وأجدر»","url":""}]},{"id":"s9-530","number":530,"surah":9,"verses":[97],"references":[{"surah":9,"verses":[97]}],"verseLabel":"التوبة: 97","question":"ما سرّ اختيار لفظ حدود في قوله تعالى: ﴿حدود ما أنزل الله على رسوله﴾؟","answer":"الحدود هي أحكام الله الفاصلة بين الحلال والحرام والطاعة والمعصية، وإضافتها إلى ما أنزل وربطها بالرسول ﷺ يثبت مصدرها وطريق تبليغها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص151، تحت «سر اختيار لفظ حدود»","url":""}]},{"id":"s9-531","number":531,"surah":9,"verses":[97],"references":[{"surah":9,"verses":[97]}],"verseLabel":"التوبة: 97","question":"لماذا ختم وصف الأعراب بـ﴿والله عليم حكيم﴾؟","answer":"هو عليم بخفايا النفوس وأحوال هؤلاء الأعراب، وحكيم في تدبير خلقه وجزائهم؛ فناسب الاسمان بيان صفاتهم وما يستحقونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص153، تحت «سر تذييل الآية بقوله والله عليم حكيم»","url":""}]},{"id":"s9-759","number":759,"surah":9,"verses":[97],"references":[{"surah":9,"verses":[97]}],"verseLabel":"التوبة: 97","question":"لماذا قدم ﴿عليم﴾ على ﴿حكيم﴾ في ختام وصف الأعراب؟","answer":"لأن الحكم المحكم يقوم على العلم، فقدم ما هو أساس الحكمة ومبدؤها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص154، تحت «نكتة التقديم عليم على حكيم»","url":""}]},{"id":"s9-760","number":760,"surah":9,"verses":[97],"references":[{"surah":9,"verses":[97]}],"verseLabel":"التوبة: 97","question":"ما سر التعبير بالجملة الاسمية في ﴿والله عليم حكيم﴾؟","answer":"تفيد الجملة الاسمية ثبوت العلم والحكمة لله ودوام اتصافه بهما، لا حدوثهما في وقت دون وقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص154، تحت «سر التعبير بالجملة الاسمية»","url":""}]},{"id":"s9-532","number":532,"surah":9,"verses":[98],"references":[{"surah":9,"verses":[98]}],"verseLabel":"التوبة: 98","question":"ما سرّ التعبير في قوله تعالى عن بعض الأعراب: ﴿يتخذ ما ينفق مغرمًا﴾؟","answer":"يعد النفقة غرامة وخسارة لازمة لا قربة؛ لأنه يدفعها كارهًا بلا إيمان بثوابها، فكشف اللفظ ميزانه المادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص156، تحت «نكتة التعبير بلفظ يتخذ»","url":""}]},{"id":"s9-533","number":533,"surah":9,"verses":[98],"references":[{"surah":9,"verses":[98]}],"verseLabel":"التوبة: 98","question":"ما دلالة المضارع في قوله عن الأعراب المنافقين: ﴿ما ينفق﴾؟","answer":"يفيد تجدد الإنفاق؛ فكلما وقعت منهم نفقة نظروا إليها على أنها غرامة وخسارة. وبذلك يصور استمرار هذا الموقف منهم مع تجدد النفقة، لا حكمهم على نفقة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص159، تحت «دلالة التعبير بالمضارع ينفق»","url":""}]},{"id":"s9-534","number":534,"surah":9,"verses":[98],"references":[{"surah":9,"verses":[98]}],"verseLabel":"التوبة: 98","question":"ما سرّ التعبير في قوله تعالى: ﴿ويتربص بكم الدوائر﴾ بصيغة الجمع؟","answer":"الدوائر جمع دائرة، وهي تقلبات الدهر ومصائبه؛ والجمع يدل على ترقبهم أنواع النكبات متتابعة بالمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص161، تحت «نكتة التعبير بالجمع الدوائر»","url":""}]},{"id":"s9-535","number":535,"surah":9,"verses":[98],"references":[{"surah":9,"verses":[98]}],"verseLabel":"التوبة: 98","question":"لماذا جاء الجزاء: ﴿عليهم دائرة السوء﴾ من جنس لفظهم؟","answer":"رد الدعاء عليهم من جنس لفظهم: ما تمنوه للمؤمنين يحيق بهم، و﴿دائرة السوء﴾ تخصهم بالدائرة القبيحة العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص162، تحت «سر المغايرة بالتعبير دائرة السوء مقابل الدوائر»","url":""}]},{"id":"s9-536","number":536,"surah":9,"verses":[98],"references":[{"surah":9,"verses":[98]}],"verseLabel":"التوبة: 98","question":"لماذا ختم بـ﴿والله سميع عليم﴾؟","answer":"﴿سميع﴾ لأقوالهم ودعائهم الخفي، و﴿عليم﴾ بما تضمره قلوبهم من تربص وكراهة؛ فلا يخفى نفاقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص165، تحت «نكتة التذييل بالاسمين الجليلين سميع عليم»","url":""}]},{"id":"s9-537","number":537,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"لماذا استدرك بصورة أخرى من الأعراب: ﴿ومن الأعراب من يؤمن بالله واليوم الآخر﴾؟","answer":"جاءت المقابلة لرفع التعميم: ليس الأعراب سواء، فمنهم مؤمن صادق يجعل نفقته قربة بعد ذكر من يجعلها مغرمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص170، تحت «دلالة أل في الأعراب»","url":""}]},{"id":"s9-538","number":538,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"لماذا تكرر تركيب ﴿يتخذ ما ينفق﴾ في الفريقين مع اختلاف النتيجة؟","answer":"اتحد العمل الظاهر وهو الإنفاق، واختلفت النية: الكافر يراه غرامة، والمؤمن يتخذه قربات؛ فدل التكرار على أن قيمة العمل بنيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص172، تحت «سر التعبير بقوله يتخذ دون يحتسب»","url":""}]},{"id":"s9-539","number":539,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"ما دلالة تسمية النفقات ﴿قربات﴾؟","answer":"سميت قربات لأنها أسباب تقرّب أصحابها إلى رضا الله وثوابه؛ فعبّر بالمسبَّب عن سببه، وفيه إشعار بصدق نيتهم في الإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص172، تحت «الغرض من التعبير بالمجاز المرسل القربات»","url":""}]},{"id":"s9-761","number":761,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"ما دلالة إضافة ﴿الصلوات﴾ إلى الرسول ﷺ؟","answer":"الإضافة تبين أن دعاء الرسول ﷺ لهم بالخير والبركة ثمرة من ثمرات صدقهم، فجمع لهم قبول الله ودعاء رسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص175، تحت «فائدة إضافة الصلوات للرسول الأكرم»","url":""}]},{"id":"s9-540","number":540,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"لماذا جاءت ﴿قربات﴾ بالجمع؟","answer":"لأن وجوه التقرب تتعدد بتعدد النفقات والطاعات والنيات الصالحة، فكل نفقة صادقة باب قرب مستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص172، تحت «سر التعبير بالجمع قربات دون قربة بالإفراد»","url":""}]},{"id":"s9-762","number":762,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"لماذا جاءت ﴿صلوات الرسول﴾ بالجمع؟","answer":"يشير الجمع إلى تكرر دعوات الرسول ﷺ لهم وتنوع ما تتضمنه من رحمة وبركة وخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص175، تحت «نكتة الجمع صلوات في قوله وصلوات الرسول»","url":""}]},{"id":"s9-541","number":541,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"لماذا أكد بقوله: ﴿ألا إنها قربة لهم﴾؟","answer":"افتتحت الجملة بألا التنبيهية وأكدت بإن وبالجملة الاسمية؛ تثبيتًا لصدق رجائهم في القرب من الله وبشارة بقبول نفقتهم. فليست القربة مجرد اعتقاد منهم، بل شهد الله لهم بتحققها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص175، تحت «الغرض من استئناف ألا إنها قربة لهم في السياق»","url":""}]},{"id":"s9-542","number":542,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿سيدخلهم الله في رحمته﴾، فصوّر الرحمة مكانًا يدخلونه؟","answer":"صورت الرحمة فضاء يحيط بهم ويدخلون فيه، للدلالة على شمولها وتمكنهم منها؛ والسين وعد بتحقق ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص177، تحت «دلالة دخول السين في سيدخلهم»","url":""}]},{"id":"s9-543","number":543,"surah":9,"verses":[99],"references":[{"surah":9,"verses":[99]}],"verseLabel":"التوبة: 99","question":"لماذا ختم بـ﴿إن الله غفور رحيم﴾؟","answer":"﴿غفور﴾ لما يقع منهم من تقصير، و﴿رحيم﴾ يقبل نفقتهم ويدخلهم في رحمته؛ فناسبت الخاتمة وعد المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص178، تحت «دلالة فصل جملة إن الله غفور رحيم عما قبلها»","url":""}]},{"id":"s9-544","number":544,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"ما سرّ تقديم ﴿السابقون الأولون﴾ قبل المهاجرين والأنصار؟","answer":"﴿السابقون﴾ وصف جامع، ثم بين أنهم الأوائل من المهاجرين والأنصار؛ وتقديم الوصف يشرف السبق نفسه ويجعله أساس المنزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص185، تحت «معنى أل في السابقون»","url":""}]},{"id":"s9-545","number":545,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿من المهاجرين والأنصار﴾، فقدم المهاجرين؟","answer":"قُدم المهاجرون لسبقهم إلى الإيمان وتحملهم مفارقة الديار والأموال، ثم الأنصار الذين آووا ونصروا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص187–188، تحت «دلالة تقديم المهاجرين على الأنصار»","url":""}]},{"id":"s9-546","number":546,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"لماذا قيد أتباعهم بقوله: ﴿بإحسان﴾؟","answer":"قيد الاتباع بالإحسان حتى لا تكون مجرد الدعوى أو الصحبة كافية؛ بل لا بد من اقتفاء منهج السابقين في صحة الاعتقاد والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص190، تحت «معنى الباء في بإحسان»","url":""}]},{"id":"s9-547","number":547,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"ما وجه البلاغة في المشاكلة بين رضا الله عنهم ورضاهم عنه في قوله تعالى: ﴿رضي الله عنهم ورضوا عنه﴾؟","answer":"رضاه عنهم يتضمن قبول صالح أعمالهم ومغفرة ذنوبهم وإدخالهم الجنة. ورضاهم عنه شكرهم له على نعمه وإيمانهم به وطاعتهم له، ورضاهم بما أعطاهم؛ فاجتمع الجزاء الكريم ورضا العبد وشكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص194، تحت «بلاغة المشاكلة بين رضا الله عنهم ورضاهم عنه»","url":""}]},{"id":"s9-548","number":548,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"ما سرّ تقديم رضا الله عنهم على رضاهم عنه؟","answer":"رضا الله أعلى مراتب الجزاء، فناسب تقديمه. كما أن رضاهم بما نالوه من النعمة والكرامة تابع لرضاه عنهم، فتقدم السبب على ما نشأ عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص193، تحت «نكتة تقديم رضاه عنهم قبل رضاهم عنه»","url":""}]},{"id":"s9-549","number":549,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"لماذا جمع بين الرضوان وإعداد الجنات؟","answer":"الرضوان نعيم معنوي وسبب القبول، والجنات نعيم حسي دائم؛ فجمع كرامة القرب ومتعة المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص194، تحت «بلاغة العطف في وأعد لهم جنات»","url":""}]},{"id":"s9-550","number":550,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"ما فائدة قوله تعالى: ﴿أبدًا﴾ بعد ﴿خالدين فيها﴾؟","answer":"يزيل ﴿أبدًا﴾ كل توهم لانتهاء الخلود أو انقطاع النعيم، فيؤكد امتداده الدائم الذي لا تحده غاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص199، تحت «فائدة الظرف أبدًا بعد التعبير بالخلود»","url":""}]},{"id":"s9-763","number":763,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"لماذا وُصف الفوز بأنه ﴿العظيم﴾؟","answer":"لأنه فوز يجمع رضا الله والنعيم الدائم والنجاة من العذاب، فلا يدانيه فوز دنيوي محدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص201، تحت «فائدة وصف الفوز بالعظيم»","url":""}]},{"id":"s9-551","number":551,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"لماذا قدّم في التوبة: ﴿رضي الله عنهم ورضوا عنه﴾ على ذكر الجنات، بينما قدّم في المائدة الجنات ثم قال: ﴿رضي الله عنهم ورضوا عنه﴾؟","answer":"في التوبة كان المقام مقام الثناء على السابقين واتباعهم، فقدم الرضا المتعلق بأعمالهم ثم ثنى بالجزاء؛ وفي المائدة كان المقام مقام جزاء الصادقين يوم القيامة، فقدم الجنة ثم ختم برضا الطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص171–172، تحت «التشابه بين آيتي سورة المائدة والتوبة وسر تقديم الرضا في إحداهما دون الأخرى»","url":""}]},{"id":"s9-552","number":552,"surah":9,"verses":[100],"references":[{"surah":9,"verses":[100]}],"verseLabel":"التوبة: 100","question":"ما سرّ التعبير في قوله تعالى في أكثر آيات الجنة: ﴿تجري من تحتها الأنهار﴾، وحذف ﴿من﴾ في التوبة فقال: ﴿تجري تحتها الأنهار﴾؟","answer":"الإثبات بـ﴿من تحتها﴾ يدل على ابتداء جريان الأنهار من تحت الجنات أو أشجارها، وحذف ﴿من﴾ في التوبة يكتفي بتصوير جريانها تحتها؛ والتنويع اللفظي مع بقاء أصل النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص197–198، تحت «بلاغة القراءات القرآنية المتواترة»","url":""}]},{"id":"s9-553","number":553,"surah":9,"verses":[101],"references":[{"surah":9,"verses":[101]}],"verseLabel":"التوبة: 101","question":"ما النكتة البلاغية في العطف في ومن أهل المدينة في قوله تعالى: ﴿وممن حولكم من الأعراب منافقون ومن أهل المدينة﴾؟","answer":"قدم منافقي الأعراب المحيطين بالمدينة ثم عطف منافقي أهلها، فدل على إحاطة الخطر من خارج المدينة وداخلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص210، تحت «نكتة العطف في ومن أهل المدينة»","url":""}]},{"id":"s9-554","number":554,"surah":9,"verses":[101],"references":[{"surah":9,"verses":[101]}],"verseLabel":"التوبة: 101","question":"إلى ماذا يعود الضمير في مردوا في قوله تعالى: ﴿مردوا على النفاق﴾؟","answer":"﴿مردوا﴾ أي مرنوا وتمرنوا واستمروا على النفاق حتى صار لهم عادة ومهارة، فهو أبلغ من مجرد وقوعهم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص213، تحت «عود الضمير في مردوا»","url":""}]},{"id":"s9-555","number":555,"surah":9,"verses":[101],"references":[{"surah":9,"verses":[101]}],"verseLabel":"التوبة: 101","question":"ما وجه قوله تعالى للنبي ﷺ: ﴿لا تعلمهم نحن نعلمهم﴾ مع فراسته ووحيه؟","answer":"المنفي علم أشخاص بأعيانهم ممن أخفى النفاق وأتقنه، لا مطلق فراسة النبي ﷺ أو ما أعلمه الله به؛ فعلم الغيب لله ويطلع رسوله على ما يشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص215، تحت «فائدة العدول من الفعلية إلى الاسمية»","url":""}]},{"id":"s9-556","number":556,"surah":9,"verses":[101],"references":[{"surah":9,"verses":[101]}],"verseLabel":"التوبة: 101","question":"لماذا انتقل من الغيبة إلى ضمير العظمة: ﴿نحن نعلمهم سنعذبهم﴾؟","answer":"ضمير العظمة يبرز اختصاص الله بإحاطة العلم بهم وبالقدرة على عقوبتهم، في مقابلة خفائهم عن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص214، تحت «بلاغة المؤكدات في التعبير بالاسمية وذكر المسند إليه مرتين في جملة نحن نعلمهم»","url":""}]},{"id":"s9-557","number":557,"surah":9,"verses":[101],"references":[{"surah":9,"verses":[101]}],"verseLabel":"التوبة: 101","question":"كيف يزيد قوله: ﴿سنعذبهم مرتين﴾ الوعيد للمنافقين؟","answer":"يؤكد السين تحقق الوعيد، وتفيد مرتين تكرر العقوبة قبل العذاب العظيم في الآخرة. ويعرض المصدر أوجهًا في العذابين، منها عذاب الدنيا وعذاب القبر، كما يذكر احتمال إرادة التكثير؛ فلا يجزم بتعيين صورة واحدة للعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص217، تحت «دلالة دخول سين التسويف على العذاب»","url":""}]},{"id":"s9-558","number":558,"surah":9,"verses":[101],"references":[{"surah":9,"verses":[101]}],"verseLabel":"التوبة: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم يردون إلى عذاب عظيم﴾ بعد العذاب مرتين؟","answer":"بعد عقوبتين قبل القيامة يردون إلى عذاب الآخرة العظيم؛ و﴿ثم﴾ تدل على تراخي المراحل مع تفاوت عظم العذاب الأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص219، تحت «فائدة وصف العذاب بأنه عظيم»","url":""}]},{"id":"s9-559","number":559,"surah":9,"verses":[102],"references":[{"surah":9,"verses":[102]}],"verseLabel":"التوبة: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿وآخرون اعترفوا بذنوبهم﴾ دون ذكر اعتذارهم؟","answer":"الاعتراف الصادق يغني عن الاعتذار المصنوع؛ فهم أقروا بالذنب ولم يحاولوا تزيينه، فتميزوا من المنافقين المعتذرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص221، تحت «معنى الباء في بذنوبهم»","url":""}]},{"id":"s9-560","number":560,"surah":9,"verses":[102],"references":[{"surah":9,"verses":[102]}],"verseLabel":"التوبة: 102","question":"ما دلالة إضافة الذنوب إلى ضميرهم في قوله: ﴿اعترفوا بذنوبهم﴾؟","answer":"تؤكد الإضافة تحملهم مسؤولية ما اقترفوه وصدق ندمهم؛ فهم يقرون بأنها ذنوبهم التي فعلوها، ولا يدفعون تبعتها إلى غيرهم أو يسترونها بأعذار مصنوعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص221–222، تحت «غرض إضافة الذنوب إلى ضميرهم»","url":""}]},{"id":"s9-561","number":561,"surah":9,"verses":[102],"references":[{"surah":9,"verses":[102]}],"verseLabel":"التوبة: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿خلطوا عملًا صالحًا وآخر سيئًا﴾، فجعل العملين كشيئين يختلطان؟","answer":"شبهت الأعمال بأشياء مزج بعضها ببعض؛ إذ لم يخلص حالهم للصلاح ولا للسوء، بل اجتمع صدق الإيمان مع معصية التخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص223، تحت «دلالة التعبير بخلطوا مادة وصيغة»","url":""}]},{"id":"s9-562","number":562,"surah":9,"verses":[102],"references":[{"surah":9,"verses":[102]}],"verseLabel":"التوبة: 102","question":"ما سرّ تقديم العمل الصالح على السيئ؟","answer":"في تقديم الصالح تشريف له وتنويه بما في حالهم من خير؛ فقد خالط تقصيرهم عمل صالح، فرجح ذلك جانب الرجاء فيهم. ولا يلزم من التقديم وحده أن يكون الصلاح غالبًا على جميع أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص223، تحت «نكتة التنكير والإفراد في عملًا وصالحًا وتقديمهما»","url":""}]},{"id":"s9-563","number":563,"surah":9,"verses":[102],"references":[{"surah":9,"verses":[102]}],"verseLabel":"التوبة: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿عسى الله أن يتوب عليهم﴾ مع اعترافهم وندمهم؟","answer":"﴿عسى﴾ من جهة المخاطبين تربيهم بين الرجاء والخوف ولا تجعل التوبة حقًا واجبًا لهم، ووعد الله بها متحقق لمن صدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص226، تحت «غرض التعبير بالمضارع في يتوب»","url":""}]},{"id":"s9-564","number":564,"surah":9,"verses":[102],"references":[{"surah":9,"verses":[102]}],"verseLabel":"التوبة: 102","question":"لماذا ختمت آية المعترفين بذنوبهم (التوبة: 102) بـ﴿إن الله غفور رحيم﴾؟","answer":"﴿غفور﴾ يستر ذنوب المعترفين إذا تابوا، و﴿رحيم﴾ يقبلهم ويعيدهم إلى أهل الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص226، تحت «بلاغة التذييل بهذين الاسمين الجليلين»","url":""}]},{"id":"s9-764","number":764,"surah":9,"verses":[102],"references":[{"surah":9,"verses":[102]}],"verseLabel":"التوبة: 102","question":"ما غرض صيغ المبالغة في ﴿غفور رحيم﴾؟","answer":"تفيد كثرة المغفرة وسعة الرحمة ودوامهما، فتفتح للمعترفين باب التوبة والقبول مهما عظم تقصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص228، تحت «غرض صيغ المبالغة فيهما»","url":""}]},{"id":"s9-565","number":565,"surah":9,"verses":[103],"references":[{"surah":9,"verses":[103]}],"verseLabel":"التوبة: 103","question":"لماذا أُمر النبي ﷺ أن يأخذ من أموالهم صدقة بعد اعترافهم؟","answer":"كان أخذ الصدقة مظهرًا عمليًا لصدق توبتهم، ولا سيما أن التعلق بالأموال والتثاقل عن الإنفاق كان من أسباب تخلفهم. فبذل المال يعالج هذا التقصير، وتكون الصدقة سببًا لتطهيرهم وتزكيتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص233، تحت «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s9-566","number":566,"surah":9,"verses":[103],"references":[{"surah":9,"verses":[103]}],"verseLabel":"التوبة: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿تطهرهم وتزكيهم بها﴾، وما الفرق بين التطهير والتزكية؟","answer":"التطهير إزالة دنس الذنب والبخل، والتزكية تنمية الخير والبركة ورفع المنزلة؛ فالصدقة تزيل النقص وتنمي الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص268، تحت «التطهير والتزكية»","url":""}]},{"id":"s9-567","number":567,"surah":9,"verses":[103],"references":[{"surah":9,"verses":[103]}],"verseLabel":"التوبة: 103","question":"كيف يختلف إسناد التطهير في ﴿تطهرهم﴾ بحسب عود التاء إلى النبي ﷺ أو إلى الصدقة؟","answer":"يجوز أن تكون التاء للخطاب، فيكون النبي ﷺ مطهرًا لهم بأخذ صدقتهم. ويجوز أن تكون للغيبة، فيكون الفاعل ضمير الصدقة؛ فهي سبب تطهيرهم بما يترتب عليها من مغفرة وثواب. ويرجع الوجهان إلى بيان أثر الصدقة المقبولة في أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص242، تحت «نكتة عود التاء في تطهرهم»","url":""}]},{"id":"s9-568","number":568,"surah":9,"verses":[103],"references":[{"surah":9,"verses":[103]}],"verseLabel":"التوبة: 103","question":"ما وجه البلاغة في الاستئناف البياني إن صلاتك سكن لهم في قوله تعالى: ﴿وصل عليهم إن صلاتك سكن لهم﴾؟","answer":"الصلاة عليهم دعاء لهم، و﴿سكن﴾ طمأنينة تستقر بها قلوبهم لقبول توبتهم وبركة دعاء الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص247، تحت «بلاغة الاستئناف البياني إن صلاتك سكن لهم»","url":""}]},{"id":"s9-569","number":569,"surah":9,"verses":[103],"references":[{"surah":9,"verses":[103]}],"verseLabel":"التوبة: 103","question":"لماذا عبر باسم الألوهية دون الربوبية في هذا السياق؟","answer":"لأن اسم الجلالة يجمع صفات الكمال ويوافق مقام العبادة والتطهير وقبول التوبة، وهو أعم من استحضار معنى التربية وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص251، تحت «سر التعبير بالألوهية دون الربوبية»","url":""}]},{"id":"s9-765","number":765,"surah":9,"verses":[103],"references":[{"surah":9,"verses":[103]}],"verseLabel":"التوبة: 103","question":"لماذا ختمت آية أخذ الصدقة (التوبة: 103) بـ﴿والله سميع عليم﴾؟","answer":"هو سميع لدعاء الرسول واعترافهم، وعليم بصدق نياتهم وتوبتهم؛ فيجازي كلًا على ظاهره وباطنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص252، تحت «بلاغة التذييل بهذين الاسمين الجليلين»","url":""}]},{"id":"s9-766","number":766,"surah":9,"verses":[103],"references":[{"surah":9,"verses":[103]}],"verseLabel":"التوبة: 103","question":"لماذا قدم ﴿سميع﴾ على ﴿عليم﴾؟","answer":"لأن السياق بدأ بالدعاء المسموع، فقدم السمع المتصل بظاهر القول ثم أتبع بالعلم المحيط بالنيات والسرائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص252، تحت «نكتة تقديم سميع على عليم»","url":""}]},{"id":"s9-570","number":570,"surah":9,"verses":[104],"references":[{"surah":9,"verses":[104]}],"verseLabel":"التوبة: 104","question":"لماذا سأل: ﴿ألم يعلموا أن الله هو يقبل التوبة عن عباده ويأخذ الصدقات﴾؟","answer":"الاستفهام للتقرير والحض على التوبة والصدقة؛ فالله وحده يقبل توبة عباده ويقبل صدقاتهم، فلا ييأس المذنب ولا يمن بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص253، تحت «نكتة فصل الآية ألم يعلموا أن الله هو يقبل عن سابقتها»","url":""}]},{"id":"s9-571","number":571,"surah":9,"verses":[104],"references":[{"surah":9,"verses":[104]}],"verseLabel":"التوبة: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿يقبل التوبة عن عباده﴾ بـ﴿عن﴾ لا «من»؟","answer":"﴿عن﴾ تشعر بالتجاوز والصفح عن الذنب عند قبول التوبة، أما ﴿من﴾ فمجرد ابتداء الأخذ من التائب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص260، تحت «بلاغة تضمين الفعل يقبل الفعل يتجاوز وتعديتها بعن»","url":""}]},{"id":"s9-572","number":572,"surah":9,"verses":[104],"references":[{"surah":9,"verses":[104]}],"verseLabel":"التوبة: 104","question":"ما سرّ نسبة أخذ الصدقات إلى الله مع أن النبي ﷺ هو الذي يأخذها؟","answer":"نسب الأخذ إلى الله لأنه الآمر بالصدقة والمتقبل لها والمثيب عليها، والنبي ﷺ مباشر لأخذها؛ فنسب الفعل إلى مسبب قبوله وغايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص263، تحت «بلاغة الاستعارة في أخذ الصدقات»","url":""}]},{"id":"s9-573","number":573,"surah":9,"verses":[104],"references":[{"surah":9,"verses":[104]}],"verseLabel":"التوبة: 104","question":"لماذا جاء ضمير الفصل في ﴿وأن الله هو التواب الرحيم﴾؟","answer":"ضمير الفصل ﴿هو﴾ يقصر كمال قبول التوبة والرحمة على الله، ويؤكد أنه كثير التوبة على عباده لا يرده ذنب مع صدق الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص266، تحت «بلاغة القصر في تعريف طرفي الإسناد وفي ضمير الفصل»","url":""}]},{"id":"s9-574","number":574,"surah":9,"verses":[105],"references":[{"surah":9,"verses":[105]}],"verseLabel":"التوبة: 105","question":"لماذا جاء الأمر المطلق: ﴿وقل اعملوا﴾ بعد الحديث عن التوبة والصدقة؟","answer":"الأمر عام ليستأنف التائبون عملًا يصدق توبتهم، ويعلم الجميع أن الاعتبار بما يعملون بعد الدعوى والاعتراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص271، تحت «بلاغة العطف في وقل اعملوا»","url":""}]},{"id":"s9-575","number":575,"surah":9,"verses":[105],"references":[{"surah":9,"verses":[105]}],"verseLabel":"التوبة: 105","question":"ما معنى الفاء في فسيرى في قوله تعالى: ﴿فسيرى الله عملكم ورسوله والمؤمنون﴾؟","answer":"الفاء تصل العمل بنتيجته القريبة: لا يخفى على الله، ويظهر أثره للرسول والمؤمنين؛ ففيها وعد للمحسن ووعيد للمسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص273، تحت «معنى الفاء في فسيرى»","url":""}]},{"id":"s9-576","number":576,"surah":9,"verses":[105],"references":[{"surah":9,"verses":[105]}],"verseLabel":"التوبة: 105","question":"لماذا أعيد ذكر رؤية الله والرسول للعمل بعد الآية 94 وزيد هنا ﴿المؤمنون﴾؟","answer":"آية 94 في المنافقين وضمائرهم الخفية، فاقتصر على الله ورسوله بإطلاع الله؛ وهذه في التائبين المؤمنين وأعمالهم الظاهرة، فزاد ﴿المؤمنون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص285، تحت «سر ذكر لفظ والمؤمنون هنا وعدم حذفه»","url":""}]},{"id":"s9-577","number":577,"surah":9,"verses":[105],"references":[{"surah":9,"verses":[105]}],"verseLabel":"التوبة: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿وستردون إلى عالم الغيب والشهادة﴾ بدل «إلى الله»؟","answer":"الوصف يستحضر إحاطة علمه بكل باطن وظاهر عند الرجوع إليه؛ فلا ينفع ستر النية ولا تجميل العمل أمام الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص280، تحت «سر العدول عن الظاهر للمضمر في عالم الغيب والشهادة»","url":""}]},{"id":"s9-578","number":578,"surah":9,"verses":[105],"references":[{"surah":9,"verses":[105]}],"verseLabel":"التوبة: 105","question":"لماذا ختم بـ﴿فينبئكم بما كنتم تعملون﴾؟","answer":"الإنباء إظهار حقيقة الأعمال والحكم عليها والجزاء بها؛ فهو ختام يربط الأمر بالعمل بالحساب النهائي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص282، تحت «معنى الفاء في فينبئكم»","url":""}]},{"id":"s9-579","number":579,"surah":9,"verses":[106],"references":[{"surah":9,"verses":[106]}],"verseLabel":"التوبة: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿وآخرون مرجون لأمر الله﴾ بعد ذكر المعترفين التائبين؟","answer":"بعد من اعترفوا وتابوا ذكر فريقًا أُخر حكمهم مؤخر ينتظر أمر الله؛ فميز بين توبة ظهرت وحال لم يُقض فيها بعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص291، تحت «دلالة العطف في وآخرون»","url":""}]},{"id":"s9-580","number":580,"surah":9,"verses":[106],"references":[{"surah":9,"verses":[106]}],"verseLabel":"التوبة: 106","question":"لماذا بُني ﴿مرجون﴾ للمجهول؟","answer":"البناء للمجهول يركز على حالهم: مؤخرون موقوف أمرهم، مع العلم بأن المؤخر هو الله؛ وفيه تصوير القلق والانتظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص292، تحت «فائدة التعبير بمرجون مادة وصيغة»","url":""}]},{"id":"s9-581","number":581,"surah":9,"verses":[106],"references":[{"surah":9,"verses":[106]}],"verseLabel":"التوبة: 106","question":"لماذا قابل: ﴿إما يعذبهم وإما يتوب عليهم﴾؟","answer":"﴿إما... وإما﴾ تبقيهم بين احتمال العقوبة واحتمال قبول التوبة بحسب علم الله وحكمته، فلا يقطع لهم قبل صدور الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص294، تحت «الموقع البياني إما يعذبهم وإما يتوب عليهم»","url":""}]},{"id":"s9-582","number":582,"surah":9,"verses":[106],"references":[{"surah":9,"verses":[106]}],"verseLabel":"التوبة: 106","question":"ما سرّ تقديم احتمال العذاب على التوبة؟","answer":"قدم العذاب لأن سبب استحقاقه، وهو التخلف بلا عذر، متحقق ظاهرًا، أما التوبة ففضل مرجو متعلق بصدق رجوعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص295–296، تحت «نكتة تقديم العذاب على التوبة»","url":""}]},{"id":"s9-583","number":583,"surah":9,"verses":[106],"references":[{"surah":9,"verses":[106]}],"verseLabel":"التوبة: 106","question":"لماذا ختم الحديث عن المرجئين بـ﴿والله عليم حكيم﴾؟","answer":"هو عليم بحقيقة قلوبهم وتوبتهم، وحكيم في اختيار العذاب أو القبول؛ فلا يكون التأخير عن جهل أو تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص297، تحت «بلاغة التذييل بهذين الاسمين الجليلين»","url":""}]},{"id":"s9-767","number":767,"surah":9,"verses":[106],"references":[{"surah":9,"verses":[106]}],"verseLabel":"التوبة: 106","question":"لماذا قدم ﴿عليم﴾ على ﴿حكيم﴾ في شأن المرجئين؟","answer":"لأن الحكم في قبولهم أو عذابهم مبني على العلم بحقائقهم، فقدم أساس الحكم على أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص297، تحت «نكتة تقديم عليم على حكيم»","url":""}]},{"id":"s9-584","number":584,"surah":9,"verses":[107],"references":[{"surah":9,"verses":[107]}],"verseLabel":"التوبة: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين اتخذوا مسجدًا ضرارًا﴾، فسمى المكان مسجدًا مع فساد قصده؟","answer":"سماه مسجدًا بحسب الصورة والاسم الذي وضعه أصحابه، ثم كشفت الأغراض المنصوبة فساد حقيقته؛ فالعبرة بالمقصد لا بالاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص305، تحت «دلالة التعبير بصيغة الافتعال في اتخذوا»","url":""}]},{"id":"s9-585","number":585,"surah":9,"verses":[107],"references":[{"surah":9,"verses":[107]}],"verseLabel":"التوبة: 107","question":"لماذا عدّد أغراض مسجد الضرار: ضرارًا وكفرًا وتفريقًا وإرصادًا؟","answer":"عددها لكشف طبقات الجريمة: الإضرار بالمؤمنين، وتقوية الكفر، وتفريق الجماعة، وإعداد المكان لمن حارب الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص307، تحت «بلاغة حذف متعلقات ضرارًا وكفرًا»","url":""}]},{"id":"s9-586","number":586,"surah":9,"verses":[107],"references":[{"surah":9,"verses":[107]}],"verseLabel":"التوبة: 107","question":"ما سرّ تقديم الضرار على الكفر؟","answer":"يرتب المصدر الأغراض من الأعم إلى الأخص: فالضرار يشمل الأذى في الدين وغيره، والكفر وتقوية النفاق أخص منه، ثم تفريق المؤمنين، ثم الإرصاد لمن حارب الله ورسوله. فتقديم الضرار يفتتح بالغرض الأوسع ثم يفصل وجوهه الأخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص307–308، تحت «نكتة الترتيب في العطف بين علل اتخاذ المسجد»","url":""}]},{"id":"s9-587","number":587,"surah":9,"verses":[107],"references":[{"surah":9,"verses":[107]}],"verseLabel":"التوبة: 107","question":"ما معنى ﴿إرصادًا لمن حارب الله ورسوله﴾؟","answer":"الإرصاد الإعداد والترقب؛ أي اتخذوه موضعًا مهيأ لمن سبق بمحاربة الله ورسوله ليكون قاعدة له عند قدومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص308، تحت «معنى من في لمن حارب»","url":""}]},{"id":"s9-588","number":588,"surah":9,"verses":[107],"references":[{"surah":9,"verses":[107]}],"verseLabel":"التوبة: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿من قبل﴾ بعد ذكر المحاربة؟","answer":"﴿من قبل﴾ تبين أن المحاربة سابقة على بناء المسجد، وأن الإرصاد امتداد لخطة قديمة لا حادثة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص310، تحت «معنى من في من قبل»","url":""}]},{"id":"s9-589","number":589,"surah":9,"verses":[107],"references":[{"surah":9,"verses":[107]}],"verseLabel":"التوبة: 107","question":"لماذا أكدوا حلفهم: ﴿وليحلفن إن أردنا إلا الحسنى﴾؟","answer":"اللام ونون التوكيد في الحلف تقابلان شناعة مقاصدهم؛ وحصروا إرادتهم في ﴿الحسنى﴾ زاعمين الإحسان والخير لستر الضرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص311، تحت «معنى اللام في وليحلفن ودلالة المؤكدات فيها»","url":""}]},{"id":"s9-590","number":590,"surah":9,"verses":[107],"references":[{"surah":9,"verses":[107]}],"verseLabel":"التوبة: 107","question":"ما معنى الواو في والله يشهد وموقع الجملة بعدها في قوله تعالى: ﴿والله يشهد إنهم لكاذبون﴾؟","answer":"قابل حلفهم بشهادة الله المحيطة ببواطنهم، وأكد كذبهم بـ﴿إن﴾ واللام؛ فشهادة الله أصدق من أيمانهم المؤكدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص313، تحت «معنى الواو في والله يشهد وموقع الجملة بعدها»","url":""}]},{"id":"s9-591","number":591,"surah":9,"verses":[108],"references":[{"surah":9,"verses":[108]}],"verseLabel":"التوبة: 108","question":"لماذا جاء النهي: ﴿لا تقم فيه أبدًا﴾، ولم يقل: «لا تصل فيه»؟","answer":"عبر عن الصلاة بالقيام، وهو ركن منها، فأطلق الجزء وأراد الكل على سبيل المجاز المرسل، مع الاهتمام بشأن هذا الركن. وأكد النهي بأبدًا ليشمل جميع الأزمنة؛ فالمراد في هذا الموضع منع الصلاة في مسجد الضرار منعًا دائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص348، تحت «لا تقم فيه ولا تصل»","url":""}]},{"id":"s9-592","number":592,"surah":9,"verses":[108],"references":[{"surah":9,"verses":[108]}],"verseLabel":"التوبة: 108","question":"لماذا قابل مسجد الضرار بمسجد ﴿أسس على التقوى من أول يوم﴾؟","answer":"المقابلة تكشف أن قيمة المسجد بأساسه وغايته: ذاك أسس للإضرار والكفر، وهذا أسس منذ البدء على تقوى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص318، تحت «بلاغة الاستعارة المكنية في أسس على التقوى»","url":""}]},{"id":"s9-593","number":593,"surah":9,"verses":[108],"references":[{"surah":9,"verses":[108]}],"verseLabel":"التوبة: 108","question":"ما معنى من في من أول يوم في قوله تعالى: ﴿من أول يوم﴾؟","answer":"تدل على أن التقوى صاحبت تأسيسه من أول لحظة ولم تطرأ عليه بعد ذلك، فثبت إخلاص الأصل واستمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص318، تحت «معنى من في من أول يوم»","url":""}]},{"id":"s9-594","number":594,"surah":9,"verses":[108],"references":[{"surah":9,"verses":[108]}],"verseLabel":"التوبة: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿أحق أن تقوم فيه﴾ مع أن القيام في مسجد الضرار منهي عنه؟","answer":"﴿أحق﴾ للمفاضلة بالنظر إلى دعواهم أن مسجدهم أعد للخير، أي هذا وحده أجدر بالقيام؛ ومع النهي عن الآخر تصير الأحقية تعيينًا لا مشاركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص319، تحت «دلالة التعبير بأحق لغة وصرفا»","url":""}]},{"id":"s9-595","number":595,"surah":9,"verses":[108],"references":[{"surah":9,"verses":[108]}],"verseLabel":"التوبة: 108","question":"لماذا وصف أهله بأنهم ﴿يحبون أن يتطهروا﴾، ولم يقل: «يتطهرون»؟","answer":"ذكر محبتهم للتطهر لأنها الدافع الباطني المستمر إلى استعمال أسبابه، والمدح بمحبة الطهارة أبلغ من فعل قد يقع بلا إخلاص أو مداومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص323، تحت «غرض التعبير بالمضارعة في يحبون ويتطهروا»","url":""}]},{"id":"s9-596","number":596,"surah":9,"verses":[108],"references":[{"surah":9,"verses":[108]}],"verseLabel":"التوبة: 108","question":"لماذا ختم بـ﴿والله يحب المطهرين﴾؟","answer":"الخاتمة تعلل مدح أهل المسجد: محبتهم للطهارة عمل يحبه الله، وفيها ترغيب في الجمع بين طهارة الظاهر والباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص324، تحت «معنى الواو في والله»","url":""}]},{"id":"s9-597","number":597,"surah":9,"verses":[109],"references":[{"surah":9,"verses":[109]}],"verseLabel":"التوبة: 109","question":"لماذا صوّر العمل الصالح بأنه بنيان مؤسس على تقوى ورضوان؟","answer":"شُبهت الأعمال ببنيان لأن العقيدة والقصد أساس يحمل العمل؛ فما قام على التقوى ثبت ونفع صاحبه كما يثبت البناء على أصل محكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص332، تحت «بلاغة الاستعارة في تأسيس البنيان على التقوى»","url":""}]},{"id":"s9-598","number":598,"surah":9,"verses":[109],"references":[{"surah":9,"verses":[109]}],"verseLabel":"التوبة: 109","question":"لماذا جمع بين ﴿تقوى من الله ورضوان﴾؟","answer":"التقوى اجتناب سخط الله وهي أساس العمل، والرضوان غايته وثمرته؛ فجمع سلامة المبدأ وحسن المقصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص332، تحت «نكتة تنكير لفظي تقوى ورضوان»","url":""}]},{"id":"s9-599","number":599,"surah":9,"verses":[109],"references":[{"surah":9,"verses":[109]}],"verseLabel":"التوبة: 109","question":"لماذا شبه عمل المنافق ببنيان على ﴿شفا جرف هار﴾؟","answer":"شفا الجرف حافته التي أكلها السيل من أسفل فأشرفت على السقوط. فتمثل الصورة عمل المنافق القائم على أصل واهٍ، ينتهي انهياره بصاحبه إلى الهلاك؛ وتقابله صورة البناء المحكم على التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص334، تحت «بلاغة التشبيه المتفرع عن الاستعارة المكنية في الآية»","url":""}]},{"id":"s9-600","number":600,"surah":9,"verses":[109],"references":[{"surah":9,"verses":[109]}],"verseLabel":"التوبة: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿فانهار به في نار جهنم﴾، فجعل البنيان يهوي بصاحبه؟","answer":"الفاء تصور سرعة الانهيار، والباء في ﴿به﴾ تجعل الباني مصاحبًا لبنيانه في السقوط؛ ففساد العمل يورد صاحبه النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص336، تحت «معنى الفاء في فانهار به»","url":""}]},{"id":"s9-601","number":601,"surah":9,"verses":[109],"references":[{"surah":9,"verses":[109]}],"verseLabel":"التوبة: 109","question":"ما فائدة التعبير بالمضارع في ﴿يهدي﴾؟","answer":"يفيد تجدد نفي التوفيق واستمراره ما داموا مصرين على الظلم، فلا تنفك النتيجة عن سببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص339، تحت «فائدة التعبير بالمضارع يهدي»","url":""}]},{"id":"s9-768","number":768,"surah":9,"verses":[109],"references":[{"surah":9,"verses":[109]}],"verseLabel":"التوبة: 109","question":"لماذا وصفوا بالظلم في ﴿والله لا يهدي القوم الظالمين﴾؟","answer":"لأنهم وضعوا العبادة في غير موضعها واتخذوا المسجد للإضرار والتفريق، فكان الظلم أنسب وصف يكشف حقيقة صنيعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص340، تحت «علة وصفهم بالظلم»","url":""}]},{"id":"s9-602","number":602,"surah":9,"verses":[110],"references":[{"surah":9,"verses":[110]}],"verseLabel":"التوبة: 110","question":"ما النكتة البلاغية في الفصل لا يزال بنيانهم في قوله تعالى: ﴿لا يزال بنيانهم الذي بنوا ريبة في قلوبهم﴾؟","answer":"ظل البناء سبب شك واضطراب في قلوبهم بما تعلق به من نفاق وحسرة بعد هدمه؛ فالجملة تصور دوام أثر الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص341، تحت «نكتة الفصل لا يزال بنيانهم»","url":""}]},{"id":"s9-603","number":603,"surah":9,"verses":[110],"references":[{"surah":9,"verses":[110]}],"verseLabel":"التوبة: 110","question":"لماذا كرر الجذر: ﴿بنيانهم الذي بنوا﴾؟","answer":"التكرار يواجههم بصنيعهم: هذا البنيان المنسوب إليهم هو الذي تعمدوا بناءه، فلا ينفصل أثره عن كسبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص342، تحت «فائدة التعبير بالاسم الموصول وصلته الذي بنوا»","url":""}]},{"id":"s9-604","number":604,"surah":9,"verses":[110],"references":[{"surah":9,"verses":[110]}],"verseLabel":"التوبة: 110","question":"لماذا جعل غاية الريبة: ﴿إلا أن تقطع قلوبهم﴾؟","answer":"المعنى أن الريبة تلازمهم إلى أن تتقطع قلوبهم بالموت أو الندم الشديد؛ فجعل لها غاية تهول استمرارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص343، تحت «نكتة الاستثناء المصدّر بالأداة إلا»","url":""}]},{"id":"s9-605","number":605,"surah":9,"verses":[110],"references":[{"surah":9,"verses":[110]}],"verseLabel":"التوبة: 110","question":"لماذا لم يقل: «حتى يموتوا»؟","answer":"﴿تقطع قلوبهم﴾ يصور الموت أو تمزق القلوب بالحسرة تصويرًا محسوسًا، وهو أبلغ من الخبر المباشر عن انتهاء الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص345، تحت «بلاغة الكناية عن صفة في تقطيع القلوب»","url":""}]},{"id":"s9-606","number":606,"surah":9,"verses":[110],"references":[{"surah":9,"verses":[110]}],"verseLabel":"التوبة: 110","question":"لماذا ختم خبر مسجد الضرار بـ﴿والله عليم حكيم﴾؟","answer":"هو عليم بنياتهم الخفية في البناء، وحكيم في كشفها وهدم مسجد الضرار وترتيب الجزاء عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص346، تحت «سر تذييل الآية بهذين الاسمين الجليلين»","url":""}]},{"id":"s9-769","number":769,"surah":9,"verses":[110],"references":[{"surah":9,"verses":[110]}],"verseLabel":"التوبة: 110","question":"ما سر تقديم العلم على الحكمة؟","answer":"لأن الحكمة في الحكم والجزاء ثمرة العلم بالنيات والحقائق، فقدم السبب الذي يقوم عليه الحكم المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص347، تحت «سر تقديم العلم على الحكمة»","url":""}]},{"id":"s9-607","number":607,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"لماذا صوّر علاقة المؤمن بالله بالبيع: ﴿إن الله اشترى من المؤمنين أنفسهم وأموالهم﴾؟","answer":"البيع تمثيل لعهد المؤمن: يبذل نفسه وماله لله في مقابل الجنة، وفي الصورة توثيق للالتزام وتشريف للعوض والمعوَّض.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص353، تحت «بلاغة الاستعارة إن الله اشترى»","url":""}]},{"id":"s9-608","number":608,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"ما سرّ تقديم الأنفس هنا على الأموال، بخلاف مواضع الجهاد السابقة؟","answer":"قدمت الأنفس لأنها أعز ما يملكه الإنسان، ولأن المقام مقام بذلها حتى القتل في سبيل الله. أما تقديم الأموال في مواضع أخرى فيناسب كونها وسيلة إلى تجهيز الجهاد وحماية النفس؛ فلكل ترتيب ما يلائم سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص355، تحت «علة تقديم الأنفس على الأموال»","url":""}]},{"id":"s9-609","number":609,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"ما وجه تصوير المعاملة بالشراء في قوله تعالى: ﴿إن الله اشترى من المؤمنين أنفسهم وأموالهم﴾ مع أن الله مالكهم ومالك أموالهم؟","answer":"ملك الله لهم أصلي، لكنه عاملهم تفضلًا معاملة المالك المختار، فسمى بذل ما استخلفهم فيه بيعًا وأعطاهم عليه الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص353، تحت «بلاغة الاستعارة إن الله اشترى»","url":""}]},{"id":"s9-610","number":610,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"لماذا جعل الثمن ﴿بأن لهم الجنة﴾؟","answer":"الباء للمقابلة، والجنة ثمن كريم دائم لنفس ومال فانيين؛ وفيه إظهار عظم فضل المشتري وربح المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص355، تحت «معنى الباء في بأن»","url":""}]},{"id":"s9-611","number":611,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿فيقتلون ويُقتلون﴾، وقدم الفعل المعلوم على المبني للمجهول؟","answer":"في قراءة تقديم الفعل المعلوم إبراز لقتالهم عدوهم ثم احتمال قتلهم في سبيل الله؛ وفي القراءة الأخرى قدم المبني للمجهول للاهتمام بالشهادة. وتدل القراءتان على ثباتهم على القتال وإن قتل بعضهم، ولا يلزم أن يقع الفعلان من كل فرد بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص358، تحت «بلاغة توجيه القراءات في فيقتلون ويقتلون»","url":""}]},{"id":"s9-612","number":612,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"لماذا ذكر التوراة والإنجيل والقرآن في توثيق الوعد؟","answer":"ذكر الكتب الثلاثة لبيان قدم الوعد وثباته في الشرائع الكبرى، وأنه عهد إلهي واحد لم ينفرد به القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص361، تحت «بلاغة الترتيب بين الكتب الثلاثة»","url":""}]},{"id":"s9-613","number":613,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن أوفى بعهده من الله﴾ بصيغة السؤال؟","answer":"الاستفهام إنكاري تقريري: لا أحد أوفى بعهده من الله، فيورث اليقين بالعوض ويزيل كل تردد في الصفقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص362، تحت «بلاغة الاستفهام وغرضه ومن أوفى»","url":""}]},{"id":"s9-614","number":614,"surah":9,"verses":[111],"references":[{"surah":9,"verses":[111]}],"verseLabel":"التوبة: 111","question":"لماذا ختم بـ﴿فاستبشروا ببيعكم... وذلك هو الفوز العظيم﴾؟","answer":"الأمر بالاستبشار يعلن تمام الصفقة وربحها، واسم الإشارة مع ﴿هو﴾ يقصر الفوز العظيم على هذا البيع المضمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص366، تحت «بلاغة التذييل التعليلي في الإشارة إلى الفوز العظيم»","url":""}]},{"id":"s9-615","number":615,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"لماذا جاءت صفات المؤمنين سلسلة أسماء: ﴿التائبون العابدون الحامدون...﴾؟","answer":"الأسماء تدل على ثبوت الصفات ورسوخها، وتعرض المؤمنين كأن كل خصلة صارت سمة معروفة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص375، تحت «دلالة التعبير عن أوصاف المؤمنين بأسماء الفاعلين»","url":""}]},{"id":"s9-616","number":616,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"لماذا بدأت الصفات بالتوبة؟","answer":"بدأت بالتوبة لأنها تطهر من الموانع وتفتح طريق العبودية؛ فمن رجع عن الذنب استقام له ما بعدها من الصفات.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص376، تحت «سر ترتيب هذه الصفات»","url":""}]},{"id":"s9-617","number":617,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿السائحون﴾، وما صلتها بالصيام أو طلب العلم والجهاد؟","answer":"السياحة مفارقة المألوف في طاعة الله؛ ففسرت بالصيام لانقطاع الصائم عن الشهوات، وبالسفر في طلب العلم أو الجهاد، ويجمعها التجرد للطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص378، تحت «بلاغة الاستعارة في السائحون»","url":""}]},{"id":"s9-618","number":618,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"لماذا أفرد الركوع والسجود كصفتين بعد العبادة؟","answer":"خُصا لأنهما أبرز هيئات الصلاة وأدلها على الخضوع، والسجود غاية التذلل؛ ففصلا بعد عموم العبادة للتنويه بهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص379، تحت «سر التعبير عن الصلاة ببعض أجزائها»","url":""}]},{"id":"s9-619","number":619,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"لماذا عطف ﴿الناهون عن المنكر﴾ على ﴿الآمرون بالمعروف﴾ بالواو، مع تتابع الصفات السابقة بلا عطف؟","answer":"تتابع الصفات السابقة بلا عطف يصورها صفات متلازمة لموصوف واحد. أما الواو بين الأمر بالمعروف والنهي عن المنكر فتبرز التمييز بين الوظيفتين والاعتداد بكل واحدة، مع تلازمهما في إصلاح الغير؛ فلا يكتفى بأحدهما عن الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص380، تحت «نكتة العطف في الآمرون بالمعروف والناهون عن المنكر»","url":""}]},{"id":"s9-620","number":620,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"لماذا ختم الصفات بـ﴿والحافظون لحدود الله﴾؟","answer":"حفظ الحدود جامع للقيام بالأوامر واجتناب النواهي، فختم به ليستوعب ما لم تفصله الصفات السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص384، تحت «سر ختم هذه الصفات بالحفظ لحدود الله»","url":""}]},{"id":"s9-621","number":621,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"ما سرّ التعبير في قوله تعالى في النهاية: ﴿وبشر المؤمنين﴾ بدل إعادة الصفات؟","answer":"ردهم إلى الاسم الجامع ﴿المؤمنين﴾ لأن تلك الصفات شواهد الإيمان، ولتعم البشارة كل من تحقق بها دون إعادة طويلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص387، تحت «سر ختام الآية بالبشارة وبشر المؤمنين مع سبق ذكرها»","url":""}]},{"id":"s9-622","number":622,"surah":9,"verses":[113],"references":[{"surah":9,"verses":[113]}],"verseLabel":"التوبة: 113","question":"لماذا نُهي النبي والمؤمنون عن الاستغفار للمشركين ولو كانوا أولي قربى؟","answer":"إذا تبين موت المشرك على الشرك انقطع محل المغفرة، وقرابة النسب لا تقدم على حق الله ولا تغير حكم الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص397، تحت «سر التعبير ولو كانوا أولي قربى»","url":""}]},{"id":"s9-623","number":623,"surah":9,"verses":[113],"references":[{"surah":9,"verses":[113]}],"verseLabel":"التوبة: 113","question":"لماذا جاء القيد: ﴿من بعد ما تبين لهم أنهم أصحاب الجحيم﴾؟","answer":"يقيد النهي بحصول التبين، ومن صوره في المصدر موت المشرك على شركه أو ورود الوحي ببيان مآله. أما قبل ذلك فلا يلزم انقطاع الرجاء في إيمانه؛ ويذكر المصدر الدعاء للأحياء بطلب توفيقهم إلى الهدى. فلا يخلط الدعاء بالهداية بالاستغفار لمن ثبت موته على الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص399، تحت «دلالة تقييد النهي بالتبيين من بعد ما تبين لهم»","url":""}]},{"id":"s9-624","number":624,"surah":9,"verses":[113],"references":[{"surah":9,"verses":[113]}],"verseLabel":"التوبة: 113","question":"لماذا وصفوا بـ﴿أصحاب الجحيم﴾؟","answer":"الصحبة تفيد الملازمة؛ أي هم أهل الجحيم الملازمون لها، لا عذابًا عابرًا ينتهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص401، تحت «سر اختيار الجحيم دون غيرها من أوصاف النار»","url":""}]},{"id":"s9-625","number":625,"surah":9,"verses":[114],"references":[{"surah":9,"verses":[114]}],"verseLabel":"التوبة: 114","question":"لماذا استغفر إبراهيم لأبيه مع النهي الوارد في الآية السابقة؟","answer":"كان استغفاره متعلقًا بموعدة ورجاء إيمان أبيه، لا استغفارًا بعد ثبوت مآله على الشرك. ومن أوجه الضمير أن إبراهيم وعد أباه بالاستغفار، ويذكر المصدر أيضًا أن أباه وعده بالإيمان؛ فلما تبينت عداوته لله تبرأ منه، فلا تعارض مع النهي بعد التبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص403، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-626","number":626,"surah":9,"verses":[114],"references":[{"surah":9,"verses":[114]}],"verseLabel":"التوبة: 114","question":"ما سرّ التعبير بقوله تبرأ منه؟","answer":"الفاء تفيد أن البراءة أعقبت التبين بلا إبطاء، فقدم حق الله على عاطفة الأبوة حين انكشف المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص409، تحت «سر التعبير بقوله تبرأ منه»","url":""}]},{"id":"s9-627","number":627,"surah":9,"verses":[114],"references":[{"surah":9,"verses":[114]}],"verseLabel":"التوبة: 114","question":"لماذا ختم بوصف إبراهيم: ﴿لأواه حليم﴾؟","answer":"﴿أواه﴾ كثير التضرع والتأوه رحمة، و﴿حليم﴾ لا يعجل بالعقوبة؛ فالوصفان يفسران رفقه واستغفاره قبل التبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص411، تحت «سر ختم الآية بهذين الوصفين»","url":""}]},{"id":"s9-628","number":628,"surah":9,"verses":[115],"references":[{"surah":9,"verses":[115]}],"verseLabel":"التوبة: 115","question":"ما دلالة النفي في وما كان في قوله تعالى: ﴿وما كان الله ليضل قومًا بعد إذ هداهم حتى يبين لهم ما يتقون﴾؟","answer":"نفت الآية أن يؤاخذ الله المهتدين على أمر لم يبين لهم وجوب اتقائه؛ فالحجة والبيان يسبقان المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص416، تحت «دلالة النفي في وما كان»","url":""}]},{"id":"s9-629","number":629,"surah":9,"verses":[115],"references":[{"surah":9,"verses":[115]}],"verseLabel":"التوبة: 115","question":"ما دلالة صيغة النفي في قوله: ﴿وما كان الله ليضل قومًا﴾؟","answer":"تؤكد الصيغة نفي الحكم بالضلال والمؤاخذة قبل البيان؛ فإقامة الحجة سابقة للمؤاخذة، وهذه سنة ثابتة في معاملة العباد. وفي ذلك طمأنة لمن خاف المؤاخذة بفعل سبق ورود النهي عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص416، تحت «دلالة النفي في وما كان»","url":""}]},{"id":"s9-630","number":630,"surah":9,"verses":[115],"references":[{"surah":9,"verses":[115]}],"verseLabel":"التوبة: 115","question":"ما فائدة التعبير بالظرفية في بعد إذ هداهم في قوله تعالى: ﴿بعد إذ هداهم﴾؟","answer":"تذكرهم بنعمة الهداية السابقة وتطمئنهم أنها لا تسلب لمجرد فعل وقع قبل بيان حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص419، تحت «فائدة التعبير بالظرفية في بعد إذ هداهم»","url":""}]},{"id":"s9-631","number":631,"surah":9,"verses":[115],"references":[{"surah":9,"verses":[115]}],"verseLabel":"التوبة: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى يبين لهم ما يتقون﴾ لا «ما يفعلون»؟","answer":"التقوى لفظ جامع لما يتقى به سخط الله؛ فيشمل امتثال الأوامر واجتناب النواهي، ومن ذلك النهي عن الاستغفار للمشركين في السياق. فالتعبير يربط البيان بما يحقق الوقاية، ولا يقتصر على مجرد معرفة ما يفعلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص422، تحت «دلالة التعبير بما»","url":""}]},{"id":"s9-632","number":632,"surah":9,"verses":[115],"references":[{"surah":9,"verses":[115]}],"verseLabel":"التوبة: 115","question":"لماذا ختم بـ﴿إن الله بكل شيء عليم﴾؟","answer":"علمه بكل شيء يقتضي علمه بأحوال العباد وما بلّغوا وما خفي عنهم، فيجري البيان والمؤاخذة على عدل تام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص422، تحت «بلاغة الفصل في إن الله بكل شيء عليم»","url":""}]},{"id":"s9-633","number":633,"surah":9,"verses":[116],"references":[{"surah":9,"verses":[116]}],"verseLabel":"التوبة: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الله له ملك السماوات والأرض﴾ بعد الحديث عن الهداية والبيان؟","answer":"الملك المطلق دليل قدرته على الهداية والتشريع والجزاء؛ فمن له السماوات والأرض وحده له الحكم والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص430، تحت «سر التعبير بقوله له ملك»","url":""}]},{"id":"s9-634","number":634,"surah":9,"verses":[116],"references":[{"surah":9,"verses":[116]}],"verseLabel":"التوبة: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿يحيي ويميت﴾ بالمضارع؟","answer":"المضارعان يدلان على تجدد آثار قدرته واستمرارها في إحياء الخلق وإماتتهم، وأن الأمر كله بيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص433، تحت «سر التعبير بالفعل المضارع يحيي ويميت»","url":""}]},{"id":"s9-635","number":635,"surah":9,"verses":[116],"references":[{"surah":9,"verses":[116]}],"verseLabel":"التوبة: 116","question":"لماذا نُفي الولي والنصير معًا؟","answer":"الولي يتولى شؤونهم ويجلب النفع، والنصير يدفع الضر؛ فنفيهما يستوعب وجهي الحماية من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص436، تحت «دلالة الجمع بين الولي والنصير في النفي»","url":""}]},{"id":"s9-636","number":636,"surah":9,"verses":[116],"references":[{"surah":9,"verses":[116]}],"verseLabel":"التوبة: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿من دون الله من ولي ولا نصير﴾ بتكرار ﴿من﴾؟","answer":"ليست من في الموضعين لوظيفة واحدة: فالأولى في ﴿من دون الله﴾ تبين أن الولاية والنصرة المقصودتين لا تكونان استقلالًا من غيره. وأما ﴿من ولي﴾ مع النفي فتفيد استغراق جنس الولي، ويؤكد تكرار لا شمول النفي للنصير أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص434، تحت «دلالة من في من دون الله»","url":""}]},{"id":"s9-637","number":637,"surah":9,"verses":[117],"references":[{"surah":9,"verses":[117]}],"verseLabel":"التوبة: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد تاب الله على النبي والمهاجرين والأنصار﴾ مع عصمة النبي ﷺ؟","answer":"يعرض المصدر للتوبة درجات بحسب من أسندت إليه؛ فتكون في حق النبي ﷺ ارتقاءً في مراتب الكمال، أو رجوعًا إلى الأولى والأفضل في شأن الإذن للمتخلفين. وفي تقديم ذكره تشريف للمهاجرين والأنصار وترغيب للجميع في التوبة، دون تسوية أحوالهم جميعًا في الذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص441، تحت «سر التعبير بالتوبة لقد تاب»","url":""}]},{"id":"s9-638","number":638,"surah":9,"verses":[117],"references":[{"surah":9,"verses":[117]}],"verseLabel":"التوبة: 117","question":"ما سرّ تقديم النبي ثم المهاجرين ثم الأنصار؟","answer":"قُدم النبي ﷺ لشرفه وقيادته، ثم المهاجرون لسبقهم، ثم الأنصار لنصرتهم؛ ترتيبًا للرتب مع شمول الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص444، تحت «سر تقديم المهاجرين على الأنصار في الذكر»","url":""}]},{"id":"s9-639","number":639,"surah":9,"verses":[117],"references":[{"surah":9,"verses":[117]}],"verseLabel":"التوبة: 117","question":"لماذا سميت الغزوة ﴿ساعة العسرة﴾ مع امتداد زمنها؟","answer":"الساعة هنا وقت العسرة، لا مقدار الساعة الاصطلاحي. ويذكر المصدر أنها تهوين لمدة الكرب وحث على الصبر؛ فزمن الشدة يسير إلى جانب ما يعقبه من الأجر. وإضافتها إلى العسرة تجمع ما وقع من شدة الحر وقلة الزاد والماء والظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص447، تحت «نكتة إضافة الساعة إلى العسرة»","url":""}]},{"id":"s9-640","number":640,"surah":9,"verses":[117],"references":[{"surah":9,"verses":[117]}],"verseLabel":"التوبة: 117","question":"ما دلالة إسناد الزيغ إلى القلوب في قوله تعالى: ﴿من بعد ما كاد يزيغ قلوب فريق منهم﴾؟","answer":"﴿كاد﴾ تصور قرب بعضهم من الميل بسبب شدة العسرة، ثم أدركتهم التوبة والعناية قبل وقوع الزيغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص449، تحت «دلالة إسناد الزيغ إلى القلوب»","url":""}]},{"id":"s9-641","number":641,"surah":9,"verses":[117],"references":[{"surah":9,"verses":[117]}],"verseLabel":"التوبة: 117","question":"لماذا قيد مقاربة الزيغ بقوله: ﴿قلوب فريق منهم﴾؟","answer":"حتى لا يعمم هذا الوصف على المهاجرين والأنصار؛ فقد ثبت معظمهم مع شدة العسرة، وقاربت قلوب فريق منهم الميل بسببها. ففي القيد إنصاف لهم وإبراز لقوة إيمان من لم تؤثر الشدة في عزيمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص450، تحت «سر التعبير بالفريق قلوب فريق منهم»","url":""}]},{"id":"s9-642","number":642,"surah":9,"verses":[117],"references":[{"surah":9,"verses":[117]}],"verseLabel":"التوبة: 117","question":"لماذا كرر: ﴿ثم تاب عليهم﴾ بعد قوله: ﴿لقد تاب الله﴾؟","answer":"من توجيهات التكرار أن التوبة الأولى توفيق لهم إلى الرجوع، والثانية قبول وإثابة، وفيه تأكيد للعناية بهم. ومن أوجه ضمير عليهم أن يعود إلى الفريق الذي قاربت قلوبه الزيغ، كما يجوز عوده إلى المهاجرين والأنصار جميعًا؛ فلا يحصر التكرار في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص450، تحت «دلالة تكرار فعل التوبة»","url":""}]},{"id":"s9-643","number":643,"surah":9,"verses":[117],"references":[{"surah":9,"verses":[117]}],"verseLabel":"التوبة: 117","question":"لماذا ختم بـ﴿إنه بهم رؤوف رحيم﴾؟","answer":"الرأفة أبلغ الرحمة وألطفها، والرحمة أعم؛ فهما تفسران إنقاذهم من الزيغ وقبولهم بعد العسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص451، تحت «بلاغة الفصل إنه بهم رؤوف رحيم»","url":""}]},{"id":"s9-644","number":644,"surah":9,"verses":[118],"references":[{"surah":9,"verses":[118]}],"verseLabel":"التوبة: 118","question":"لماذا عطف ﴿وعلى الثلاثة الذين خلفوا﴾ دون ذكر أسمائهم؟","answer":"عطفوا على من تاب الله عليهم لتشريفهم بإدخالهم في حكم التوبة، وأعيد حرف الجر لتأكيد شمولها لهم بعد طول الفصل. أما ترك التصريح بأسمائهم فذكر المصدر أنهم كانوا معروفين، وفيه لطف بهم وستر لما ارتبط بقصتهم من تقصير وحزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص457، تحت «سر إعادة حرف الجر وعلى الثلاثة»","url":""}]},{"id":"s9-645","number":645,"surah":9,"verses":[118],"references":[{"surah":9,"verses":[118]}],"verseLabel":"التوبة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿خُلّفوا﴾ بالبناء للمجهول، لا «تخلفوا»؟","answer":"﴿خُلّفوا﴾ يدل على أن أمرهم أُخّر عن قبول الآخرين، أو خلّفهم الحكم الإلهي، لا مجرد أنهم اختاروا التخلف عن الغزو.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص458، تحت «علة التعبير بالفعل الماضي المبني للمفعول»","url":""}]},{"id":"s9-646","number":646,"surah":9,"verses":[118],"references":[{"surah":9,"verses":[118]}],"verseLabel":"التوبة: 118","question":"ما الصورة في قوله: ﴿ضاقت عليهم الأرض بما رحبت﴾؟","answer":"تمثيل لشدة الكرب والوحشة: مع سعة الأرض لم يجدوا مكانًا يطمئنون إليه، فكأنها ضاقت حقيقة حولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص460، تحت «سر التعبير بالمجاز في ضاقت عليهم الأرض»","url":""}]},{"id":"s9-647","number":647,"surah":9,"verses":[118],"references":[{"surah":9,"verses":[118]}],"verseLabel":"التوبة: 118","question":"لماذا انتقل من ضيق الأرض إلى ﴿وضاقت عليهم أنفسهم﴾؟","answer":"ضيق الأرض خارجي، ثم بلغ الكرب باطنهم فلم تسعهم نفوسهم؛ فانتقل من إحاطة المكان إلى أشد ضيق نفسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص462، تحت «دلالة العطف في وضاقت عليهم أنفسهم»","url":""}]},{"id":"s9-648","number":648,"surah":9,"verses":[118],"references":[{"surah":9,"verses":[118]}],"verseLabel":"التوبة: 118","question":"ما دلالة إلا إليه في قوله تعالى: ﴿وظنوا أن لا ملجأ من الله إلا إليه﴾؟","answer":"علموا أنه لا مهرب من عقاب الله إلا بالرجوع إليه؛ فجمع التركيب الخوف منه واللجوء إليه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص466، تحت «دلالة إلا إليه»","url":""}]},{"id":"s9-649","number":649,"surah":9,"verses":[118],"references":[{"surah":9,"verses":[118]}],"verseLabel":"التوبة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم تاب عليهم ليتوبوا﴾، وما وجه تقدم توبة الله عليهم على توبتهم؟","answer":"يبرز تقديم توبته عليهم فضل الله وامتنانه. ويذكر المصدر أن قبوله لهم يدعوهم إلى الثبات على التوبة والاستمرار فيها، وأنه لطف وهداية للرجوع إليه؛ فلا يلزم حصر ترتيب الجملة في توبة واحدة للعبد تسبقها توبة واحدة من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص470، تحت «سر تقديم توبة الله تعالى على توبة العباد»","url":""}]},{"id":"s9-650","number":650,"surah":9,"verses":[118],"references":[{"surah":9,"verses":[118]}],"verseLabel":"التوبة: 118","question":"لماذا ختم بـ﴿إن الله هو التواب الرحيم﴾ بضمير الفصل؟","answer":"ضمير الفصل يقصر كمال قبول التوبة والرحمة على الله، ويؤكد أنه كثير القبول لمن صدق مهما اشتد كربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص470، تحت «دلالة التذييل إن الله هو التواب الرحيم»","url":""}]},{"id":"s9-651","number":651,"surah":9,"verses":[119],"references":[{"surah":9,"verses":[119]}],"verseLabel":"التوبة: 119","question":"لماذا جاء بعد قصة الثلاثة الأمر: ﴿اتقوا الله وكونوا مع الصادقين﴾؟","answer":"قصة الثلاثة برهان على نجاة الصدق وهلاك الكذب؛ فجاء الأمر بالتقوى وملازمة الصادقين تعميمًا لعبرتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص476، تحت «سر العدول عن خطاب الثلاثة إلى خطاب المؤمنين جميعًا»","url":""}]},{"id":"s9-652","number":652,"surah":9,"verses":[119],"references":[{"surah":9,"verses":[119]}],"verseLabel":"التوبة: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿مع الصادقين﴾ لا «من الصادقين»؟","answer":"﴿مع﴾ تأمر بملازمة جماعتهم ونصرتهم والسير في طريقهم، وفي ذلك معنى الصحبة العملية المستمرة، لا مجرد الانتساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص478، تحت «سر إيثار التعبير وكونوا مع الصادقين»","url":""}]},{"id":"s9-653","number":653,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"ما دلالة التعبير ومن حولهم من الأعراب في قوله تعالى: ﴿ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله﴾؟","answer":"﴿ما كان﴾ تنفي استحقاق التخلف وتقرر أنه لا يليق بأهل المدينة ومن حولها مع قربهم وقدرة الرسول ﷺ بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص485، تحت «دلالة التعبير ومن حولهم من الأعراب»","url":""}]},{"id":"s9-654","number":654,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"ما دلالة التعبير بقوله ولا يرغبوا بأنفسهم عن نفسه؟","answer":"لا ينبغي أن يطلبوا لأنفسهم الراحة معرضين عن نفس الرسول ﷺ؛ فحياته ونفسه أولى بالحفظ والبذل من أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص486، تحت «دلالة التعبير بقوله ولا يرغبوا بأنفسهم عن نفسه»","url":""}]},{"id":"s9-655","number":655,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"ما سرّ ترتيب الظمأ والنصب والمخمصة والموطئ والنيل من العدو؟","answer":"رتبت الآية مشاق الغزو وآثاره على نسق وقوعها: تعب الطريق وحاجاته، ثم دخول أرض العدو، ثم ما يناله المسلمون منه؛ فاستوعبت مراحل السعي التي يكتب الله بها العمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص500، تحت «براعة ترتيب الأحداث في الآية»","url":""}]},{"id":"s9-770","number":770,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"ما دلالة التعبير بقوله تعالى: ﴿ولا يطؤون موطئًا يغيظ الكفار﴾؟","answer":"يجمع اللفظ وطء المكان حقيقة وما يترتب عليه من إذلال العدو وقهره؛ فكل تقدم في أرضه يغيظه ويكتب للمؤمنين به عمل صالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص492، تحت «دلالة التعبير بيطؤون بين الحقيقة والاستعارة»","url":""}]},{"id":"s9-771","number":771,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"ما سرّ التعبير بالمصدر في قوله تعالى: ﴿ولا ينالون من عدو نيلًا﴾؟","answer":"جاء المصدر نكرة ليعم كل ما يصيبونه من العدو قليلًا أو كثيرًا، ماديًا أو معنويًا؛ فلا يضيع من أثر جهادهم شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص494، تحت «دلالة التعبير بالمصدر في نيلا»","url":""}]},{"id":"s9-656","number":656,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"لماذا تكرر ﴿ولا﴾ في تعداد المشاق؟","answer":"التكرار يجعل كل مشقة وعمل مستقلًا في إثبات الأجر، فلا يضيع واحد منها تابعًا لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص493، تحت «دلالة تتابع الجمل المنفية»","url":""}]},{"id":"s9-657","number":657,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿إلا كتب لهم به عمل صالح﴾، فجعل المشقة نفسها عملًا؟","answer":"تفضل الله فأجرى ما ليس فعلًا اختياريًا كالظمأ والتعب مجرى العمل الصالح، لأنه نشأ عن مسيرهم في الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص496، تحت «دلالة التعبير بكتابة العمل الصالح دون قوله في كتب لهم»","url":""}]},{"id":"s9-658","number":658,"surah":9,"verses":[120],"references":[{"surah":9,"verses":[120]}],"verseLabel":"التوبة: 120","question":"لماذا ختم بـ﴿إن الله لا يضيع أجر المحسنين﴾؟","answer":"الخاتمة تضمن حفظ كل مشقة وعمل، وتسميهم محسنين لأنهم بذلوا طاقتهم في نصرة الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص498، تحت «سر الختم بقوله إن الله لا يضيع أجر المحسنين»","url":""}]},{"id":"s9-659","number":659,"surah":9,"verses":[120,121],"references":[{"surah":9,"verses":[120,121]}],"verseLabel":"التوبة: 120؛ التوبة: 121","question":"ما سرّ التعبير في قوله تعالى في الآية 120: ﴿إلا كتب لهم به عمل صالح﴾، ثم قال في الآية 121: ﴿إلا كتب لهم﴾ وحذف ﴿به عمل صالح﴾؟","answer":"الآية 120 جمعت مشاقًا ليست أفعالًا لهم مع أعمالهم، فأجراها الله مجرى العمل فقال ﴿به عمل صالح﴾؛ أما 121 فذكرت الإنفاق وقطع الوادي وهما من فعلهم، فاكتفى بـ﴿كتب لهم﴾ أي كتب نفس العمل وثوابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص508، تحت «بلاغة الحذف في إلا كتب لهم»","url":""}]},{"id":"s9-660","number":660,"surah":9,"verses":[121],"references":[{"surah":9,"verses":[121]}],"verseLabel":"التوبة: 121","question":"ما سرّ التنكير في المفعول به نفقة في قوله تعالى: ﴿ولا ينفقون نفقة صغيرة ولا كبيرة﴾؟","answer":"قوبلت الصغيرة بالكبيرة لاستغراق كل نفقة مهما قل قدرها أو كثر، فلا يضيع منها شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص504، تحت «سر التنكير في المفعول به نفقة»","url":""}]},{"id":"s9-661","number":661,"surah":9,"verses":[121],"references":[{"surah":9,"verses":[121]}],"verseLabel":"التوبة: 121","question":"ما سرّ العطف في ولا يقطعون واديًا إلا كتب لهم في قوله تعالى: ﴿ولا يقطعون واديًا إلا كتب لهم﴾؟","answer":"القطع في أصله فصل الشيء، واستعمل هنا في اجتياز الطريق والسير في الجهاد؛ فكأن السائر يفصل بمسيره قطعة من الأرض عن أخرى. وذكر الوادي يصور مراحل هذا السير، وكل ذلك محفوظ لهم بأجره.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص506، تحت «سر العطف في ولا يقطعون واديًا إلا كتب لهم»","url":""}]},{"id":"s9-662","number":662,"surah":9,"verses":[121],"references":[{"surah":9,"verses":[121]}],"verseLabel":"التوبة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿ليجزيهم الله أحسن ما كانوا يعملون﴾، لا «بما كانوا يعملون»؟","answer":"يذكر المصدر وجهين: أن يجزيهم بأحسن أعمالهم، أو أن يجزيهم جزاءً هو أحسن من أعمالهم تفضلًا منه. فصيغة أحسن تبين كرم الجزاء، ولا تحصره في مقابلة حسابية مساوية للعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص508، تحت «دلالة اللام في ليجزيهم الله»","url":""}]},{"id":"s9-663","number":663,"surah":9,"verses":[122],"references":[{"surah":9,"verses":[122]}],"verseLabel":"التوبة: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان المؤمنون لينفروا كافة﴾ بعد الأمر السابق بالنفير؟","answer":"النفير العام لا يجب في كل حال؛ بل تتوزع وظائف الأمة بين الجهاد والتفقه، فلا يخلو الثغر ولا يخلو الناس من العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص514، تحت «سر المقابلة بين التحريضين على الغزو والعلم»","url":""}]},{"id":"s9-664","number":664,"surah":9,"verses":[122],"references":[{"surah":9,"verses":[122]}],"verseLabel":"التوبة: 122","question":"ما دلالة الفاء في فلولا نفر في قوله تعالى: ﴿فلولا نفر من كل فرقة منهم طائفة﴾؟","answer":"لولا للتحضيض على النفير، وذكر طائفة من كل فرقة يبين حصول الكفاية بجماعة تتفقه وتنذر قومها. وفي توزيع النافرين على الفرق تعميم لنفع العلم، وقرب من قبول كل قوم لمن يعلمهم من بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص516، تحت «دلالة الفاء في فلولا نفر»","url":""}]},{"id":"s9-665","number":665,"surah":9,"verses":[122],"references":[{"surah":9,"verses":[122]}],"verseLabel":"التوبة: 122","question":"لماذا استعمل ﴿نفر﴾ لطالب العلم كما استعمله للجهاد؟","answer":"النفر يدل على الخروج بجد ونشاط لمهمة عظيمة؛ فطلب العلم جهاد يحتاج حركة وبذلًا كما يحتاجه القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص515، تحت «نكتة التعبير لينفروا في سياق طلب العلم بالفقه»","url":""}]},{"id":"s9-666","number":666,"surah":9,"verses":[122],"references":[{"surah":9,"verses":[122]}],"verseLabel":"التوبة: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿ليتفقهوا في الدين﴾ لا «ليتعلموا»؟","answer":"التفقه فهم عميق لأحكام الدين ومقاصده يجاوز جمع المعلومات، وهو الذي يؤهل صاحبه للإنذار والتعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص518، تحت «سر التعبير بصيغة التفعل»","url":""}]},{"id":"s9-667","number":667,"surah":9,"verses":[122],"references":[{"surah":9,"verses":[122]}],"verseLabel":"التوبة: 122","question":"ما سرّ تقديم التفقه على إنذار القوم؟","answer":"لا يصح الإنذار إلا بعد علم راسخ؛ فقدم إعداد المبلّغ بالتفقه على أثره في قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص519، تحت «دلالة الاقتصار على الإنذار وترك البشارة»","url":""}]},{"id":"s9-668","number":668,"surah":9,"verses":[122],"references":[{"surah":9,"verses":[122]}],"verseLabel":"التوبة: 122","question":"لماذا ختم بـ﴿لعلهم يحذرون﴾ لا «يعلمون»؟","answer":"غاية العلم أن يثمر حذرًا وامتثالًا، لا أن يبقى معرفة ذهنية؛ لذلك ختم بالأثر العملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص520، تحت «دلالة الختم بأسلوب الإنشاء غير الطلبي»","url":""}]},{"id":"s9-669","number":669,"surah":9,"verses":[123],"references":[{"surah":9,"verses":[123]}],"verseLabel":"التوبة: 123","question":"لماذا أمر بقتال ﴿الذين يلونكم من الكفار﴾؟","answer":"البدء بالأقرب تنظيم للقتال ودفع للخطر المباشر، ثم ينتقل إلى من وراءه، وفيه حماية للحدود واستكمال للقوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص530، تحت «دلالة استعمال يلونكم دون مرادفاتها»","url":""}]},{"id":"s9-670","number":670,"surah":9,"verses":[123],"references":[{"surah":9,"verses":[123]}],"verseLabel":"التوبة: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿وليجدوا فيكم غلظة﴾، فجعل الغلظة شيئًا يوجد؟","answer":"جعل الغلظة شيئًا يلقونه في المؤمنين لتظهر في الموقف والثبات بحيث يحسها العدو أثرًا واقعيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص533، تحت «سر إيثار صيغة الأمر باللام والفعل المضارع وليجدوا»","url":""}]},{"id":"s9-671","number":671,"surah":9,"verses":[123],"references":[{"surah":9,"verses":[123]}],"verseLabel":"التوبة: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿غلظة﴾ لا «قسوة»؟","answer":"الغلظة شدة وحزم في موضع القتال مع بقاء العدل، أما القسوة فغلظ القلب المذموم؛ فاختير اللفظ المنضبط بالمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص535، تحت «نكتة التعبير بلفظ غلظة»","url":""}]},{"id":"s9-673","number":673,"surah":9,"verses":[124],"references":[{"surah":9,"verses":[124]}],"verseLabel":"التوبة: 124","question":"ما دلالة قول المنافقين عند نزول السورة: ﴿أيكم زادته هذه إيمانًا﴾؟","answer":"قالوها استهزاءً وتشكيكًا في أثر الوحي، يسأل بعضهم بعضًا سؤال إنكار لا طلب هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص549، تحت «دلالة أي في سياق السؤال»","url":""}]},{"id":"s9-674","number":674,"surah":9,"verses":[124],"references":[{"surah":9,"verses":[124]}],"verseLabel":"التوبة: 124","question":"لماذا نُسبت زيادة الإيمان إلى السورة؟","answer":"لأن نزول السورة يمد المؤمن بعلم جديد من قصص وأحكام، ويقيم له دليلًا على توحيد الله ومعرفته، ويزيل شكًا أو شبهة؛ فهي سبب زيادة تصديقه ويقينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص549، تحت «نكتة استعمال مفردة الزيادة في الفعل زادته»","url":""}]},{"id":"s9-675","number":675,"surah":9,"verses":[124],"references":[{"surah":9,"verses":[124]}],"verseLabel":"التوبة: 124","question":"ما معنى الفاء في لفظ فأما في قوله تعالى: ﴿فأما الذين آمنوا فزادتهم إيمانًا وهم يستبشرون﴾؟","answer":"جاء التفصيل ردًا على تشكيك المنافقين، فبين أثر السورة في المؤمنين. والفاء في ﴿فزادتهم﴾ تربط جواب أما وتبين تسبب تلقي القرآن في زيادة الإيمان، والجملة الحالية ﴿وهم يستبشرون﴾ تصور فرحهم المتجدد بنزول الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص552، تحت «معنى الفاء في لفظ فأما»","url":""}]},{"id":"s9-676","number":676,"surah":9,"verses":[125],"references":[{"surah":9,"verses":[125]}],"verseLabel":"التوبة: 125","question":"ما وجه اختلاف أثر السورة؛ فتزيد المؤمن إيمانًا وتزيد مريض القلب رجسًا؟","answer":"السورة سبب واحد، لكن المحل مختلف: المؤمن يقبلها فتزيد يقينه، والمريض يردها فتضيف كفرًا ونفاقًا إلى ما فيه؛ فالاختلاف في القلوب لا في الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص558، تحت «نكتة تعدية الزيادة إليهم لا إلى القلوب في سياق الآية الكريمة»","url":""}]},{"id":"s9-677","number":677,"surah":9,"verses":[125],"references":[{"surah":9,"verses":[125]}],"verseLabel":"التوبة: 125","question":"ما وجه البلاغة في ذكر قيد إلى رجسهم في قوله تعالى: ﴿فزادتهم رجسًا إلى رجسهم﴾؟","answer":"﴿إلى﴾ تصور انضمام رجس جديد إلى رجس سابق وتراكمه، فكل رد لآية يزيد مرض القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص559، تحت «بلاغة ذكر قيد إلى رجسهم»","url":""}]},{"id":"s9-678","number":678,"surah":9,"verses":[125],"references":[{"surah":9,"verses":[125]}],"verseLabel":"التوبة: 125","question":"لماذا ختم بـ﴿وماتوا وهم كافرون﴾؟","answer":"الخاتمة تبين نهاية التراكم: استمر رجسهم حتى خرجوا من الدنيا على الكفر من غير توبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص560، تحت «فن الازدواج بين وهم يستبشرون وماتوا وهم كافرون»","url":""}]},{"id":"s9-679","number":679,"surah":9,"verses":[126],"references":[{"surah":9,"verses":[126]}],"verseLabel":"التوبة: 126","question":"ما فائدة استعمال لفظ مرة أو مرتين في قوله تعالى: ﴿أولا يرون أنهم يفتنون في كل عام مرة أو مرتين﴾؟","answer":"الاستفهام للتوبيخ على ترك الاعتبار بالابتلاء المتكرر، و﴿مرة أو مرتين﴾ يدل على أن الفرص تتجدد كل عام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص569، تحت «فائدة استعمال لفظ مرة أو مرتين»","url":""}]},{"id":"s9-680","number":680,"surah":9,"verses":[126],"references":[{"surah":9,"verses":[126]}],"verseLabel":"التوبة: 126","question":"ما دلالة بناء الفعل ﴿يفتنون﴾ للمفعول؟","answer":"يوجه البناء للمفعول الاهتمام إلى الفتنة ومقاصدها؛ أي ما يصيبهم من ابتلاء ينبههم إلى التوبة والاعتبار، دون الانشغال بذكر فاعل الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص566–567، تحت «فائدة بناء الفعل يفتنون للمفعول»","url":""}]},{"id":"s9-681","number":681,"surah":9,"verses":[126],"references":[{"surah":9,"verses":[126]}],"verseLabel":"التوبة: 126","question":"لماذا جمع بين ﴿لا يتوبون﴾ و﴿لا هم يذكرون﴾؟","answer":"نفت التوبة التي تصلح العمل، ونفت التذكر الذي يوقظ القلب ويفضي إليها؛ فجمع غياب الثمرة وسببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص570، تحت «دلالة النفي بلا في دخوله على الفعل يتوبون»","url":""}]},{"id":"s9-682","number":682,"surah":9,"verses":[127],"references":[{"surah":9,"verses":[127]}],"verseLabel":"التوبة: 127","question":"لماذا نظر المنافقون بعضهم إلى بعض عند نزول السورة؟","answer":"تبادلوا النظر خفية يستأذنون بعضهم بعضًا في الانصراف ويتفقدون هل يراهم أحد، فكشفت النظرات تواطؤهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص576، تحت «سر التعبير بالفعل نظر»","url":""}]},{"id":"s9-683","number":683,"surah":9,"verses":[127],"references":[{"surah":9,"verses":[127]}],"verseLabel":"التوبة: 127","question":"ما دلالة استفهام المنافقين: ﴿هل يراكم من أحد﴾؟","answer":"استفهموا بالإشارة خوف افتضاح خروجهم؛ أي هل يراقبنا أحد من المؤمنين قبل أن ننصرف؟","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص578، تحت «علة فصل جملة هل يراكم من أحد»","url":""}]},{"id":"s9-684","number":684,"surah":9,"verses":[127],"references":[{"surah":9,"verses":[127]}],"verseLabel":"التوبة: 127","question":"ما وجه البلاغة في الاستئناف البياني في ذكر صرف القلوب في قوله تعالى: ﴿ثم انصرفوا صرف الله قلوبهم﴾؟","answer":"انصرفوا بأبدانهم عن مجلس الوحي، فجازاهم الله بصرف قلوبهم عن الهدى؛ جزاء من جنس فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص580، تحت «بلاغة الاستئناف البياني في ذكر صرف القلوب»","url":""}]},{"id":"s9-685","number":685,"surah":9,"verses":[127],"references":[{"surah":9,"verses":[127]}],"verseLabel":"التوبة: 127","question":"لماذا علل صرف القلوب بأنهم ﴿قوم لا يفقهون﴾؟","answer":"لأنهم لا يتدبرون الوحي ولا يتأملون مقاصده وما يؤول إليه إعراضهم، فعدم الفقه سبب لصرف قلوبهم. ونفي الفقه أبلغ هنا من نفي مجرد العلم؛ إذ المطلوب فهم يتبعه انتفاع وعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص584، تحت «نكتة إيثار نفي الفقه دون العلم أو العقل»","url":""}]},{"id":"s9-686","number":686,"surah":9,"verses":[128],"references":[{"surah":9,"verses":[128]}],"verseLabel":"التوبة: 128","question":"ما فائدة التوكيد والتحقيق بلفظ لقد في قوله تعالى: ﴿لقد جاءكم رسول من أنفسكم﴾؟","answer":"اللام و﴿قد﴾ تؤكدان عظم المنة ووقوعها: جاءهم رسول قريب منهم، يعرفون نسبه وصدقه ولسانه وأحواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص589، تحت «فائدة التوكيد والتحقيق بلفظ لقد»","url":""}]},{"id":"s9-687","number":687,"surah":9,"verses":[128],"references":[{"surah":9,"verses":[128]}],"verseLabel":"التوبة: 128","question":"لماذا اختير ﴿من أنفسكم﴾ لا «منكم» فقط؟","answer":"﴿من أنفسكم﴾ أبلغ في شدة الاتصال، أي من جنسكم وخالص جماعتكم، فكأنه من نفسكم لا غريبًا عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص592، تحت «بلاغة استعمال قيد من أنفسكم»","url":""}]},{"id":"s9-688","number":688,"surah":9,"verses":[128],"references":[{"surah":9,"verses":[128]}],"verseLabel":"التوبة: 128","question":"ما وجه البلاغة في تعدية عزيز بحرف الاستعلاء على في قوله تعالى: ﴿عزيز عليه ما عنتم﴾؟","answer":"﴿عزيز عليه﴾ أي شديد شاق عليه ما يصيبهم من عنت ومشقة. والتعدية بـ﴿على﴾ تصور شدة ثقل معاناتهم عليه، فيظهر كمال شفقته بهم ورحمته لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص594، تحت «بلاغة تعدية عزيز بحرف الاستعلاء على»","url":""}]},{"id":"s9-689","number":689,"surah":9,"verses":[128],"references":[{"surah":9,"verses":[128]}],"verseLabel":"التوبة: 128","question":"ما بلاغة التعبير بقوله تعالى: ﴿حريص عليكم﴾؟","answer":"يصوّر شدة عنايته بهم ورعايته لأحوالهم وحرصه على إيمانهم ونجاتهم؛ حتى شُبّه حرصه عليهم بحرْص الشفيق على ما يخاف ضياعه، مبالغة في تعلقه بخيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص595–596، تحت «براعة استعمال مفردة حريص مع حرف الاستعلاء في السياق»","url":""}]},{"id":"s9-690","number":690,"surah":9,"verses":[128],"references":[{"surah":9,"verses":[128]}],"verseLabel":"التوبة: 128","question":"لماذا خص المؤمنين بقوله: ﴿بالمؤمنين رؤوف رحيم﴾ بعد عموم حرصه على الناس؟","answer":"حرصه عام في دعوة الناس، أما الرأفة والرحمة الخاصة النافعة فبالمؤمنين الذين قبلوا هديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص597، تحت «نكتة تقديم المتعلق على عامله»","url":""}]},{"id":"s9-691","number":691,"surah":9,"verses":[128],"references":[{"surah":9,"verses":[128]}],"verseLabel":"التوبة: 128","question":"ما سرّ تقديم ﴿رؤوف﴾ على ﴿رحيم﴾؟","answer":"الرأفة أشد الرحمة، فقدم الوصف الأقوى المناسب لحرصه على المؤمنين، ثم أتبعه بالرحمة الأعم؛ وفي ترتيب الوصفين تأكيد للشفقة وجمع بين الخاص والعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص598، تحت «بلاغة تقديم صفة رؤوف على صفة رحيم»","url":""}]},{"id":"s9-692","number":692,"surah":9,"verses":[129],"references":[{"surah":9,"verses":[129]}],"verseLabel":"التوبة: 129","question":"لماذا انتقل من وصف رحمة الرسول إلى قوله: ﴿فإن تولوا فقل حسبي الله﴾؟","answer":"بعد بيان بلوغ شفقته أقصى مدى، سلاه إن أعرضوا بأن الله كافيه؛ فعليه البلاغ لا حملهم على الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص604، تحت «غرض الأمر فقل حسبي الله في السياق»","url":""}]},{"id":"s9-693","number":693,"surah":9,"verses":[129],"references":[{"surah":9,"verses":[129]}],"verseLabel":"التوبة: 129","question":"ما بلاغة الانتقال من الغيبة في ﴿فإن تولوا﴾ إلى خطاب النبي ﷺ في ﴿فقل حسبي الله﴾؟","answer":"يوجه الخطاب إلى النبي ﷺ ليثبت على الاستعانة بالله وتفويض الأمر إليه بعد إعراضهم؛ وفي الأمر طمأنة له بأن الله كافيه، فلا يضره توليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص604، تحت «بلاغة الالتفات من الغيبة إلى الخصوص»","url":""}]},{"id":"s9-694","number":694,"surah":9,"verses":[129],"references":[{"surah":9,"verses":[129]}],"verseLabel":"التوبة: 129","question":"ما مناسبة إتباع الكفاية بالتوحيد في قوله تعالى: ﴿لا إله إلا هو﴾؟","answer":"الجملة استئناف يقرر وحدانية الله ويعلل كفايته: فهو يكفي رسوله ﷺ لأنه لا معبود بحق ولا مدبر للأمر سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص605، تحت «علة الفصل في لا إله إلا هو»","url":""}]},{"id":"s9-695","number":695,"surah":9,"verses":[129],"references":[{"surah":9,"verses":[129]}],"verseLabel":"التوبة: 129","question":"ما سرّ تقديم الجار والمجرور في قوله تعالى: ﴿عليه توكلت﴾؟","answer":"تقديم ﴿عليه﴾ للاختصاص؛ أي لا أفوض أمري ولا أعتمد إلا على الله، فالتوكل عبادة لا تصرف لسواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص606، تحت «سر تقديم الجار والمجرور عليه»","url":""}]},{"id":"s9-696","number":696,"surah":9,"verses":[129],"references":[{"surah":9,"verses":[129]}],"verseLabel":"التوبة: 129","question":"ما مناسبة ختام السورة بقوله تعالى: ﴿وهو رب العرش العظيم﴾؟","answer":"الخاتمة ثناء على عظيم قدرة الله وتعليل للكفاية والتوكل؛ فمن كان رب العرش، أعظم المخلوقات، فهو قادر على نصرة رسوله ﷺ وكفايته ممن تولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص608، تحت «سر ختم السورة برب العرش العظيم»","url":""}]},{"id":"s9-772","number":772,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"ما سر الترتيب في قوله: ﴿فتُكوى بها جباههم وجنوبهم وظهورهم﴾؟","answer":"بدأ بالجباه ثم الجنوب ثم الظهور متدرّجًا بحسب الرتبة. وينقل السامرائي قول من قال: إنهم كانوا إذا رأوا الفقير عبسوا، وإذا ضمّهم وإياه مجلس ازورّوا عنه بجنوبهم، ثم ولّوه ظهورهم، فكان العذاب على هذا الترتيب.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص58.","url":""}]},{"id":"s9-773","number":773,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"ما الفرق بين ﴿ذلك الدين القيّم﴾ بتشديد الياء هنا، و﴿دينًا قِيَمًا﴾ في الأنعام؟","answer":"«القِيَم» مصدر بمعنى الاستقامة نُعت به مبالغة، و«القيّم» صفة مشبهة بمعنى المستقيم. وسياق الأنعام أعمّ يشمل الحياة والعبادة كلها فوُصف بالمصدر، أما آية التوبة ففي عدة الشهور والأشهر الحرم وحكم القتال فيهن، وهي جزء من ذلك، فوُصف بالصفة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص53–55.","url":""}]},{"id":"s9-774","number":774,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"ما دلالة تعدية الإيمان باللام في قوله: ﴿لن نؤمن لكم﴾ وقوله: ﴿ويؤمن للمؤمنين﴾ [61]؟","answer":"الإيمان بالله لا يُعدّى إلا بالباء، نحو ﴿حتى تؤمنوا بالله وحده﴾، فإذا رأيت الإيمان معدّى باللام فاعلم أنه لغير الله. وقد عدّاه القرآن باللام مع الأشخاص غالبًا، بمعنى التصديق لهم فيما يقولون.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص75.","url":""}]},{"id":"s9-775","number":775,"surah":9,"verses":[15,27],"references":[{"surah":9,"verses":[15,27]}],"verseLabel":"التوبة: 15، 27","question":"ما سر ختم ﴿ويتوب الله على من يشاء﴾ بـ﴿والله عليم حكيم﴾ في الآية 15، وبـ﴿والله غفور رحيم﴾ في الآية 27؟","answer":"الآية الأولى في سياق كفار مكة وما فعلوه بالرسول ﷺ من التضييق والإخراج، والأمر بقتالهم وتعذيبهم، ثم التوبة على من أسلم منهم، فناسبها العلم والحكمة بما في القتال وتقديره. أما الثانية ففي حنين وتولّي الناس مدبرين، فناسبها ذكر المغفرة والرحمة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص234.","url":""}]},{"id":"s9-776","number":776,"surah":9,"verses":[22],"references":[{"surah":9,"verses":[22]}],"verseLabel":"التوبة: 22","question":"ما دلالة ذكر ﴿أبدًا﴾ في جزاء المؤمنين: ﴿خالدين فيها أبدًا﴾، وتركه في جزاء المنافقين في الآية 68؟","answer":"يذكر القرآن «الأبد» حين يبسط القول في وصف الفريق أو جزائه، ويتركه حين يوجز. وقد فصّل هنا في صفات المؤمنين من إيمان وهجرة وجهاد، وفي جزائهم من رحمة ورضوان وجنات ونعيم مقيم، فذكر الأبد. أما آية المنافقين فأوجز فيها فلم يذكره.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص104.","url":""}]},{"id":"s9-777","number":777,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"ما سر ترك التوكيد في قوله: ﴿والله لا يهدي القوم الفاسقين﴾، وقد أُكّد في المنافقون بـ«إنّ»؟","answer":"آية التوبة هذه موجّهة إلى المسلمين في إيثار الآباء والأموال على الله ورسوله، فلا تحتاج إلى توكيد. أما سورة المنافقون فهي أشد المواضع تبكيتًا وذمًّا، فصّلت في كذبهم وصدّهم وجبنهم واستكبارهم، فناسبها التوكيد.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص81–82.","url":""}]},{"id":"s9-778","number":778,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"ما دلالة بناء الفعل للمجهول في قوله: ﴿من الذين أُوتوا الكتاب﴾؟","answer":"إذا كان المقام مقام مدح وثناء أظهر ذاته ونسب الإيتاء إلى نفسه فقال: ﴿آتيناهم الكتاب﴾، وإذا كان مقام ذمّ وتقريع قال: ﴿أُوتوا الكتاب﴾. وهذه الآية في ذمّ من لا يؤمن بالله ولا باليوم الآخر منهم، فبُني الفعل للمجهول.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص322–324.","url":""}]},{"id":"s9-779","number":779,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"ما سر التعبير بـ﴿منها﴾ ثم بـ﴿فيهنّ﴾ في قوله: ﴿اثنا عشر شهرًا... منها أربعة حُرُم... فلا تظلموا فيهنّ أنفسكم﴾؟","answer":"جرى التعبير على سُنن العرب؛ فلما ذكر الاثني عشر وهي كثرة قال: ﴿منها﴾ بالمفرد، ولما ذكر الأربعة وهي قلة قال: ﴿فيهنّ﴾ بضمير الجمع، فاستعمل ضمير المفرد للكثرة وضمير الجمع للقلة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص12.","url":""}]},{"id":"s9-780","number":780,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"ما سر التعبير بـ«العام» دون «السنة» في قوله: ﴿يُحِلّونه عامًا ويُحرِّمونه عامًا﴾؟","answer":"خالف القرآن بين العام والسنة؛ فاستعمل العام للواحد وللمثنى وبعد العدد، ولم يجمعه، كما في هذه الآية وفي قوله: ﴿بعد عامهم هذا﴾ [28] و﴿يُفتنون في كل عام﴾ [126]. أما السنة فلم يستعملها مفردة ولا مثناة، بل جاءت كلها في الجمع.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص58.","url":""}]},{"id":"s9-781","number":781,"surah":9,"verses":[55,85],"references":[{"surah":9,"verses":[55,85]}],"verseLabel":"التوبة: 55، 85","question":"ما سر الفروق بين ﴿فلا تعجبك أموالهم ولا أولادهم إنما يريد الله ليعذبهم بها في الحياة الدنيا﴾ و﴿ولا تعجبك أموالهم وأولادهم إنما يريد الله أن يعذبهم بها في الدنيا﴾؟","answer":"الآية 55 في سياق إنفاق الأموال والكلام على أموال المنافقين والصدقات، فزاد «لا» النافية توكيدًا، وزاد اللام في ﴿ليعذبهم﴾ لزيادة الاختصاص وتوكيده. أما الآية 85 ففي سياق آخر، هو القعود عن الخروج والنهي عن الصلاة عليهم، فلم يُحتج إلى هذا التوكيد.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص270–271.","url":""}]},{"id":"s9-782","number":782,"surah":9,"verses":[65,79],"references":[{"surah":9,"verses":[65,79]}],"verseLabel":"التوبة: 65، 79","question":"ما الفرق بين الاستهزاء في قوله: ﴿أبالله وآياته ورسوله كنتم تستهزئون﴾ والسخرية في قوله: ﴿فيسخرون منهم سخر الله منهم﴾؟","answer":"السخرية تدل على فعل يسبق من المسخور منه، ولم ترد في القرآن إلا من الأشخاص، وهي هنا على فعل المؤمنين المتصدقين. أما الاستهزاء فعام في الأشخاص والأعمال وغيرها، فقال: ﴿أبالله وآياته ورسوله﴾. ويستأنس في ذلك بـ«روح المعاني» و«الفروق اللغوية».","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص43–44.","url":""}]},{"id":"s9-783","number":783,"surah":9,"verses":[72],"references":[{"surah":9,"verses":[72]}],"verseLabel":"التوبة: 72","question":"ما دلالة التعبير بـ«الرضوان» دون «الرضا» في قوله: ﴿ورضوان من الله أكبر﴾؟","answer":"الرضوان أكبر الرضا وأعظمه، ولذلك اختص في القرآن برضا الله ولم يُستعمل مع غيره، وقد ورد ثلاث عشرة مرة كلها في رضوانه سبحانه. وينقل في ذلك كلام الراغب في «المفردات».","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص14.","url":""}]},{"id":"s9-784","number":784,"surah":9,"verses":[94,101,105],"references":[{"surah":9,"verses":[94,101,105]}],"verseLabel":"التوبة: 94، 101، 105","question":"ما سر التعبير بالردّ في قوله: ﴿ثم تُردّون إلى عالم الغيب والشهادة﴾ و﴿ثم يُردّون إلى عذاب عظيم﴾ دون الرجوع؟","answer":"يستعمل القرآن «ردّ» في الغالب للأمور الثقيلة المستكرهة، و«رجع» لما هو أخف وأيسر. والآية 94 في المنافقين، وردّهم إلى الله ثقيل عليهم شديد، والآية 101 ردّ إلى العذاب. ويستشهد بما في «ملاك التأويل» من أن لفظ «ردّ» يحتمل من القهر والتعنيف أكثر مما يحتمله «رجع».","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص47–50.","url":""}]},{"id":"s9-785","number":785,"surah":9,"verses":[112],"references":[{"surah":9,"verses":[112]}],"verseLabel":"التوبة: 112","question":"ما دلالة اسم الفاعل دون صيغ المبالغة في قوله: ﴿التائبون العابدون الحامدون﴾؟","answer":"أمر بتبشير هؤلاء وجاء باسم الفاعل، فلم يقل: «التوّابون» ولا «الحمّادون»، ليدلّ على سعة رحمته وعظيم تفضّله، إذ بشّر من لم يكثر ويبالغ في ذلك من المؤمنين. أما «التوّاب» فورد لله لكثرة ما يتوب به على عباده.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص29–30.","url":""}]},{"id":"s9-786","number":786,"surah":9,"verses":[114],"references":[{"surah":9,"verses":[114]}],"verseLabel":"التوبة: 114","question":"ما سر وصف إبراهيم بـ﴿لأوّاه حليم﴾ هنا، وزيادة ﴿مُنيب﴾ في هود: ﴿لحليم أوّاه مُنيب﴾؟","answer":"لم يذكر في سورة التوبة عن إبراهيم إلا آية واحدة في استغفاره لأبيه، وليس قبلها ولا بعدها شيء من خبره، فأوجز في وصفه. أما في هود ففصّل في قصته مع الملائكة ومجادلته في قوم لوط، فزاد في وصفه.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص107.","url":""}]},{"id":"s10-156","number":156,"surah":10,"verses":[1],"references":[{"surah":10,"verses":[1]}],"verseLabel":"يونس: 1","question":"ما سرّ التعبير باسم الإشارة للبعيد في ﴿تلك آيات الكتاب﴾، مع أن الآيات قريبة تُتلى وتُسمع؟","answer":"الإشارة بالبعيد ترفع منزلة الآيات في نفس السامع؛ فهي قريبة في تلاوتها، عالية في قدرها ومعانيها. فالبعد هنا يصور علو الرتبة، ويهيئ القارئ لتلقي كلام جليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص621، تحت «علة إيثار اسم الإشارة ﴿تلك﴾»","url":""}]},{"id":"s10-157","number":157,"surah":10,"verses":[1],"references":[{"surah":10,"verses":[1]}],"verseLabel":"يونس: 1","question":"ما دلالة وصف الكتاب بـ﴿الحكيم﴾؟","answer":"يحتمل الوصف الإحكام والإتقان، واشتمال الكتاب على الحكمة، وكونه حاكمًا على الكتب وبالحلال والحرام؛ فجمع لفظ واحد هذه المعاني المتقاربة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص624، تحت «وجه إيثار الوصف بـ﴿الحكيم﴾»","url":""}]},{"id":"s10-158","number":158,"surah":10,"verses":[2],"references":[{"surah":10,"verses":[2]}],"verseLabel":"يونس: 2","question":"ما سرّ تعميم الإنذار وتخصيص البشارة في قوله: ﴿أن أنذر الناس وبشر الذين آمنوا﴾؟","answer":"الإنذار ينبه الجميع إلى ما يجب اجتنابه وعاقبة مخالفته، أما البشارة بالجزاء الحسن فلمن آمن واستجاب. فاختلاف المفعولين يميز بين عموم التحذير وخصوص الوعد لمن تحقق فيه سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص637، تحت «سر تغاير مفعولي الإنذار والتبشير»","url":""}]},{"id":"s10-159","number":159,"surah":10,"verses":[2],"references":[{"surah":10,"verses":[2]}],"verseLabel":"يونس: 2","question":"ما دلالة إضافة ﴿القدم﴾ إلى ﴿الصدق﴾ في قوله تعالى: ﴿قدم صدق عند ربهم﴾؟","answer":"تفيد الإضافة أن سابقة المؤمنين ومنزلتهم عند الله ثابتة في الحق والخير، خالصة من الزيف؛ فليست منزلة مدعاة، بل قدم موصوفة بالصدق والثبوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص639، تحت «فائدة إضافة (القدم) إلى (الصدق)»","url":""}]},{"id":"s10-175","number":175,"surah":10,"verses":[2],"references":[{"surah":10,"verses":[2]}],"verseLabel":"يونس: 2","question":"ما الصورة البلاغية في قوله تعالى: ﴿قدم صدق عند ربهم﴾؟","answer":"كنّى بالقدم عن العمل الصالح السابق والمنزلة المتقدمة، ويجوز حملها على الاستعارة؛ لأن القدم آلة التقدم والثبات، فأطلقت على ما يتقدم به المؤمن إلى كرامة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص640، تحت «﴿قدم صدق﴾ بين الاستعارة، والكناية»","url":""}]},{"id":"s10-160","number":160,"surah":10,"verses":[3],"references":[{"surah":10,"verses":[3]}],"verseLabel":"يونس: 3","question":"ما سرّ تكرار لفظ الربوبية في قوله تعالى: ﴿إن ربكم الله﴾ ثم ﴿ذلكم الله ربكم﴾؟","answer":"كرر لفظ الربوبية لزيادة التقرير والتذكير، وللتنبيه إلى أن من خلق العالم ودبره وربّى عباده هو وحده المستحق للعبادة؛ ولذلك تفرع عنه الأمر: ﴿فاعبدوه﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص664، تحت «تكرار لفظ الربوبية»","url":""}]},{"id":"s10-161","number":161,"surah":10,"verses":[4],"references":[{"surah":10,"verses":[4]}],"verseLabel":"يونس: 4","question":"ما سرّ التعبير بـ﴿يبدأ الخلق ثم يعيده﴾ دون ذكر الموت بين البداية والإعادة؟","answer":"لأن الإعادة تدل على ما سبقها من حياة ثم موت، فاستُغني بالمذكور عن المحذوف. وبذلك اتصل طرفا الحجة مباشرة: من أنشأ الخلق أول مرة قادر على إعادته، وهو المقصود في الرد على منكري البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص676، تحت «بلاغة الإضمار في: ﴿إنه يبدأ الخلق﴾»","url":""}]},{"id":"s10-162","number":162,"surah":10,"verses":[5],"references":[{"surah":10,"verses":[5]}],"verseLabel":"يونس: 5","question":"ما سرّ التعبير عن الشمس بـ﴿ضياء﴾ وعن القمر بـ﴿نورًا﴾؟","answer":"الضياء يدل هنا على الإشراق القوي الساطع، أما النور فأعم، ويناسب ضوء القمر الألطف. فاختلاف اللفظين يصور اختلاف أثرهما الذي نراه، وما في كل منهما من منفعة ملائمة للنهار أو الليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص688، تحت «سر نسبة الضياء إلى الشمس، والنور إلى القمر»","url":""}]},{"id":"s10-163","number":163,"surah":10,"verses":[5,6],"references":[{"surah":10,"verses":[5,6]}],"verseLabel":"يونس: 5، 6","question":"ما سرّ ختم آية الشمس والقمر بـ﴿لقوم يعلمون﴾، والتي بعدها بـ﴿لقوم يتقون﴾؟","answer":"العلم يفتح باب فهم الدلائل وإدراك إحكامها، والتقوى تحمل صاحبها على الاعتبار بها والحذر من مخالفة خالقها. فتنوع الخاتمتين يبرز جانبين من الانتفاع بالآيات: بصيرة تفهم، وقلب يستجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص707، تحت «بيان التشابه بين ﴿لقوم يعلمون﴾، و﴿لقوم يتقون﴾»","url":""}]},{"id":"s10-164","number":164,"surah":10,"verses":[7],"references":[{"surah":10,"verses":[7]}],"verseLabel":"يونس: 7","question":"ما سر تقديم ﴿رَضُوا بِالْحَيَاةِ الدُّنْيَا﴾ على ﴿وَاطْمَأَنُّوا بِهَا﴾؟","answer":"يوجه المصدر الترتيب بأنه تقديم للنتيجة على علتها؛ إذ سكونهم إلى الدنيا واطمئنانهم بها حملهم على الرضا بها. ويحتمل أن تكون الواو للحال: رضوا بها حال كونهم مطمئنين إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص716، تحت «بلاغة تقديم الرضا على الطمأنينة»","url":""}]},{"id":"s10-165","number":165,"surah":10,"verses":[8],"references":[{"surah":10,"verses":[8]}],"verseLabel":"يونس: 8","question":"ما سرّ التعبير بـ﴿بما كانوا يكسبون﴾ دون «بما كسبوا»؟","answer":"اجتماع ﴿كانوا﴾ مع المضارع يصور الكسب السيئ عادة متكررة استمروا عليها، لا فعلًا عابرًا انقضى. فنسبت الآية العاقبة إلى طريق سلكوه وأصروا عليه من الكفر والغفلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص721، تحت «فائدة ذكر ﴿كانوا﴾»","url":""}]},{"id":"s10-166","number":166,"surah":10,"verses":[9],"references":[{"surah":10,"verses":[9]}],"verseLabel":"يونس: 9","question":"ما دلالة التعبير بالمضارع في قوله تعالى: ﴿يهديهم ربهم﴾؟","answer":"يدل المضارع على أن هداية الله لهم متجددة مستمرة، تثبتهم على الإيمان وترقيهم في مراتب الكمال، وليست هداية عابرة انتهت.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص728، تحت «بلاغة الإخبار بالجملة الفعلية المضارعية»","url":""}]},{"id":"s10-176","number":176,"surah":10,"verses":[9],"references":[{"surah":10,"verses":[9]}],"verseLabel":"يونس: 9","question":"ما معنى الباء في قوله تعالى: ﴿يهديهم ربهم بإيمانهم﴾؟","answer":"الباء للتعليل والسببية؛ فإيمانهم سبب لهداية الله المتتابعة لهم، وفي التعبير تأكيد لارتباط الجزاء بأصل الإيمان الصادق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص729، تحت «معنى الباء في: ﴿بإيمانهم﴾»","url":""}]},{"id":"s10-167","number":167,"surah":10,"verses":[9],"references":[{"surah":10,"verses":[9]}],"verseLabel":"يونس: 9","question":"لماذا قُدّم ﴿مِنْ تَحْتِهِمْ﴾ على ﴿الْأَنْهَارُ﴾ في قوله: ﴿تَجْرِي مِنْ تَحْتِهِمُ الْأَنْهَارُ﴾؟","answer":"قُدّم اهتمامًا وتخصيصًا لإظهار النعمة على أهل الجنة؛ فجريان الأنهار من تحتهم يبرز أنها مهيأة لمنفعتهم وسقايتهم ولذتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص732، تحت «فائدة تقديم الجار والمجرور: ﴿من تحتهم﴾»","url":""}]},{"id":"s10-168","number":168,"surah":10,"verses":[10],"references":[{"surah":10,"verses":[10]}],"verseLabel":"يونس: 10","question":"ما دلالة التعبير بـ﴿دعواهم﴾ في قوله: ﴿دعواهم فيها سبحانك اللهم﴾، مع أن المذكور تسبيح وثناء؟","answer":"الدعوى هنا قولهم وثناؤهم على الله، لا مجرد طلب حاجة؛ فقد غمرهم النعيم، فكانت مناجاتهم تسبيحًا وتنزيهًا وتعظيمًا، وثناءً مقصودًا لذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص738، تحت «نكتة إيثار لفظ الدعوى»","url":""}]},{"id":"s10-169","number":169,"surah":10,"verses":[10],"references":[{"surah":10,"verses":[10]}],"verseLabel":"يونس: 10","question":"ما سرّ افتتاح كلام أهل الجنة بالتسبيح وختمه بالحمد؟","answer":"التسبيح تنزيه لله عن النقص، والحمد ثناء عليه لكماله ونعمه. فجمع التعبير بين تعظيم المنعم وشكر إنعامه، وجعل الحمد خاتمة تلائم ما يشاهدونه من تمام النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص742، تحت «بلاغة الترتيب بين الجمل المتعاطفة»","url":""}]},{"id":"s10-170","number":170,"surah":10,"verses":[11],"references":[{"surah":10,"verses":[11]}],"verseLabel":"يونس: 11","question":"ما دلالة ذكر ﴿استعجالهم بالخير﴾ في سياق الحديث عن تعجيل الشر؟","answer":"اتخذت الآية حرص الإنسان على سرعة مجيء الخير مقياسًا يوضح خطورة طلب الشر: لو عُجّل له ما يدعو به من سوء بتلك السرعة لهلك. فالمقابلة تكشف رحمة الله في الإمهال، وإن استعجل الإنسان ما يضره.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص753، تحت «بلاغة التشبيه: ﴿استعجالهم بالخير﴾»","url":""}]},{"id":"s10-171","number":171,"surah":10,"verses":[12],"references":[{"surah":10,"verses":[12]},{"surah":3,"verses":[191]}],"verseLabel":"يونس: 12؛ آل عمران: 191","question":"ما سرّ اختلاف ترتيب الأحوال بين ﴿لجنبه أو قاعدًا أو قائمًا﴾ في يونس، و﴿قيامًا وقعودًا وعلى جنوبهم﴾ في آل عمران؟","answer":"في يونس مشهد ضر ومرض، فبدأ بالمضطجع، وهو غالبًا أشد عجزًا، ثم القاعد فالقائم. وفي آل عمران مشهد ذكر في أحوال العافية، فبدأ بالقيام. فاختلاف الترتيب يراعي الحال التي يصورها كل سياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص767–768، تحت «توجيه المتشابه اللفظي في ترتيب أحوال الداعين في الصحة والمرض»","url":""}]},{"id":"s10-172","number":172,"surah":10,"verses":[12],"references":[{"surah":10,"verses":[12]}],"verseLabel":"يونس: 12","question":"ما دلالة التعبير بـ﴿مر﴾ في قوله تعالى: ﴿مر كأن لم يدعنا إلى ضر مسه﴾؟","answer":"يصوّر الفعل أنه مضى على عادته الأولى فور كشف الضر، فلم يقف للشكر ولم يلتفت إلى دعائه السابق؛ فكلمة ﴿مر﴾ ترسم سرعة الجحود والانصراف عن مقام الابتهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص771، تحت «براعة التعبير بالفعل ﴿مر﴾ جوابًا لـ﴿فلما﴾»","url":""}]},{"id":"s10-173","number":173,"surah":10,"verses":[13],"references":[{"surah":10,"verses":[13]}],"verseLabel":"يونس: 13","question":"ما دلالة استعمال ﴿كانوا﴾ في قوله تعالى: ﴿وما كانوا ليؤمنوا﴾؟","answer":"تفيد أن التكذيب والظلم تمكنا منهم وصارا عادة مستمرة؛ فجاء نفي الإيمان وصفًا لحال رسخت بأعمالهم واختيارهم، لا لموقف عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص787، تحت «دلالة استعمال: ﴿كانوا﴾»","url":""}]},{"id":"s10-177","number":177,"surah":10,"verses":[13],"references":[{"surah":10,"verses":[13]}],"verseLabel":"يونس: 13","question":"ما دلالة اللام في قوله تعالى: ﴿وما كانوا ليؤمنوا﴾؟","answer":"هي لام الجحود، تؤكد نفي الإيمان وتبالغ فيه؛ أي بلغ إصرارهم على الكفر حدًّا صار معه رجوعهم إلى الإيمان أمرًا ميؤوسًا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص788، تحت «دلالة اللام في: ﴿ليؤمنوا﴾»","url":""}]},{"id":"s10-174","number":174,"surah":10,"verses":[14],"references":[{"surah":10,"verses":[14]}],"verseLabel":"يونس: 14","question":"ما دلالة قوله: ﴿لننظر كيف تعملون﴾ مع إحاطة علم الله بأعمال العباد قبل وقوعها؟","answer":"المقصود ظهور العمل في الواقع الذي يقع عليه الجزاء، لا اكتساب علم لم يكن. فالله يعلم ما سيعملون، ثم يُمهلون ويُمكَّنون حتى يصدر منهم العمل نفسه، فتقوم عليهم الحجة بما فعلوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص796، تحت «سر التعبير بالنظر: ﴿لننظر﴾»","url":""}]},{"id":"s10-1","number":1,"surah":10,"verses":[15],"references":[{"surah":10,"verses":[15]}],"verseLabel":"يونس: 15","question":"لماذا طلبوا: ﴿ائت بقرآن غير هذا أو بدله﴾؟","answer":"أرادوا قرآنًا يوافق أهواءهم ولا يذم أصنامهم ولا ينذرهم بالبعث والجزاء؛ فكان طلبهم تغييرًا لمضمون الرسالة، وفيه تعنت ومحاولة للطعن في كون القرآن وحيًا من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص22، تحت «الغرض من طلبهم تغيير القرآن»","url":""}]},{"id":"s10-2","number":2,"surah":10,"verses":[15],"references":[{"surah":10,"verses":[15]}],"verseLabel":"يونس: 15","question":"ما دلالة قول النبي: ﴿ما يكون لي أن أبدله من تلقاء نفسي﴾؟","answer":"نفى أن يملك تبديله من عند نفسه لأن القرآن وحي يتبع فيه ما يوحى إليه؛ فليس الرسول ﷺ منشئًا للنص حتى يغيره استجابة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص27، تحت «دلالة النفي في ما يكون لي»","url":""}]},{"id":"s10-3","number":3,"surah":10,"verses":[15],"references":[{"surah":10,"verses":[15]}],"verseLabel":"يونس: 15","question":"لماذا ختم بقوله: ﴿إني أخاف إن عصيت ربي عذاب يوم عظيم﴾؟","answer":"ختم بالخوف من العذاب لبيان أن تبديل الوحي معصية عظيمة لا يقدم عليها الرسول ﷺ، وفيه رد عملي على طلبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص32، تحت «الموقع البياني للجملة إني أخاف»","url":""}]},{"id":"s10-4","number":4,"surah":10,"verses":[16],"references":[{"surah":10,"verses":[16]}],"verseLabel":"يونس: 16","question":"لماذا احتج عليهم بقوله: ﴿فقد لبثت فيكم عمرًا من قبله﴾؟","answer":"عاش بينهم زمنًا طويلًا قبل الوحي يعرفون صدقه وأمانته ولم يقل شعرًا أو يتعاط تأليفًا؛ فكيف ينسبون إليه فجأة اختلاق القرآن؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص52، تحت «براعة الاستدلال فقد لبثت فيكم عمرا من قبله»","url":""}]},{"id":"s10-5","number":5,"surah":10,"verses":[16],"references":[{"surah":10,"verses":[16]}],"verseLabel":"يونس: 16","question":"لماذا ختم الحجة بقوله: ﴿أفلا تعقلون﴾؟","answer":"العقل كاف في وصل مقدمات الحجة بنتيجتها: من عرفوا سيرته وأميته وطول مكثه بينهم ينبغي أن يدركوا أن القرآن ليس من عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص53، تحت «دلالة التعبير بالاستفهام والفاء والنفي في أفلا تعقلون»","url":""}]},{"id":"s10-6","number":6,"surah":10,"verses":[17],"references":[{"surah":10,"verses":[17]}],"verseLabel":"يونس: 17","question":"لماذا جمع بين ﴿افترى على الله كذبًا﴾ و﴿كذب بآياته﴾؟","answer":"الأول إنشاء للكذب ونسبته إلى الله، والثاني رد للآيات الصادقة بعد مجيئها؛ فجمع طرفي الجريمة: اختلاق الباطل وإنكار الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص64، تحت «الفرق الدلالي بين كذبا وكذب»","url":""}]},{"id":"s10-7","number":7,"surah":10,"verses":[17],"references":[{"surah":10,"verses":[17]}],"verseLabel":"يونس: 17","question":"لماذا ختم بـ﴿إنه لا يفلح المجرمون﴾؟","answer":"المجرم لا يبلغ مطلوبه ولا ينجو من عاقبته؛ والخاتمة قاعدة تشمل المفترين والمكذبين وتقطع دعوى فلاحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص65، تحت «بلاغة التذييل في إنه لا يفلح المجرمون»","url":""}]},{"id":"s10-8","number":8,"surah":10,"verses":[18],"references":[{"surah":10,"verses":[18]}],"verseLabel":"يونس: 18","question":"كيف يكشف قول المشركين: ﴿هؤلاء شفعاؤنا عند الله﴾ تناقض عبادتهم للأصنام؟","answer":"زعموا للأصنام منزلة الشفاعة ليقربوها من مقام العبادة، مع أنها لا تملك ضرًا ولا نفعًا. فجمع النظم بين عجزها ودعواهم الشفاعة لها ليكشف بطلان حجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص73، تحت «المعنى الإجمالي»","url":""}]},{"id":"s10-9","number":9,"surah":10,"verses":[18],"references":[{"surah":10,"verses":[18]}],"verseLabel":"يونس: 18","question":"ما دلالة الاستفهام في قوله تعالى: ﴿أتنبئون الله﴾؟","answer":"الاستفهام للإنكار والتهكم؛ إذ لا يصح أن يخبر المشركون الله بشفعاء مزعومين في ملكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص82، تحت «دلالة أسلوب الاستفهام في أتنبئون»","url":""}]},{"id":"s10-178","number":178,"surah":10,"verses":[18],"references":[{"surah":10,"verses":[18]}],"verseLabel":"يونس: 18","question":"ما دلالة النفي بما لا يعلم في قوله تعالى: ﴿بما لا يعلم﴾؟","answer":"ما لا يعلمه الله مستحيل الوجود؛ فالعبارة تنفي وجود الشفعاء الذين زعموهم نفيًا قاطعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص84، تحت «دلالة النفي بما لا يعلم»","url":""}]},{"id":"s10-10","number":10,"surah":10,"verses":[19],"references":[{"surah":10,"verses":[19]}],"verseLabel":"يونس: 19","question":"ما علة ذكر الاختلاف بعد الوحدة في قوله تعالى: ﴿كان الناس أمة واحدة فاختلفوا﴾؟","answer":"كان الناس على أصل التوحيد أو جماعة واحدة ثم طرأ الاختلاف؛ فالنظم يقرر أن التفرق في الدين عارض لا أصل في الفطرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص95، تحت «علة ذكر الاختلاف بعد الوحدة»","url":""}]},{"id":"s10-11","number":11,"surah":10,"verses":[19],"references":[{"surah":10,"verses":[19]}],"verseLabel":"يونس: 19","question":"لماذا أُخّر الفصل بينهم بسبب ﴿كلمة سبقت من ربك﴾؟","answer":"الكلمة السابقة هي تأخير الفصل التام إلى أجل القيامة؛ ولولا هذا القضاء لعوجلوا بالحكم والعقوبة عند اختلافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص97، تحت «دلالة التعبير بالجملة الشرطية في ولولا»","url":""}]},{"id":"s10-12","number":12,"surah":10,"verses":[20],"references":[{"surah":10,"verses":[20]}],"verseLabel":"يونس: 20","question":"ما دلالة قولهم: ﴿لولا أنزل عليه آية من ربه﴾ مع كثرة الآيات؟","answer":"أرادوا آية حسية مقترحة توافق تعنتهم، مع أن القرآن والآيات القائمة كافية؛ فليس طلبهم بحثًا عن دليل بل مراوغة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص110، تحت «توجيه لفظ آية»","url":""}]},{"id":"s10-13","number":13,"surah":10,"verses":[20],"references":[{"surah":10,"verses":[20]}],"verseLabel":"يونس: 20","question":"لماذا جاء الأمر في قوله تعالى: ﴿فانتظروا﴾؟","answer":"جاء الأمر للتهديد: انتظروا حكم الله وعاقبة التكذيب، فستظهر الحقيقة التي جحدتموها.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص114، تحت «علة ورود فعل الأمر في فانتظروا»","url":""}]},{"id":"s10-179","number":179,"surah":10,"verses":[20],"references":[{"surah":10,"verses":[20]}],"verseLabel":"يونس: 20","question":"ما دلالة المعية في إني معكم في قوله تعالى: ﴿إني معكم من المنتظرين﴾؟","answer":"فيه تحدٍّ وطمأنينة إلى وعد الله؛ فالرسول ﷺ ينتظر معهم ما يقضي الله به، لكن العاقبة ستكون على المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص116، تحت «دلالة المعية في إني معكم»","url":""}]},{"id":"s10-14","number":14,"surah":10,"verses":[21],"references":[{"surah":10,"verses":[21]}],"verseLabel":"يونس: 21","question":"ما بلاغة التعبير بالإذاقة في قوله تعالى: ﴿وإذا أذقنا الناس رحمة﴾؟","answer":"تصوّر الإذاقة الرحمة أمرًا محسوس الأثر يباشرونه ويجدون نفعه، فكان الواجب أن يقابلوها بالشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص123، تحت «بلاغة الاستعارة في التعبير بالإذاقة في وإذا أذقنا»","url":""}]},{"id":"s10-180","number":180,"surah":10,"verses":[21],"references":[{"surah":10,"verses":[21]}],"verseLabel":"يونس: 21","question":"ما بلاغة التعبير بالمس في قوله تعالى: ﴿من بعد ضراء مستهم﴾؟","answer":"يصوّر المس الضر قد باشرهم وأصابهم إصابة محسوسة، ثم كشفه الله عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص126، تحت «بلاغة الاستعارة في التعبير بالمس في مستهم»","url":""}]},{"id":"s10-15","number":15,"surah":10,"verses":[21],"references":[{"surah":10,"verses":[21]}],"verseLabel":"يونس: 21","question":"ما النكتة البلاغية في دخول إذا على جواب الشرط في قوله تعالى: ﴿إذا لهم مكر في آياتنا﴾؟","answer":"﴿إذا﴾ الفجائية تصور مبادرتهم إلى الطعن والتكذيب فور الرحمة، بدل الشكر الذي يقتضيه المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص126، تحت «نكتة دخول إذا على جواب الشرط»","url":""}]},{"id":"s10-16","number":16,"surah":10,"verses":[21],"references":[{"surah":10,"verses":[21]}],"verseLabel":"يونس: 21","question":"لماذا سُمّيت مجازاة الله للمشركين على مكرهم مكرًا في قوله: ﴿الله أسرع مكرًا﴾؟","answer":"جاء اللفظ على المشاكلة؛ فمكر الله بهم هو إبطال تدبيرهم ومجازاتهم عليه من حيث لا يشعرون، لا المكر المذموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص130، تحت «بلاغة المشاكلة»","url":""}]},{"id":"s10-181","number":181,"surah":10,"verses":[21],"references":[{"surah":10,"verses":[21]}],"verseLabel":"يونس: 21","question":"ما دلالة اسم التفضيل ﴿أسرع﴾ في قوله تعالى: ﴿الله أسرع مكرًا﴾؟","answer":"يدل على أن تدبيرهم لا يسبق إحاطة الله ولا يفلت من مجازاته؛ فجزاء مكرهم أسرع نفاذًا من حيلتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص130، تحت «فائدة اسم التفضيل في أسرع»","url":""}]},{"id":"s10-17","number":17,"surah":10,"verses":[22],"references":[{"surah":10,"verses":[22]}],"verseLabel":"يونس: 22","question":"ما سر الانتقال من الخطاب في ﴿كنتم في الفلك﴾ إلى الغيبة في ﴿وجرين بهم﴾؟","answer":"ينقل الالتفات حالهم من خطاب النعمة إلى حكاية مشهدهم للسامع؛ ليتعجب من تقلبهم بين الإخلاص عند الخوف والبغي بعد النجاة. وفي الغيبة هنا أيضًا إعراض عنهم وتبعيد لهم حين انكشف جحودهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص141، تحت «فائدة الالتفات بالضمائر من الخطاب إلى الغيبة وجرين بهم»","url":""}]},{"id":"s10-18","number":18,"surah":10,"verses":[22],"references":[{"surah":10,"verses":[22]}],"verseLabel":"يونس: 22","question":"لماذا وُصفت الريح في قوله تعالى: ﴿بريح طيبة﴾ بأنها طيبة؟","answer":"لأنها توافق سير السفن برفق وتلائم حال الأمن والفرح الذي كان فيه ركابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص150، تحت «غرض وصف الريح بأنها طيبة»","url":""}]},{"id":"s10-182","number":182,"surah":10,"verses":[22],"references":[{"surah":10,"verses":[22]}],"verseLabel":"يونس: 22","question":"لماذا وُصفت الريح في قوله تعالى: ﴿جاءتها ريح عاصف﴾ بأنها عاصف؟","answer":"لتصوير شدتها وخطرها حين قلبت حال الركاب من الأمن والفرح إلى الخوف من الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص152، تحت «غرض وصف الريح بأنها عاصف»","url":""}]},{"id":"s10-19","number":19,"surah":10,"verses":[22],"references":[{"surah":10,"verses":[22]}],"verseLabel":"يونس: 22","question":"ما وجه البلاغة في الاستعارة في التعبير بالإحاطة في أحيط بهم في قوله تعالى: ﴿وظنوا أنهم أحيط بهم﴾؟","answer":"﴿أحيط بهم﴾ تصور الخطر محاصرًا من كل جانب حتى انقطعت أسباب النجاة، فعندها أخلصوا الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص156، تحت «بلاغة الاستعارة في التعبير بالإحاطة في أحيط بهم»","url":""}]},{"id":"s10-20","number":20,"surah":10,"verses":[23],"references":[{"surah":10,"verses":[23]}],"verseLabel":"يونس: 23","question":"ما دلالة دخول إذا في جواب لما في قوله تعالى: ﴿فلما أنجاهم إذا هم يبغون﴾؟","answer":"الفجاءة في ﴿إذا هم يبغون﴾ تكشف سرعة نقضهم عهد الإخلاص؛ فما إن تحققت النجاة حتى عادوا إلى الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص167، تحت «دلالة دخول إذا في جواب لما»","url":""}]},{"id":"s10-21","number":21,"surah":10,"verses":[23],"references":[{"surah":10,"verses":[23]}],"verseLabel":"يونس: 23","question":"ما وجه البلاغة في أسلوب القصر بإنما في قوله تعالى: ﴿إنما بغيكم على أنفسكم﴾؟","answer":"قصر أثر البغي عليهم؛ فضرره وعقوبته راجعان إلى صاحبه، ولا يضر الله ولا يعجزه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص174، تحت «بلاغة أسلوب القصر بإنما»","url":""}]},{"id":"s10-22","number":22,"surah":10,"verses":[24],"references":[{"surah":10,"verses":[24]}],"verseLabel":"يونس: 24","question":"لماذا شُبّهت الحياة الدنيا بمشهد الماء والنبات الذي يزدهر ثم يزول؟","answer":"التشبيه للمشهد كله: يبدأ النبات بالماء، ثم يزدهر وتتعلق به الآمال، ثم يزول سريعًا. وهكذا متاع الدنيا؛ يبهج صاحبه ويغره امتداده ثم ينقضي، فالصورة تكشف قصره وسرعة تحوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص189، تحت «بلاغة التشبيه المركب»","url":""}]},{"id":"s10-23","number":23,"surah":10,"verses":[24],"references":[{"surah":10,"verses":[24]}],"verseLabel":"يونس: 24","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿أخذت الأرض زخرفها وازينت﴾؟","answer":"صوّرت الأرض كأنها امرأة اكتست زينتها حتى بلغت غاية الحسن؛ فاشتد تعلق أهلها بها واغترارهم بنضرتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص197، تحت «بلاغة الاستعارة في تزين الأرض»","url":""}]},{"id":"s10-183","number":183,"surah":10,"verses":[24],"references":[{"surah":10,"verses":[24]}],"verseLabel":"يونس: 24","question":"ما دلالة الجملة الاسمية في قوله تعالى: ﴿وظن أهلها أنهم قادرون عليها﴾؟","answer":"تصوّر الجملة رسوخ ظنهم بالتمكن من ثمرها واستقرار اطمئنانهم إليها؛ فعند تمام الاغترار جاء أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص198، تحت «نكتة التعبير بالجملة الاسمية أنهم قادرون عليها»","url":""}]},{"id":"s10-24","number":24,"surah":10,"verses":[24],"references":[{"surah":10,"verses":[24]}],"verseLabel":"يونس: 24","question":"ما بلاغة التعبير في قوله تعالى: ﴿فجعلناها حصيدًا﴾؟","answer":"صوّر النبات بعد هلاكه حصيدًا مقطوعًا مستأصلًا، بعد أن كان ناميًا مزدهرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص200، تحت «بلاغة المجاز والاستعارة في فجعلناها حصيدا»","url":""}]},{"id":"s10-184","number":184,"surah":10,"verses":[24],"references":[{"surah":10,"verses":[24]}],"verseLabel":"يونس: 24","question":"ما فائدة التشبيه في قوله تعالى: ﴿كأن لم تغن﴾؟","answer":"يبالغ التشبيه في تصوير سرعة زوال بهجة الأرض حتى كأنها لم تعمر ولم تنعم من قبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص200، تحت «معنى كأن وفائدة التشبيه»","url":""}]},{"id":"s10-185","number":185,"surah":10,"verses":[24],"references":[{"surah":10,"verses":[24]}],"verseLabel":"يونس: 24","question":"ما دلالة التعريف في قوله تعالى: ﴿بالأمس﴾؟","answer":"يشير إلى الماضي القريب المعلوم، فيبرز شدة سرعة التحول من النضرة إلى الفناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص201، تحت «معنى أل في بالأمس»","url":""}]},{"id":"s10-25","number":25,"surah":10,"verses":[25],"references":[{"surah":10,"verses":[25]}],"verseLabel":"يونس: 25","question":"لماذا جاءت ﴿والله يدعو إلى دار السلام﴾ بعد مثل الدنيا الزائلة؟","answer":"بعد صورة الدار الزائلة جاء النداء إلى دار السلام الباقية؛ فالمقابلة تنقل القلب من الاغترار بالدنيا إلى اختيار الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص207، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s10-26","number":26,"surah":10,"verses":[25],"references":[{"surah":10,"verses":[25]}],"verseLabel":"يونس: 25","question":"لماذا أضاف الجنة إلى ﴿السلام﴾؟","answer":"هي دار السلامة من الموت والحزن والآفات، أو دار الله السلام؛ فالإضافة تجمع الأمان وكرامة القرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص210، تحت «نكتة تخصيص اسم الله السلام»","url":""}]},{"id":"s10-27","number":27,"surah":10,"verses":[26],"references":[{"surah":10,"verses":[26]}],"verseLabel":"يونس: 26","question":"ما سرّ التعبير بـ﴿الحسنى﴾ في قوله تعالى: ﴿للذين أحسنوا الحسنى﴾؟","answer":"﴿الحسنى﴾ هي المثوبة البالغة غاية الحسن، وأعظمها الجنة؛ فجاء اللفظ مناسبًا لإحسانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص219، تحت «سر التعبير بالحسنى»","url":""}]},{"id":"s10-186","number":186,"surah":10,"verses":[26],"references":[{"surah":10,"verses":[26]}],"verseLabel":"يونس: 26","question":"ما معنى ﴿زيادة﴾ في قوله تعالى: ﴿وزيادة﴾، وما وجه التعبير بها؟","answer":"هي فضل زائد على الجزاء المستحق، وأعظمه النظر إلى وجه الله؛ فثواب المحسنين إحسان وزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص221، تحت «بيان معنى الزيادة في وزيادة ووجه التعبير بها»","url":""}]},{"id":"s10-28","number":28,"surah":10,"verses":[26],"references":[{"surah":10,"verses":[26]}],"verseLabel":"يونس: 26","question":"ما سرّ عطف الذلة على القتر في قوله تعالى: ﴿ولا يرهق وجوههم قتر ولا ذلة﴾؟","answer":"الرهق غشيان يغطي الوجوه، فنفى عنها سواد الكآبة والذل معًا؛ فظهر الأمن والكرامة على سيمائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص225، تحت «سر عطف الذلة على القتر»","url":""}]},{"id":"s10-29","number":29,"surah":10,"verses":[27],"references":[{"surah":10,"verses":[27]}],"verseLabel":"يونس: 27","question":"ما سرّ التعبير في قوله تعالى في السيئة: ﴿جزاء سيئة بمثلها﴾، دون أن يقال مثل ما قال في الحسنة: «وزيادة»؟","answer":"العدل يقتضي أن السيئة لا تضاعف بل تجازى بمثلها، أما الحسنة فتزاد فضلًا؛ فافترق مقام العدل عن مقام الإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص242، تحت «وجه المقابلة بين ذكر عمال الحسنات وعمال السيئات»","url":""}]},{"id":"s10-30","number":30,"surah":10,"verses":[27],"references":[{"surah":10,"verses":[27]}],"verseLabel":"يونس: 27","question":"لماذا شُبهت وجوههم بقطع من الليل مظلمًا؟","answer":"صورت الظلمة تغطي وجوههم قطعًا متراكمة من ليل شديد الإظلام؛ فجمعت السواد والخوف والمهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص246، تحت «بلاغة التشبيه والاستعارة»","url":""}]},{"id":"s10-31","number":31,"surah":10,"verses":[28],"references":[{"surah":10,"verses":[28]}],"verseLabel":"يونس: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿مكانكم أنتم وشركاؤكم﴾ يوم الحشر؟","answer":"اسم الفعل ﴿مكانكم﴾ يأمرهم بالثبات في موضعهم هم وشركاؤهم للحساب، وفيه زجر يمنع الفرار واختلاط الصفوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص260، تحت «وجه التعبير بمكانكم وإضافته»","url":""}]},{"id":"s10-32","number":32,"surah":10,"verses":[28],"references":[{"surah":10,"verses":[28]}],"verseLabel":"يونس: 28","question":"ما دلالة إيثار لفظ زيلنا في قوله تعالى: ﴿فزيلنا بينهم﴾؟","answer":"﴿زيلنا﴾ أي فرقنا وميزنا بينهم بعد اجتماعهم في الدنيا على العبادة؛ فبانت براءة المعبودين وبطلان الصلة المزعومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص263، تحت «إيثار لفظ زيلنا»","url":""}]},{"id":"s10-33","number":33,"surah":10,"verses":[29],"references":[{"surah":10,"verses":[29]}],"verseLabel":"يونس: 29","question":"ما دلالة قول الشركاء: ﴿فكفى بالله شهيدًا بيننا وبينكم﴾؟","answer":"استشهدوا بالله لأنه المحيط بحقيقة الحال، وليكذبوا دعوى العابدين أن عبادتهم كانت بعلمهم ورضاهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص273، تحت «توجيه التعبير بلفظ كفى»","url":""}]},{"id":"s10-34","number":34,"surah":10,"verses":[29],"references":[{"surah":10,"verses":[29]}],"verseLabel":"يونس: 29","question":"ما سرّ التعبير عن الغفلة باسم الفاعل مجموعا في قوله تعالى: ﴿إن كنا عن عبادتكم لغافلين﴾؟","answer":"الغفلة هنا نفي العلم والرضا بعبادتهم؛ فالمعبودون الباطلون لم يشعروا بها أو لم يقروها، فلا تقوم شفاعة مزعومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص278، تحت «سر التعبير عن الغفلة باسم الفاعل مجموعا»","url":""}]},{"id":"s10-35","number":35,"surah":10,"verses":[30],"references":[{"surah":10,"verses":[30]}],"verseLabel":"يونس: 30","question":"ما دلالة اسم الإشارة ﴿هنالك﴾ في قوله: ﴿هنالك تبلو كل نفس ما أسلفت﴾؟","answer":"يشير ﴿هنالك﴾ إلى مقام الحساب المهول الذي تنكشف فيه حقائق الأعمال وعواقبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص284، تحت «وجه التعبير باسم الإشارة هنالك»","url":""}]},{"id":"s10-187","number":187,"surah":10,"verses":[30],"references":[{"surah":10,"verses":[30]}],"verseLabel":"يونس: 30","question":"ما بلاغة الكناية في قوله تعالى: ﴿تبلو كل نفس ما أسلفت﴾؟","answer":"كني بالفعل ﴿تبلو﴾ عن اختبار النفس لما قدمت ومعرفة حقيقته وعاقبته؛ فيتميز لها نفع عملها من ضرره.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص286، تحت «بلاغة الكناية»","url":""}]},{"id":"s10-36","number":36,"surah":10,"verses":[30],"references":[{"surah":10,"verses":[30]}],"verseLabel":"يونس: 30","question":"لماذا وصف الله بأنه ﴿مولاهم الحق﴾ عند رد الخلق إليه؟","answer":"لأنه الولي الحق الذي ظهرت ولايته وانفرادُه بالحكم بعد سقوط كل ولاية مدعاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص290، تحت «نكتة الوصف بمولاهم الحق»","url":""}]},{"id":"s10-188","number":188,"surah":10,"verses":[30],"references":[{"surah":10,"verses":[30]}],"verseLabel":"يونس: 30","question":"ما وجه تعدية الضلال بعن في قوله تعالى: ﴿وضل عنهم ما كانوا يفترون﴾؟","answer":"صوّر ما افتروه من آلهة وشفاعة كشيء غاب عنهم وفقدوه عند الحاجة، فانقطعت الصلة المزعومة وبطل نفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص291، تحت «وجه تعدية الضلال بعن»","url":""}]},{"id":"s10-37","number":37,"surah":10,"verses":[31],"references":[{"surah":10,"verses":[31]}],"verseLabel":"يونس: 31","question":"لماذا تتابعت الأسئلة: من يرزق؟ ومن يملك السمع والأبصار؟ ومن يخرج الحي؟ ومن يدبر الأمر؟","answer":"جمعت الأسئلة أصول النعمة والقدرة: الرزق، والحواس، وإخراج الحي والميت، ثم عُمّم ذلك بتدبير الأمر كله؛ لتلزمهم بأن المدبر الواحد هو المستحق للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص299، تحت «بلاغة حشد الاستفهامات»","url":""}]},{"id":"s10-38","number":38,"surah":10,"verses":[31],"references":[{"surah":10,"verses":[31]}],"verseLabel":"يونس: 31","question":"لماذا أعقب إقرارهم بأن الله يدبر الأمر بقوله: ﴿فقل أفلا تتقون﴾؟","answer":"بعد إقرارهم بربوبيته جاء سؤال التقوى: إذا كان هو الفاعل وحده، أفلا تتقون الشرك وتفردونه بالعبادة؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص315، تحت «توجيه التعبير بالاستفهام في أفلا»","url":""}]},{"id":"s10-39","number":39,"surah":10,"verses":[32],"references":[{"surah":10,"verses":[32]}],"verseLabel":"يونس: 32","question":"ما بلاغة اسم الإشارة في قوله تعالى: ﴿فذلكم الله ربكم الحق﴾؟","answer":"يعقب اسم الإشارة اعترافهم بأفعال الربوبية ليعين الله الموصوف بتلك الأفعال، ويقرر أنه ربهم الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص321، تحت «بلاغة استخدام اسم الإشارة فذلكم»","url":""}]},{"id":"s10-189","number":189,"surah":10,"verses":[32],"references":[{"surah":10,"verses":[32]}],"verseLabel":"يونس: 32","question":"ما دلالة القصر في قوله تعالى: ﴿فماذا بعد الحق إلا الضلال﴾؟","answer":"يقصر ما يجاوز الحق على الضلال، فينفي وجود منزلة وسطى بين توحيد الله والانصراف عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص327، تحت «وجه القصر»","url":""}]},{"id":"s10-40","number":40,"surah":10,"verses":[32],"references":[{"surah":10,"verses":[32]}],"verseLabel":"يونس: 32","question":"لماذا ختم بقوله: ﴿فأنى تصرفون﴾؟","answer":"الاستفهام للتعجب والتوبيخ: من أي جهة يصرفون عن الحق الواضح بعد أن أقرت به ألسنتهم؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص328، تحت «بلاغة الاستفهام بأنى»","url":""}]},{"id":"s10-41","number":41,"surah":10,"verses":[33],"references":[{"surah":10,"verses":[33]}],"verseLabel":"يونس: 33","question":"ما بلاغة التشبيه في قوله تعالى: ﴿كذلك حقت كلمة ربك﴾؟","answer":"كما ثبت انصرافهم عن الحق ثبت عليهم قضاء الله بعدم الإيمان لإصرارهم، فجاء الجزاء موافقا لاختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص334، تحت «بلاغة التشبيه في كذلك حقت»","url":""}]},{"id":"s10-190","number":190,"surah":10,"verses":[33],"references":[{"surah":10,"verses":[33]}],"verseLabel":"يونس: 33","question":"لماذا وصف من حقت عليهم الكلمة بأنهم ﴿فسقوا﴾؟","answer":"لأن الفسق خروج متعمد عن طاعة الله وحدوده، فبيّن الوصف سبب استحقاقهم الحكم بعد إصرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص340، تحت «نكتة التعبير بالفسق»","url":""}]},{"id":"s10-42","number":42,"surah":10,"verses":[34],"references":[{"surah":10,"verses":[34]}],"verseLabel":"يونس: 34","question":"لماذا جُدّد سؤال بدء الخلق وإعادته في قوله تعالى: ﴿هل من شركائكم من يبدأ الخلق ثم يعيده﴾؟","answer":"جاء السؤال بعد محاجة المشركين في شركائهم ليطالبهم بدليل على أن واحدًا منها يقدر على بدء الخلق أو إعادته؛ فلما عجزوا ثبت أن الله وحده هو الفاعل المستحق للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص342، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s10-191","number":191,"surah":10,"verses":[34],"references":[{"surah":10,"verses":[34]}],"verseLabel":"يونس: 34","question":"ما دلالة استئناف قوله تعالى في أول سورة يونس: ﴿إنه يبدأ الخلق ثم يعيده﴾؟","answer":"استؤنفت الجملة لتقرير قدرة الله على بدء الخلق وإعادته أصلًا من أصول العقيدة، وتعليل الرجوع إليه والجزاء بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص674، تحت «دلالة جملة الاستئناف إنه يبدأ الخلق»","url":""}]},{"id":"s10-43","number":43,"surah":10,"verses":[34],"references":[{"surah":10,"verses":[34]}],"verseLabel":"يونس: 34","question":"لماذا ختم بـ﴿فأنى تؤفكون﴾؟","answer":"﴿تؤفكون﴾ أي تصرفون بالكذب عن الحق؛ والاستفهام يعجب من انقلابهم عن إقرارهم بعجز الشركاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص348، تحت «الغرض من التعبير بالاستفهام المجازي في فأنى تؤفكون»","url":""}]},{"id":"s10-44","number":44,"surah":10,"verses":[35],"references":[{"surah":10,"verses":[35]}],"verseLabel":"يونس: 35","question":"لماذا سأل: ﴿هل من شركائكم من يهدي إلى الحق﴾ ثم قال: ﴿قل الله يهدي للحق﴾؟","answer":"السؤال يكشف عجز الشركاء حتى عن الهداية، ثم يثبت أن الله وحده يهدي إلى الحق؛ فكيف يعبد العاجز ويترك الهادي؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص352، تحت «الجواب الملقن ودلالته»","url":""}]},{"id":"s10-45","number":45,"surah":10,"verses":[35],"references":[{"surah":10,"verses":[35]}],"verseLabel":"يونس: 35","question":"ما سرّ الفرق بين نفي الاهتداء مع أن السياق لنفي الهداية في قوله تعالى: ﴿أفمن يهدي إلى الحق أحق أن يتبع أمن لا يهدي إلا أن يهدى﴾؟","answer":"المقابلة تقيم برهان الأحقية بالاتباع: الله يهدي بذاته، والشريك لا يهتدي فضلا عن أن يهدي إلا إذا هداه غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص357، تحت «سر الفرق بين نفي الاهتداء مع أن السياق لنفي الهداية»","url":""}]},{"id":"s10-46","number":46,"surah":10,"verses":[36],"references":[{"surah":10,"verses":[36]}],"verseLabel":"يونس: 36","question":"ما دلالة القصر في قوله تعالى: ﴿وما يتبع أكثرهم إلا ظنا﴾؟","answer":"يقصر مستند أكثرهم على الظن والتقليد من غير علم، فيبطل بناء العقيدة على التوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص362، تحت «الغرض من التعبير بأسلوب القصر»","url":""}]},{"id":"s10-192","number":192,"surah":10,"verses":[36],"references":[{"surah":10,"verses":[36]}],"verseLabel":"يونس: 36","question":"لماذا قصر اتباع الظن على ﴿أكثرهم﴾ ولم يعمهم جميعا؟","answer":"لأن منهم من عرف الحق فعاند، ولأن بعضهم سيؤمن؛ فلا يستوي الجميع في حقيقة حالهم ومآلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص363، تحت «سر قصر الحكم على أكثرهم»","url":""}]},{"id":"s10-47","number":47,"surah":10,"verses":[36],"references":[{"surah":10,"verses":[36]}],"verseLabel":"يونس: 36","question":"ما موقع جملة إن الظن ودلالته في قوله تعالى: ﴿إن الظن لا يغني من الحق شيئا﴾؟","answer":"الظن لا يقوم مقام اليقين ولا يدفع شيئا من الحق الثابت؛ فبطل أن تبنى العقيدة على توهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص363، تحت «موقع جملة إن الظن ودلالته»","url":""}]},{"id":"s10-48","number":48,"surah":10,"verses":[37],"references":[{"surah":10,"verses":[37]}],"verseLabel":"يونس: 37","question":"ما سرّ استخدام أسلوب النفي على وجه الجحود في قوله تعالى: ﴿وما كان هذا القرآن أن يفترى من دون الله﴾؟","answer":"﴿ما كان﴾ تنفي إمكان افترائه نفيا يناسب منزلته ونظمه وموافقته للوحي؛ فلا يليق أن يكون صادرا من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص369، تحت «سر استخدام أسلوب النفي على وجه الجحود»","url":""}]},{"id":"s10-49","number":49,"surah":10,"verses":[37],"references":[{"surah":10,"verses":[37]}],"verseLabel":"يونس: 37","question":"لماذا جمع بين ﴿تصديق الذي بين يديه﴾ و﴿تفصيل الكتاب﴾؟","answer":"تصديقه يثبت اتصال الوحي ووحدة أصله، وتفصيله يبين ما يحتاج إليه من العقائد والأحكام؛ فجمع الشهادة لما قبله والبيان لأهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص374، تحت «دلالة عطف التفصيل على التصديق»","url":""}]},{"id":"s10-50","number":50,"surah":10,"verses":[38],"references":[{"surah":10,"verses":[38]}],"verseLabel":"يونس: 38","question":"لماذا تحداهم هنا بالإتيان ﴿بسورة مثله﴾؟","answer":"لما زعموا أن محمدا ﷺ افتراه تحداهم بأقل وحدة مستقلة من جنسه، سورة واحدة، مع دعوة كل من يستطيعون؛ فعجزهم حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص382، تحت «الغرض من التنكير في بسورة»","url":""}]},{"id":"s10-51","number":51,"surah":10,"verses":[39],"references":[{"surah":10,"verses":[39]}],"verseLabel":"يونس: 39","question":"ما النكتة البلاغية في التعبير بما لم يحيطوا بعلمه في قوله تعالى: ﴿بل كذبوا بما لم يحيطوا بعلمه﴾؟","answer":"ذمهم لأنهم بادروا إلى التكذيب قبل تدبر معاني القرآن ومعرفة حججه، فكان إنكارهم صادرا من غير علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص390، تحت «نكتة التعبير بما لم يحيطوا بعلمه»","url":""}]},{"id":"s10-193","number":193,"surah":10,"verses":[39],"references":[{"surah":10,"verses":[39]}],"verseLabel":"يونس: 39","question":"ما سر إيثار ﴿لما﴾ في قوله تعالى: ﴿ولما يأتهم تأويله﴾؟","answer":"تفيد أن تأويل ما أخبر به القرآن لم يأتهم إلى ذلك الوقت مع توقع مجيئه، وفيه إشعار بأن الوقائع ستصدق أخباره.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص391، تحت «سر التعبير بلما وإيثاره»","url":""}]},{"id":"s10-52","number":52,"surah":10,"verses":[40],"references":[{"surah":10,"verses":[40]}],"verseLabel":"يونس: 40","question":"ما دلالة الترتيب في تقسيم الناس في قوله تعالى: ﴿ومنهم من يؤمن به ومنهم من لا يؤمن به﴾؟","answer":"التقسيم يستوعب مآلهم: منهم من سيؤمن أو يصدق باطنا، ومنهم من يصر؛ والله يعلم حقيقة الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص400، تحت «دلالة الترتيب في تقسيم الناس»","url":""}]},{"id":"s10-53","number":53,"surah":10,"verses":[40],"references":[{"surah":10,"verses":[40]}],"verseLabel":"يونس: 40","question":"ما دلالة التذييل بقوله: ﴿وربك أعلم بالمفسدين﴾؟","answer":"فيه وعيد للمصرين على التكذيب، وتقرير أن الله يعلم حقيقة أحوالهم وما يستحقونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص400، تحت «الغرض البلاغي من التذييل بالاعتراض»","url":""}]},{"id":"s10-194","number":194,"surah":10,"verses":[40],"references":[{"surah":10,"verses":[40]}],"verseLabel":"يونس: 40","question":"ما دلالة التعريف في لفظ ﴿المفسدين﴾؟","answer":"يفيد جنس المفسدين ويشمل أصناف الإفساد، فلا يقتصر الوعيد على صورة واحدة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص401، تحت «معنى أل في المفسدين»","url":""}]},{"id":"s10-54","number":54,"surah":10,"verses":[41],"references":[{"surah":10,"verses":[41]}],"verseLabel":"يونس: 41","question":"ما دلالة اللام في قوله تعالى: ﴿لي عملي ولكم عملكم﴾؟","answer":"تختص اللام كل فريق بعمله وجزائه، فلا يحمل الرسول ﷺ عملهم ولا يحملون عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص405، تحت «نكتة التعبير باللام في لي ولكم»","url":""}]},{"id":"s10-195","number":195,"surah":10,"verses":[41],"references":[{"surah":10,"verses":[41]}],"verseLabel":"يونس: 41","question":"لماذا أتبع قوله: ﴿لي عملي ولكم عملكم﴾ بالتصريح بالبراءة؟","answer":"أكدت جملتا البراءة المفاصلة بعد قيام الحجة: لا يؤاخذون بعمل الرسول ﷺ ولا يؤاخذ بعملهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص406، تحت «نكتة فصل أنتم بريئون ودلالته»","url":""}]},{"id":"s10-55","number":55,"surah":10,"verses":[42],"references":[{"surah":10,"verses":[42]}],"verseLabel":"يونس: 42","question":"ما الغرض البلاغي من التعبير بالاستعارة في الصمم في قوله تعالى: ﴿ومنهم من يستمعون إليك أفأنت تسمع الصم ولو كانوا لا يعقلون﴾؟","answer":"سماع الصوت بلا عقل للحق بمنزلة الصمم؛ والاستفهام ينفي قدرة الرسول ﷺ على إسماع هداية لمن عطل أدوات الفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص412، تحت «الغرض من التعبير بالاستعارة الصم»","url":""}]},{"id":"s10-56","number":56,"surah":10,"verses":[43],"references":[{"surah":10,"verses":[43]}],"verseLabel":"يونس: 43","question":"ما وجه البلاغة في الاستعارة العمي في قوله تعالى: ﴿ومنهم من ينظر إليك أفأنت تهدي العمي ولو كانوا لا يبصرون﴾؟","answer":"النظر الظاهر لا ينفع مع عمى البصيرة؛ فلا يملك الرسول ﷺ أن يهدي من اختار ألا يبصر الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص421، تحت «بلاغة الاستعارة العمي»","url":""}]},{"id":"s10-57","number":57,"surah":10,"verses":[44],"references":[{"surah":10,"verses":[44]}],"verseLabel":"يونس: 44","question":"ما دلالة تنكير ﴿شيئا﴾ في قوله تعالى: ﴿إن الله لا يظلم الناس شيئا﴾؟","answer":"يفيد نفي أدنى قدر من الظلم عن الله نفيا شاملا، فلا ينقص أحدا شيئا من حقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص429، تحت «بلاغة تنكير شيئا»","url":""}]},{"id":"s10-196","number":196,"surah":10,"verses":[44],"references":[{"surah":10,"verses":[44]}],"verseLabel":"يونس: 44","question":"ما دلالة تقديم ﴿أنفسهم﴾ في قوله تعالى: ﴿ولكن الناس أنفسهم يظلمون﴾؟","answer":"يبين التقديم أن ضرر الكفر راجع إليهم وأنهم المتسببون في ظلم أنفسهم، لا أن الله ظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص430، تحت «نكتة تقديم المفعول الأول أنفسهم»","url":""}]},{"id":"s10-58","number":58,"surah":10,"verses":[45],"references":[{"surah":10,"verses":[45]}],"verseLabel":"يونس: 45","question":"لماذا يبدو لهم يوم الحشر أنهم لم يلبثوا إلا ساعة من النهار؟","answer":"صوّر قصر مقامهم في الدنيا، أو في القبور على تفسير آخر، كأنه ساعة من النهار إذا قيس بما يستقبلونه من الآخرة. وفي تقليل المدة تحسير لهم على ما فرطوا فيه وإبطال لاغترارهم بطول اللبث.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص441، تحت «نكتة تنكير ساعة»","url":""}]},{"id":"s10-59","number":59,"surah":10,"verses":[46],"references":[{"surah":10,"verses":[46]}],"verseLabel":"يونس: 46","question":"ما دلالة مجيء جواب واحد لجملتي الشرط في قوله تعالى: ﴿وإما نرينك بعض الذي نعدهم أو نتوفينك فإلينا مرجعهم﴾؟","answer":"سواء رأى الرسول ﷺ بعض الوعيد في حياته أو توفاه الله قبله، فمرجعهم إليه والحساب واقع؛ فلا يتعلق صدق الوعد بمشاهدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص456، تحت «دلالة مجيء جواب واحد لجملتي الشرط»","url":""}]},{"id":"s10-60","number":60,"surah":10,"verses":[47],"references":[{"surah":10,"verses":[47]}],"verseLabel":"يونس: 47","question":"ما دلالة جملة الجواب قضي بينهم بالقسط في قوله تعالى: ﴿ولكل أمة رسول فإذا جاء رسولهم قضي بينهم بالقسط﴾؟","answer":"لكل أمة رسول يقيم الحجة، فإذا جاء يوم الفصل قضى بينهم بالعدل؛ فلا عقوبة بلا رسالة ولا محاباة في الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص465، تحت «دلالة جملة الجواب قضي بينهم بالقسط»","url":""}]},{"id":"s10-61","number":61,"surah":10,"verses":[48,49],"references":[{"surah":10,"verses":[48,49]}],"verseLabel":"يونس: 48–49","question":"لماذا سألوا: ﴿متى هذا الوعد﴾ فأجيبوا بأن الرسول لا يملك لنفسه ضرًا ولا نفعًا؟","answer":"لأن سؤالهم كان استعجالًا للوعيد استهزاءً، فجاء الجواب بأن توقيت العذاب ليس إلى الرسول؛ فهو عبد لا يملك الضر والنفع حتى لنفسه، وإنما الأمر كله لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص475، تحت «علة الفصل قل لا أملك»","url":""}]},{"id":"s10-63","number":63,"surah":10,"verses":[50,51],"references":[{"surah":10,"verses":[50,51]}],"verseLabel":"يونس: 50–51","question":"ما علة فصل قوله تعالى: ﴿أثم إذا ما وقع آمنتم به﴾ عما قبله؟","answer":"جاءت الجملة مستأنفة جوابًا عن استعجالهم العذاب، تنكر عليهم تأخير الإيمان حتى وقوعه حين لا ينفع التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص494، تحت «علة الفصل أثم إذا ما وقع آمنتم به»","url":""}]},{"id":"s10-197","number":197,"surah":10,"verses":[50,51],"references":[{"surah":10,"verses":[50,51]}],"verseLabel":"يونس: 50–51","question":"ما غرض الاستفهام في قوله تعالى: ﴿آلآن﴾؟","answer":"هو استفهام إنكاري توبيخي يرد طلب قبول الإيمان بعد وقوع العذاب، لأن زمن الاختيار قد فات.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص496، تحت «غرض الاستفهام ونوعه»","url":""}]},{"id":"s10-64","number":64,"surah":10,"verses":[52],"references":[{"surah":10,"verses":[52]}],"verseLabel":"يونس: 52","question":"ما بلاغة التعبير عن الإحساس بالعذاب بقوله: ﴿ذوقوا﴾؟","answer":"استعير الذوق لمباشرة العذاب وإدراك ألمه إدراكًا محسوسًا، فصوّر شدة اتصاله بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص503، تحت «بلاغة المجاز في التعبير عن الإحساس بالعذاب بتذوقه»","url":""}]},{"id":"s10-198","number":198,"surah":10,"verses":[52],"references":[{"surah":10,"verses":[52]}],"verseLabel":"يونس: 52","question":"ما نكتة إضافة العذاب إلى الخلد في قوله: ﴿عذاب الخلد﴾؟","answer":"تدل الإضافة على أن العذاب ملازم للخلود دائم لا ينقطع، وليس تجربة عابرة تزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص503، تحت «نكتة إضافة العذاب إلى الخلد»","url":""}]},{"id":"s10-65","number":65,"surah":10,"verses":[53],"references":[{"surah":10,"verses":[53]}],"verseLabel":"يونس: 53","question":"لماذا أُمر النبي أن يقسم: ﴿إي وربي إنه لحق﴾؟","answer":"جاء الجواب مفصولًا مستأنفًا ومؤكدًا بالقسم لمواجهة إنكارهم للبعث، فقرر أن الوعد حق لا ريب فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص512، تحت «علة الفصل قل إي وربي»","url":""}]},{"id":"s10-66","number":66,"surah":10,"verses":[54],"references":[{"surah":10,"verses":[54]}],"verseLabel":"يونس: 54","question":"ما دلالة قوله تعالى: ﴿لافتدت به﴾ في تصوير موقف النفس الظالمة يوم القيامة؟","answer":"تصور المفردة أن النفس، لو ملكت جميع ما في الأرض، لبذلته كله فداءً من العذاب؛ وفي ذلك تهويل للموقف وإسقاط لقيمة الدنيا عند معاينة الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص526، تحت «دلالة مفردة الافتداء في لافتدت به»","url":""}]},{"id":"s10-67","number":67,"surah":10,"verses":[54],"references":[{"surah":10,"verses":[54]}],"verseLabel":"يونس: 54","question":"ما سرّ إيثار ﴿أسروا﴾ في قوله تعالى: ﴿وأسروا الندامة لما رأوا العذاب﴾؟","answer":"يصور اللفظ شدة الندم الذي استقر في نفوسهم عند معاينة العذاب؛ فقيل إنهم كتموه من شدة البهت، وقيل أظهروه، واللفظ يحتمل الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص527، تحت «نكتة إيثار فعل أسروا»","url":""}]},{"id":"s10-68","number":68,"surah":10,"verses":[55],"references":[{"surah":10,"verses":[55]}],"verseLabel":"يونس: 55","question":"لماذا كرر ﴿ألا﴾ في: ﴿ألا إن لله ما في السماوات والأرض ألا إن وعد الله حق﴾؟","answer":"أعيد حرف التنبيه لأن كل جملة تقرر حقيقة عظيمة مستقلة: ملك الله التام، وصدق وعده؛ فاستحق كل خبر تنبيهًا جديدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص542، تحت «نكتة إعادة حرف التنبيه»","url":""}]},{"id":"s10-69","number":69,"surah":10,"verses":[56],"references":[{"surah":10,"verses":[56]}],"verseLabel":"يونس: 56","question":"ما بلاغة ترتيب قوله تعالى: ﴿هو يحيي ويميت وإليه ترجعون﴾؟","answer":"رتبت الآية أطوار الخلق والمصير: الإحياء ثم الإماتة ثم الرجوع إلى الله، فجمعت بدء الحياة ونهايتها والبعث للحساب في نسق موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص549، تحت «بلاغة الترتيب»","url":""}]},{"id":"s10-70","number":70,"surah":10,"verses":[57],"references":[{"surah":10,"verses":[57]}],"verseLabel":"يونس: 57","question":"لماذا وصف القرآن بأنه ﴿موعظة﴾ و﴿شفاء﴾ و﴿هدى﴾ و﴿رحمة﴾ بهذا الترتيب؟","answer":"رتبت الأوصاف من إزالة الشر إلى تحصيل الخير: الموعظة تزجر، والشفاء يزيل أمراض القلب، والهدى يدل على الطريق، والرحمة ثمرة ذلك كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص561، تحت «العطف بالواو وسر ترتيب المعطوفات»","url":""}]},{"id":"s10-71","number":71,"surah":10,"verses":[57],"references":[{"surah":10,"verses":[57]}],"verseLabel":"يونس: 57","question":"ما الغرض من وصف القرآن بأنه ﴿شفاء﴾؟","answer":"استعير الشفاء لإزالة القرآن أمراض القلوب من الشك والاعتقاد الفاسد والخلق المذموم، كما يزيل الدواء مرض البدن.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص563، تحت «الغرض من التعبير بالاستعارة وشفاء»","url":""}]},{"id":"s10-199","number":199,"surah":10,"verses":[57],"references":[{"surah":10,"verses":[57]}],"verseLabel":"يونس: 57","question":"لماذا خُصت الصدور بالذكر في قوله: ﴿شفاء لما في الصدور﴾؟","answer":"خُصت لأنها موضع القلوب ومستودع الاعتقاد والخواطر؛ فالتعبير يصور تمكن الداء الباطن وكمال علاج القرآن له.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص565، تحت «فائدة تخصيص الصدور بالذكر»","url":""}]},{"id":"s10-72","number":72,"surah":10,"verses":[58],"references":[{"surah":10,"verses":[58]}],"verseLabel":"يونس: 58","question":"ما غرض تقديم ﴿بفضل الله وبرحمته﴾ في الآية؟","answer":"يفيد الاهتمام والحصر؛ فالفضل والرحمة هما السبب الحق الذي ينبغي أن يكون به الفرح.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص572، تحت «غرض تقديم الجار والمجرور»","url":""}]},{"id":"s10-200","number":200,"surah":10,"verses":[58],"references":[{"surah":10,"verses":[58]}],"verseLabel":"يونس: 58","question":"ما معنى الفاء في قوله: ﴿فبذلك فليفرحوا﴾؟","answer":"الأولى تفريع للفرح على فضل الله ورحمته، والثانية رابطة لجواب الأمر، فتؤكد اتصال الفرح بسببه الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص574، تحت «معنى الفاء في فبذلك وفليفرحوا»","url":""}]},{"id":"s10-201","number":201,"surah":10,"verses":[58],"references":[{"surah":10,"verses":[58]}],"verseLabel":"يونس: 58","question":"لماذا أشير إلى فضل الله ورحمته باسم الإشارة للبعيد في قوله: ﴿فبذلك﴾؟","answer":"استعمل اسم الإشارة للبعيد لتعظيم المشار إليه ورفع منزلته، أي بهذا الفضل العظيم والرحمة الجليلة فليفرحوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص575، تحت «الغرض من التعبير باسم الإشارة للبعيد»","url":""}]},{"id":"s10-73","number":73,"surah":10,"verses":[58],"references":[{"surah":10,"verses":[58]}],"verseLabel":"يونس: 58","question":"لماذا قيل: ﴿هو خير مما يجمعون﴾ لا «مما يملكون»؟","answer":"الفعل المضارع يصور تجدد جمع متاع الدنيا واستمرار الحرص عليه، ثم يقرر أن فضل الله ورحمته خير من كل ما يتجدد جمعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص580، تحت «بلاغة التعبير بالفعل المضارع في مما يجمعون»","url":""}]},{"id":"s10-74","number":74,"surah":10,"verses":[59],"references":[{"surah":10,"verses":[59]}],"verseLabel":"يونس: 59","question":"ما نكتة التعبير بالإنزال في قوله: ﴿ما أنزل الله لكم من رزق﴾؟","answer":"يفيد أن الرزق عطاء نازل من عند الله وتقدير منه، فلا يملك البشر أن يحللوا أو يحرموا منه بغير إذنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص589، تحت «نكتة التعبير بالإنزال أنزل»","url":""}]},{"id":"s10-202","number":202,"surah":10,"verses":[59],"references":[{"surah":10,"verses":[59]}],"verseLabel":"يونس: 59","question":"ما دلالة الفاء في قوله: ﴿فجعلتم منه حرامًا وحلالًا﴾؟","answer":"تفيد ترتب تصرفهم الباطل مباشرة على رزق الله، فتفضح سرعة مقابلتهم النعمة بالتحكم والتحريم بلا إذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص592، تحت «دلالة الفاء في فجعلتم»","url":""}]},{"id":"s10-75","number":75,"surah":10,"verses":[59],"references":[{"surah":10,"verses":[59]}],"verseLabel":"يونس: 59","question":"لماذا خُتم السؤال بـ﴿آلله أذن لكم أم على الله تفترون﴾؟","answer":"الاستفهام إنكاري حجاجي يحصر الأمر في إذن من الله أو افتراء عليه؛ ولما لم يكن لهم إذن ثبت بطلان تحريمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص594، تحت «غرض الاستفهام في قل آلله أذن لكم»","url":""}]},{"id":"s10-76","number":76,"surah":10,"verses":[60],"references":[{"surah":10,"verses":[60]}],"verseLabel":"يونس: 60","question":"ما غرض الاستفهام في قوله تعالى: ﴿وما ظن الذين يفترون على الله الكذب يوم القيامة﴾؟","answer":"يفيد التهويل والوعيد: أيّ ظنّ لهم بمصيرهم وعقابهم حين يقفون بين يدي الله وينكشف افتراؤهم؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص603، تحت «الغرض من التعبير بالاستفهام في وما»","url":""}]},{"id":"s10-77","number":77,"surah":10,"verses":[61],"references":[{"surah":10,"verses":[61]}],"verseLabel":"يونس: 61","question":"ما فائدة عطف قوله: ﴿وما تتلو منه من قرآن﴾ على قوله: ﴿وما تكون في شأن﴾؟","answer":"خُصت تلاوة القرآن بعد عموم شؤون النبي ﷺ تشريفًا لها وتنبيهًا إلى عظم منزلتها مع دخولها في علم الله وشهوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص621، تحت «فائدة عطف وما تتلو منه من قرآن»","url":""}]},{"id":"s10-203","number":203,"surah":10,"verses":[61],"references":[{"surah":10,"verses":[61]}],"verseLabel":"يونس: 61","question":"ما بلاغة الالتفات من خطاب النبي ﷺ إلى الجمع في قوله: ﴿ولا تعملون من عمل﴾؟","answer":"انتقل الخطاب من النبي ﷺ إلى الأمة لتعميم إحاطة العلم والشهادة بكل أعمال المكلفين، فلا يختص المعنى بحال الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص625، تحت «بلاغة الالتفات»","url":""}]},{"id":"s10-204","number":204,"surah":10,"verses":[61],"references":[{"surah":10,"verses":[61]}],"verseLabel":"يونس: 61","question":"ما نكتة التعبير بـ﴿شهودًا﴾ في قوله: ﴿إلا كنا عليكم شهودًا﴾؟","answer":"صيغة الجمع تفيد تعدد جهات الشهادة والإحاطة بكل عمل حال مباشرته، فلا يغيب عن علم الله شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص630، تحت «نكتة استعمال جمع فعول شهودا»","url":""}]},{"id":"s10-78","number":78,"surah":10,"verses":[61],"references":[{"surah":10,"verses":[61]},{"surah":34,"verses":[3]}],"verseLabel":"يونس: 61؛ سبأ: 3","question":"ما وجه التشابه واختلاف السياق بين نفي عزوب مثقال الذرة عن علم الله في سورتي يونس وسبأ؟","answer":"تقرر الآيتان إحاطة علم الله بأدق الموجودات. جاءت آية يونس في سياق مراقبة أعمال العباد والشهادة عليها، وجاءت آية سبأ في سياق إثبات البعث والجزاء؛ فلا تغيب الأعمال عن علمه، ولا تضيع أجزاء الخلق عند الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص636، تحت «توجيه التشابه اللفظي بين آيتي سورة يونس وسبأ»","url":""}]},{"id":"s10-79","number":79,"surah":10,"verses":[62,63],"references":[{"surah":10,"verses":[62,63]}],"verseLabel":"يونس: 62–63","question":"لماذا عُبّر عن إيمان أولياء الله بالماضي وعن تقواهم بالمضارع في قوله: ﴿الذين آمنوا وكانوا يتقون﴾؟","answer":"الماضي يدل على تحقق أصل الإيمان وثباته، والمضارع يصور تجدد التقوى واستمرارها؛ فالولاية تقوم على إيمان راسخ وطاعة متواصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص653، تحت «سر التعبير عن الإيمان بالماضي وعن التقوى بالمضارع»","url":""}]},{"id":"s10-81","number":81,"surah":10,"verses":[64],"references":[{"surah":10,"verses":[64]}],"verseLabel":"يونس: 64","question":"ما المقصود بالبشرى لأولياء الله في الحياة الدنيا وفي الآخرة؟","answer":"تشمل في الدنيا ما يثبتهم من الرؤيا الصالحة والبشارة والذكر الحسن، وفي الآخرة بشارة الملائكة والجنة والرضوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص660، تحت «المعنى الإجمالي»","url":""}]},{"id":"s10-82","number":82,"surah":10,"verses":[65],"references":[{"surah":10,"verses":[65]}],"verseLabel":"يونس: 65","question":"لماذا قيل للنبي ﷺ: ﴿ولا يحزنك قولهم إن العزة لله جميعًا﴾؟","answer":"جاءت جملة ﴿إن العزة لله جميعًا﴾ مستأنفة تعليلًا للنهي عن الحزن؛ فأقوالهم لا تنقص الحق، لأن الغلبة والقوة كلها لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص676، تحت «سر الفصل في إن العزة»","url":""}]},{"id":"s10-84","number":84,"surah":10,"verses":[66],"references":[{"surah":10,"verses":[66]}],"verseLabel":"يونس: 66","question":"ما دلالة التعبير بالظن في قوله: ﴿إن يتبعون إلا الظن﴾؟","answer":"يدل على أن شركهم لا يقوم على علم أو حجة، وإنما غايته توهم غير موثوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص695، تحت «دلالة التعبير بالظن ووقوع مفعوليته»","url":""}]},{"id":"s10-205","number":205,"surah":10,"verses":[66],"references":[{"surah":10,"verses":[66]}],"verseLabel":"يونس: 66","question":"ما دلالة استعمال يخرصون في قوله تعالى: ﴿وإن هم إلا يخرصون﴾؟","answer":"الخرص قول بالتخمين الذي لا يستند إلى علم، وقد يفضي إلى الكذب؛ فالتعبير يبطل دعاواهم من أصلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص696، تحت «دلالة استعمال يخرصون»","url":""}]},{"id":"s10-85","number":85,"surah":10,"verses":[67],"references":[{"surah":10,"verses":[67]}],"verseLabel":"يونس: 67","question":"ما دلالة الاحتباك في قوله تعالى: ﴿جعل لكم الليل لتسكنوا فيه والنهار مبصرًا﴾؟","answer":"في الآية احتباك: دل ذكر السكون مع الليل على حذف الحركة في النهار، ودل وصف النهار بالإبصار على حذف ظلمة الليل؛ فجمع التعبير نعمتَي الراحة والعمل بإيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص702، تحت «دلالة الاحتباك»","url":""}]},{"id":"s10-86","number":86,"surah":10,"verses":[67],"references":[{"surah":10,"verses":[67]}],"verseLabel":"يونس: 67","question":"لماذا خُتمت الآية بقوله: ﴿لقوم يسمعون﴾؟","answer":"خُص السمع لأن هذه الدلائل يبلّغها الوحي والموعظة، وإنما ينتفع بها من يسمع سماع تدبر وقبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص706، تحت «دلالة السمع وغرض تخصيصه»","url":""}]},{"id":"s10-87","number":87,"surah":10,"verses":[68],"references":[{"surah":10,"verses":[68]}],"verseLabel":"يونس: 68","question":"لماذا رد على قولهم: ﴿اتخذ الله ولدًا﴾ بقوله: ﴿سبحانه هو الغني﴾؟","answer":"نزّه الله نفسه عن قولهم، ثم أبطل دعواهم بغناه المطلق؛ فالولد إنما يُطلب لحاجة أو معونة أو بقاء نسل، والله غني عن ذلك كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص718، تحت «دلائل استحالة أن يكون لله تعالى ولد»","url":""}]},{"id":"s10-88","number":88,"surah":10,"verses":[68],"references":[{"surah":10,"verses":[68]}],"verseLabel":"يونس: 68","question":"ما دلالة الاستفهام في قوله تعالى: ﴿أتقولون على الله ما لا تعلمون﴾؟","answer":"الاستفهام للإنكار والتوبيخ على نسبة أعظم الدعوى إلى الله بلا علم ولا سلطان؛ فهو يفضح افتراءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص723، تحت «دلالة الاستفهام في الآية»","url":""}]},{"id":"s10-89","number":89,"surah":10,"verses":[69,70],"references":[{"surah":10,"verses":[69,70]}],"verseLabel":"يونس: 69–70","question":"ما دلالة ترتيب مصير المفترين: متاع في الدنيا، ثم الرجوع إلى الله، ثم العذاب؟","answer":"يرتقي السياق من متاع قصير إلى الرجوع المحتوم ثم الجزاء الأليم؛ فيبين أن ظاهر النعمة العاجلة لا يناقض خسرانهم النهائي.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص735، تحت «دلالة الترقي في الترتيب الزمني: المتاع، المرجع، الجزاء»","url":""}]},{"id":"s10-90","number":90,"surah":10,"verses":[71],"references":[{"surah":10,"verses":[71]}],"verseLabel":"يونس: 71","question":"ما دلالة قول نوح: ﴿إن كان كبر عليكم مقامي وتذكيري بآيات الله﴾؟","answer":"جعل المقام والتذكير مما يكبر ويثقل مجازًا، تصويرًا لشدة مشقة بقائه بينهم ودوام دعوته عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص751، تحت «بلاغة المجاز في كبر عليكم مقامي»","url":""}]},{"id":"s10-91","number":91,"surah":10,"verses":[71],"references":[{"surah":10,"verses":[71]}],"verseLabel":"يونس: 71","question":"ما دلالة أمر نوح قومه بقوله: ﴿فأجمعوا أمركم﴾؟","answer":"الأمر للتحدي والتعجيز: أحكموا تدبيركم واعزموا عليه مجتمعين، فلن تستطيعوا الإضرار به مع توكله على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص756، تحت «دلالة لفظ فأجمعوا»","url":""}]},{"id":"s10-206","number":206,"surah":10,"verses":[71],"references":[{"surah":10,"verses":[71]}],"verseLabel":"يونس: 71","question":"ما الغرض البلاغي من الاستعارة التصريحية في الآية في قوله تعالى: ﴿ثم لا يكن أمركم عليكم غمة﴾؟","answer":"استعيرت الغمة للأمر الخفي الملتبس؛ أي اجعلوا تدبيركم واضحًا محكمًا لا خفاء فيه، مبالغة في تحديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص760، تحت «الغرض من الاستعارة التصريحية في الآية»","url":""}]},{"id":"s10-207","number":207,"surah":10,"verses":[71],"references":[{"surah":10,"verses":[71]}],"verseLabel":"يونس: 71","question":"ما دلالة قوله: ﴿ولا تنظرون﴾ في تحدي نوح لقومه؟","answer":"طلب منهم ألا يمهلوه، زيادة في إظهار ثقته بالله وتعجيزهم عن تنفيذ تهديدهم ولو اجتمعوا وعجلوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص761، تحت «دلالة النهي في ولا تنظرون»","url":""}]},{"id":"s10-92","number":92,"surah":10,"verses":[72],"references":[{"surah":10,"verses":[72]}],"verseLabel":"يونس: 72","question":"ما دلالة النفي في قول نوح: ﴿فما سألتكم من أجر﴾؟","answer":"نفى أن يكون قد طلب منهم أي أجر، ليقطع تهمة المنفعة الشخصية ويثبت إخلاص دعوته لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص768، تحت «دلالة النفي بلفظ ما»","url":""}]},{"id":"s10-93","number":93,"surah":10,"verses":[73],"references":[{"surah":10,"verses":[73]}],"verseLabel":"يونس: 73","question":"ما دلالة الفاء في قوله: ﴿فكذبوه فنجيناه﴾؟","answer":"تفيد ترتيب استمرارهم على التكذيب على دعوة نوح، ثم ترتيب نجاته والمؤمنين على بلوغ التكذيب غايته وحلول الإغراق.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص778، تحت «دلالة الفاء في فكذبوه وفنجيناه»","url":""}]},{"id":"s10-208","number":208,"surah":10,"verses":[73],"references":[{"surah":10,"verses":[73]}],"verseLabel":"يونس: 73","question":"لماذا لم يكتف بذكر نجاة نوح ومن معه، بل قال: ﴿وجعلناهم خلائف﴾؟","answer":"زيادة جعلهم خلائف تتميم للنعمة؛ فلم ينجوا فحسب، بل أورثهم الله الأرض بعد هلاك المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص781، تحت «بلاغة الإطناب بجعلهم خلائف وعدم الاكتفاء بالنجاة»","url":""}]},{"id":"s10-94","number":94,"surah":10,"verses":[74],"references":[{"surah":10,"verses":[74]}],"verseLabel":"يونس: 74","question":"ما دلالة قوله تعالى عن الأمم بعد نوح: ﴿فما كانوا ليؤمنوا بما كذبوا به من قبل﴾؟","answer":"يدل على رسوخ تكذيبهم واستمرارهم عليه؛ فقد سبق منهم التكذيب ثم أصروا عليه بعد مجيء البينات حتى صار مانعًا من الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص790، تحت «دلالة تأصل الكفر قبل مجيء الرسل وبعده»","url":""}]},{"id":"s10-95","number":95,"surah":10,"verses":[75],"references":[{"surah":10,"verses":[75]}],"verseLabel":"يونس: 75","question":"ما دلالة العطف بـ﴿ثم﴾ في قوله: ﴿ثم بعثنا من بعدهم موسى وهارون﴾؟","answer":"تفيد التراخي الزمني بعد الرسل السابقين، وتوحي كذلك بالتراخي الرتبي لعظم شأن بعثة موسى وهارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص796، تحت «دلالة العطف بالحرف ثم»","url":""}]},{"id":"s10-209","number":209,"surah":10,"verses":[75],"references":[{"surah":10,"verses":[75]}],"verseLabel":"يونس: 75","question":"لماذا قُدّم موسى على هارون في قوله: ﴿موسى وهارون﴾؟","answer":"قُدم موسى لأنه المبعوث أصالة والمتولي مواجهة فرعون، وكان هارون وزيرًا مؤازرًا له في الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص797، تحت «علة التقديم في موسى وهارون»","url":""}]},{"id":"s10-210","number":210,"surah":10,"verses":[75],"references":[{"surah":10,"verses":[75]}],"verseLabel":"يونس: 75","question":"لماذا خُص فرعون وملؤه بالذكر في بعثة موسى وهارون؟","answer":"لأنهم رؤوس القوم وأصحاب السلطان والتأثير، وباستجابتهم أو استكبارهم يتبعهم عامة الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص799، تحت «دلالة اختصاص ذكر فئة الملأ»","url":""}]},{"id":"s10-211","number":772,"surah":10,"verses":[76],"references":[{"surah":10,"verses":[76]}],"verseLabel":"يونس: 76","question":"لماذا صوّر القرآن وصول الحق بقوله: ﴿فلما جاءهم الحق﴾، لا بمجرد ظهوره لهم؟","answer":"في لفظ المجيء تصوير للحق كأنه وافاهم وطرق أسماعهم وحضر بينهم بحجته، فكان ردّهم عليه بعد وصوله إصرارًا لا جهلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص10، تحت «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s10-212","number":773,"surah":10,"verses":[76,77],"references":[{"surah":10,"verses":[76,77]}],"verseLabel":"يونس: 76، 77","question":"ما الذي تكشفه سرعة قولهم: ﴿إن هذا لسحر مبين﴾ بعد مجيء الحق مباشرة؟","answer":"تكشف المبادرة عن أنهم لم يتأملوا البرهان، بل انتقلوا من الاستكبار إلى البهتان، فصار التكذيب عندهم ردّ فعل مقصودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص10، تحت «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s10-213","number":774,"surah":10,"verses":[77],"references":[{"surah":10,"verses":[77]}],"verseLabel":"يونس: 77","question":"لماذا جاء جواب موسى في صورة سؤالين: ﴿أتقولون للحق لما جاءكم أسحر هذا﴾؟","answer":"جاء الاستفهام إنكارًا لخلطهم بين الحق والسحر، وإلزامًا لهم أن يجيبوا عن حقيقة ما عاينوه بدل الاكتفاء بالدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص19، تحت «التشابه اللفظي»","url":""}]},{"id":"s10-214","number":775,"surah":10,"verses":[77],"references":[{"surah":10,"verses":[77]}],"verseLabel":"يونس: 77","question":"لماذا قال السحرة: ﴿أسحر هذا﴾، فجاء اسم الإشارة بعد كلمة السحر؟","answer":"في هذا التركيب واجه موسى دعواهم بقلبها عليهم: أتسمّون هذا الحق سحرًا؟ فجاء ﴿هذا﴾ للإشارة إلى الشيء المشاهد الحاضر أمامهم، لا إلى سحر متخيّل أو خبر منقول. ولذلك كان السؤال أبلغ في إلزامهم بما رأوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص20، تحت «التقديم في ﴿أسحر هذا﴾»","url":""}]},{"id":"s10-215","number":776,"surah":10,"verses":[78],"references":[{"surah":10,"verses":[78]}],"verseLabel":"يونس: 78","question":"لماذا قالوا: ﴿أجئتنا لتلفتنا عما وجدنا عليه آباءنا﴾ بدل أن يناقشوا الحجة نفسها؟","answer":"حوّلوا الكلام من دليل الرسالة إلى عادات الآباء؛ لأن مواجهة البرهان أعجزتهم، فاستنجدوا بالمألوف وبسلطة الموروث.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص23، تحت «دلالة التعبير بصيغة ﴿قالوا﴾»","url":""}]},{"id":"s10-216","number":777,"surah":10,"verses":[79],"references":[{"surah":10,"verses":[79]}],"verseLabel":"يونس: 79","question":"لماذا قال فرعون: ﴿ائتوني بكل ساحر عليم﴾، فجمع بين العموم و﴿عليم﴾؟","answer":"أراد استنفار كل من يقدر على المواجهة، ووصفه بالعلم ليصوّر أن القضية تحتاج إلى خبرة تقهر ما جاء به موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص33، تحت «صيغة ﴿عليم﴾ في قوله ﴿بكل ساحر عليم﴾»","url":""}]}]);
